// ─── 工具函式 ────────────────────────────────────────────────────────────────

function delay(ms: number) {
  return new Promise((r) => setTimeout(r, ms));
}

function parseDataUrlImage(dataUrl: string): { mimeType: string; base64: string } | null {
  const parsed = parseDataUrlMedia(dataUrl);
  if (!parsed || !parsed.mimeType.startsWith("image/")) return null;
  return parsed;
}

function hasImageReferenceMedia(mediaUrl?: string): boolean {
  return Boolean(mediaUrl) && !isVideoMediaUrl(mediaUrl);
}

function getDeviceMediaLabel(mediaUrl: string): "圖片" | "影片" {
  return isVideoMediaUrl(mediaUrl) ? "影片" : "圖片";
}

function createTimeoutSignal(timeoutMs: number): { signal: AbortSignal; cleanup: () => void } {
  const controller = new AbortController();
  const timer = globalThis.setTimeout(() => controller.abort(new Error(`timeout:${timeoutMs}`)), timeoutMs);
  return {
    signal: controller.signal,
    cleanup: () => globalThis.clearTimeout(timer),
  };
}

async function withTimeout<T>(promise: Promise<T>, timeoutMs: number, message: string): Promise<T> {
  let timer: ReturnType<typeof globalThis.setTimeout> | undefined;
  try {
    return await Promise.race([
      promise,
      new Promise<never>((_, reject) => {
        timer = globalThis.setTimeout(() => reject(new Error(message)), timeoutMs);
      }),
    ]);
  } finally {
    if (timer) globalThis.clearTimeout(timer);
  }
}

function remainingDeadlineMs(deadlineAt?: number, reserveMs = 0): number | null {
  if (typeof deadlineAt !== "number" || !Number.isFinite(deadlineAt)) return null;
  return Math.max(0, Math.floor(deadlineAt - Date.now() - reserveMs));
}

function throwIfDeadlineExceeded(deadlineAt?: number, message = "threadsAutoReply collect comments timeout"): void {
  const remaining = remainingDeadlineMs(deadlineAt);
  if (remaining !== null && remaining <= 0) throw new Error(message);
}

async function callPublishVerifier(
  contents: any[],
  generationConfig: Record<string, any> = { maxOutputTokens: 120, temperature: 0 },
  timeoutMs = 12_000,
) {
  const request = createTimeoutSignal(timeoutMs);
  try {
    return await callGemini(
      PUBLISH_VERIFY_MODEL,
      contents,
      generationConfig,
      request.signal,
    );
  } finally {
    request.cleanup();
  }
}

function rethrowThreadsTerminalError(error: unknown): void {
  const msg = error instanceof Error ? error.message : String(error);
  if (msg.startsWith("__THREADS_BLOCKED__") || msg.startsWith("__THREADS_STILL_COMPOSING__")) {
    throw error instanceof Error ? error : new Error(msg);
  }
}

function isPublishVerifierAuthError(message: string): boolean {
  return /401|unauthorized|invalid token|invalid api key|無效的令牌|无效的令牌|API key/i.test(message);
}

function inferMediaExtension(mediaUrl: string): string {
  return getMediaExtension(mediaUrl);
}

const VMOS_MEDIA_STAGING_ROUTE = (process.env.VMOS_MEDIA_STAGING_ROUTE || "/tool_r18_uploads").replace(/\/+$/, "") || "/tool_r18_uploads";
const DEVICE_MEDIA_STAGING_CACHE_FILE = path.join(
  process.cwd(),
  ".runtime",
  "automatic-script",
  "device-media-staging-cache.json",
);

type DeviceMediaStagingCacheEntry = {
  key: string;
  padCode: string;
  mediaHash: string;
  mediaKind: "image" | "video";
  remotePath: string;
  updatedAt: string;
};

const stagedMediaContentUriCache = new Map<string, string>();

function hashString(value: string, length = 24): string {
  return crypto.createHash("sha256").update(value).digest("hex").slice(0, length);
}

function getDeviceMediaStagingKey(padCode: string, mediaUrl: string): string {
  return `${padCode}:${isVideoMediaUrl(mediaUrl) ? "video" : "image"}:${hashString(mediaUrl, 32)}`;
}

function buildStableDeviceMediaRemotePath(prefix: string, mediaUrl: string): string {
  const ext = inferMediaExtension(mediaUrl);
  const mediaHash = hashString(mediaUrl, 20);
  return `/sdcard/Download/${prefix}_${mediaHash}.${ext}`;
}

function resolveLocalMediaFilePath(mediaUrl: string): string | null {
  if (!mediaUrl || /^(https?:\/\/|data:)/i.test(mediaUrl)) return null;
  const candidates = [
    mediaUrl,
    path.isAbsolute(mediaUrl) ? mediaUrl : path.resolve(process.cwd(), mediaUrl),
  ];
  for (const candidate of candidates) {
    try {
      if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) return candidate;
    } catch {
      // Ignore inaccessible candidates and try the next one.
    }
  }
  return null;
}

function inferLocalMediaMimeType(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  if (ext === ".png") return "image/png";
  if (ext === ".webp") return "image/webp";
  if (ext === ".gif") return "image/gif";
  if (ext === ".mp4" || ext === ".m4v") return "video/mp4";
  if (ext === ".webm") return "video/webm";
  if (ext === ".mov") return "video/quicktime";
  return isVideoMediaUrl(filePath) ? "video/mp4" : "image/jpeg";
}

function getVmosMediaStagingDir(): string {
  const configured = process.env.VMOS_MEDIA_STAGING_DIR || process.env.TOOL_R18_UPLOAD_HOST_DIR;
  if (configured) return path.resolve(configured);
  const webappDataDir = (process.env.WEBAPP_DATA_DIR || "").trim();
  if (webappDataDir) {
    return path.resolve(webappDataDir, "tool_r18_uploads");
  }
  const projectRoot = path.basename(process.cwd()).toLowerCase() === "tool_r18"
    ? process.cwd()
    : fs.existsSync(path.join(process.cwd(), "tool_r18", "package.json"))
      ? path.join(process.cwd(), "tool_r18")
      : process.cwd();
  return path.resolve(path.dirname(projectRoot), "webapp_data", "tool_r18_uploads");
}

function getVmosMediaStagingPublicBaseUrl(): string {
  const base = (
    process.env.VMOS_MEDIA_STAGING_PUBLIC_BASE_URL
    || process.env.TOOL_R18_PUBLIC_URL
    || process.env.PUBLIC_BASE_URL
    || "http://43.167.237.120"
  ).trim();
  return base.replace(/\/+$/, "");
}

function isUsableVmosMediaStagingBaseUrl(baseUrl: string): boolean {
  if (!baseUrl) return false;
  try {
    const parsed = new URL(baseUrl);
    if (!/^https?:$/i.test(parsed.protocol)) return false;
    const host = parsed.hostname.toLowerCase();
    if (process.env.VMOS_MEDIA_STAGING_ALLOW_LOCALHOST === "1") return true;
    return !["localhost", "127.0.0.1", "::1", "0.0.0.0"].includes(host);
  } catch {
    return false;
  }
}

function buildVmosStagingPublicUrl(fileName: string): string | null {
  const baseUrl = getVmosMediaStagingPublicBaseUrl();
  if (!isUsableVmosMediaStagingBaseUrl(baseUrl)) return null;
  return `${baseUrl}${VMOS_MEDIA_STAGING_ROUTE}/${encodeURIComponent(fileName)}`;
}

type SshMediaStagingConfig = {
  host: string;
  user: string;
  password: string;
  remoteDir: string;
  python: string;
};

function getDefaultSshMediaStagingPython(): string {
  const repoRoot = path.resolve(process.cwd(), "..");
  const windowsPython = path.join(repoRoot, ".venv-codex-run", "Scripts", "python.exe");
  if (fs.existsSync(windowsPython)) return windowsPython;
  return process.platform === "win32" ? "python" : "python3";
}

function getSshMediaStagingConfig(): SshMediaStagingConfig | null {
  const host = (process.env.VMOS_MEDIA_STAGING_SSH_HOST || process.env.REVERSE_TUNNEL_SSH_HOST || "").trim();
  const user = (process.env.VMOS_MEDIA_STAGING_SSH_USER || process.env.REVERSE_TUNNEL_SSH_USER || "").trim();
  const password = process.env.VMOS_MEDIA_STAGING_SSH_PASSWORD || process.env.REVERSE_TUNNEL_SSH_PASSWORD || "";
  const remoteDir = (process.env.VMOS_MEDIA_STAGING_REMOTE_DIR || "").trim();
  if (!host || !user || !password || !remoteDir) return null;
  return {
    host,
    user,
    password,
    remoteDir: remoteDir.replace(/\/+$/, ""),
    python: (process.env.VMOS_MEDIA_STAGING_SSH_PYTHON || getDefaultSshMediaStagingPython()).trim(),
  };
}

function uploadVmosStagedFileBySsh(localPath: string, fileName: string): void {
  const config = getSshMediaStagingConfig();
  if (!config) return;

  const script = String.raw`
import os
import posixpath
import sys
import paramiko

local_path, remote_dir, file_name = sys.argv[1:4]
host = os.environ["VMOS_MEDIA_STAGING_SSH_HOST"]
user = os.environ["VMOS_MEDIA_STAGING_SSH_USER"]
password = os.environ["VMOS_MEDIA_STAGING_SSH_PASSWORD"]

client = paramiko.SSHClient()
client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
client.connect(
    hostname=host,
    username=user,
    password=password,
    timeout=20,
    banner_timeout=20,
    auth_timeout=20,
    look_for_keys=False,
    allow_agent=False,
)
try:
    sftp = client.open_sftp()
    try:
        current = ""
        for part in remote_dir.strip("/").split("/"):
            if not part:
                continue
            current += "/" + part
            try:
                sftp.mkdir(current)
            except OSError:
                pass
        remote_path = posixpath.join(remote_dir, file_name)
        sftp.put(local_path, remote_path)
        try:
            sftp.chmod(remote_path, 0o644)
        except OSError:
            pass
        print(remote_path)
    finally:
        sftp.close()
finally:
    client.close()
`;

  const result = spawnSync(config.python, ["-c", script, localPath, config.remoteDir, fileName], {
    encoding: "utf8",
    timeout: Number(process.env.VMOS_MEDIA_STAGING_SSH_TIMEOUT_MS || "120000"),
    env: {
      ...process.env,
      VMOS_MEDIA_STAGING_SSH_HOST: config.host,
      VMOS_MEDIA_STAGING_SSH_USER: config.user,
      VMOS_MEDIA_STAGING_SSH_PASSWORD: config.password,
    },
  });
  if (result.error) {
    throw new Error(`SSH 上傳媒體失敗：${result.error.message}`);
  }
  if (result.status !== 0) {
    const detail = (result.stderr || result.stdout || `exit ${result.status}`).trim();
    throw new Error(`SSH 上傳媒體失敗：${detail}`);
  }
}

async function fetchWithTimeout(
  url: string,
  init: RequestInit,
  timeoutMs: number,
): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(url, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

async function checkPublicMediaReachability(publicUrl: string): Promise<{ ok: boolean; detail: string }> {
  const failures: string[] = [];
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    try {
      const head = await fetchWithTimeout(publicUrl, { method: "HEAD" }, 15000);
      if (head.ok) return { ok: true, detail: `HEAD ${head.status}` };
      failures.push(`attempt ${attempt} HEAD ${head.status}`);
    } catch (error) {
      failures.push(`attempt ${attempt} HEAD ${error instanceof Error ? error.message : String(error)}`);
    }

    try {
      const response = await fetchWithTimeout(publicUrl, {
        method: "GET",
        headers: { Range: "bytes=0-1023" },
      }, 20000);
      await response.body?.cancel();
      if (response.ok || response.status === 206) return { ok: true, detail: `GET ${response.status}` };
      failures.push(`attempt ${attempt} GET ${response.status}`);
    } catch (error) {
      failures.push(`attempt ${attempt} GET ${error instanceof Error ? error.message : String(error)}`);
    }

    if (attempt < 3) await delay(600 * attempt);
  }
  return { ok: false, detail: failures.join("; ") || "unknown error" };
}

function isTelegramFileMediaUrl(mediaUrl: string): boolean {
  try {
    const parsed = new URL(mediaUrl);
    return parsed.protocol === "https:"
      && parsed.hostname.toLowerCase() === "api.telegram.org"
      && /^\/file\/bot/i.test(parsed.pathname);
  } catch {
    return false;
  }
}

function getTelegramMediaProxyUrl(): string {
  const raw = String(
    process.env.TELEGRAM_PROXY_URL
      || process.env.HTTPS_PROXY
      || process.env.HTTP_PROXY
      || process.env.ALL_PROXY
      || (process.platform === "win32" ? "http://127.0.0.1:9974" : ""),
  ).trim();
  if (!raw || raw.toLowerCase() === "direct") return "";
  return raw;
}

function inferTelegramFileExtension(mediaUrl: string): string {
  try {
    const ext = path.extname(new URL(mediaUrl).pathname).toLowerCase();
    if (ext) return ext;
  } catch {
    // Fall through to media-type inference.
  }
  return isVideoMediaUrl(mediaUrl) ? ".mp4" : ".jpg";
}

async function downloadTelegramFileUrl(sourceUrl: string, targetPath: string, redirectsLeft = 3): Promise<void> {
  await new Promise<void>((resolve, reject) => {
    const tmpPath = `${targetPath}.part-${process.pid}-${Date.now()}`;
    let settled = false;
    const cleanup = () => {
      try {
        if (fs.existsSync(tmpPath)) fs.unlinkSync(tmpPath);
      } catch {
        // Best effort cleanup only.
      }
    };
    const finish = (error?: Error) => {
      if (settled) return;
      settled = true;
      if (error) {
        cleanup();
        reject(error);
      } else {
        resolve();
      }
    };

    const proxyUrl = getTelegramMediaProxyUrl();
    const agent = proxyUrl ? new HttpsProxyAgentCtor(proxyUrl) : undefined;
    const request = https.get(sourceUrl, { agent: agent as never, timeout: 300000 }, (response) => {
      const status = response.statusCode || 0;
      const location = response.headers.location;
      if ([301, 302, 303, 307, 308].includes(status) && location && redirectsLeft > 0) {
        response.resume();
        const nextUrl = new URL(location, sourceUrl).toString();
        downloadTelegramFileUrl(nextUrl, targetPath, redirectsLeft - 1).then(resolve, reject);
        settled = true;
        return;
      }
      if (status < 200 || status >= 300) {
        response.resume();
        finish(new Error(`HTTP ${status}`));
        return;
      }

      const stream = fs.createWriteStream(tmpPath);
      response.pipe(stream);
      response.on("error", (error) => finish(error instanceof Error ? error : new Error(String(error))));
      stream.on("error", (error) => finish(error instanceof Error ? error : new Error(String(error))));
      stream.on("finish", () => {
        stream.close((error) => {
          if (error) {
            finish(error instanceof Error ? error : new Error(String(error)));
            return;
          }
          try {
            fs.renameSync(tmpPath, targetPath);
            finish();
          } catch (renameError) {
            finish(renameError instanceof Error ? renameError : new Error(String(renameError)));
          }
        });
      });
    });
    request.on("timeout", () => request.destroy(new Error("timeout")));
    request.on("error", (error) => finish(error instanceof Error ? error : new Error(String(error))));
  });
}

async function materializeTelegramFileForVmosUpload(
  mediaUrl: string,
  mediaLabel: string,
  onProgress?: (p: PublishProgress) => void,
): Promise<string | null> {
  if (!isTelegramFileMediaUrl(mediaUrl)) return null;

  const stagingDir = getVmosMediaStagingDir();
  fs.mkdirSync(stagingDir, { recursive: true });
  const ext = inferTelegramFileExtension(mediaUrl);
  const targetPath = path.join(stagingDir, `telegram_${hashString(mediaUrl, 24)}${ext}`);
  if (!fs.existsSync(targetPath) || fs.statSync(targetPath).size <= 0) {
    onProgress?.({
      step: `正在下載 Telegram ${mediaLabel} 到本地暫存，再交給 VMOS 公網通道...`,
      done: false,
    });
    try {
      await downloadTelegramFileUrl(mediaUrl, targetPath);
    } catch (error) {
      throw new Error(`Telegram ${mediaLabel}下載失敗，無法交給 VMOS 上傳：${error instanceof Error ? error.message : String(error)}`);
    }
  }

  onProgress?.({
    step: `已完成 Telegram ${mediaLabel}本地暫存，準備 VMOS 公網直傳...`,
    done: false,
  });
  return targetPath;
}

function isPublicHttpMediaUrl(mediaUrl: string): boolean {
  if (!/^https?:\/\//i.test(mediaUrl)) return false;
  return isUsableVmosMediaStagingBaseUrl(mediaUrl);
}

function estimateVmosMediaUploadWaitMs(mediaUrl: string, isVideoMedia: boolean): number {
  const fallback = isVideoMedia ? 300000 : 90000;
  let size = 0;
  if (mediaUrl.startsWith("data:")) {
    const parsed = parseDataUrlMedia(mediaUrl);
    if (parsed?.base64) size = Math.ceil(parsed.base64.length * 0.75);
  } else {
    const localPath = resolveLocalMediaFilePath(mediaUrl);
    if (localPath) {
      try {
        size = fs.statSync(localPath).size;
      } catch {
        size = 0;
      }
    }
  }
  if (!size) return fallback;

  const conservativeBytesPerSecond = isVideoMedia ? 300 * 1024 : 200 * 1024;
  const estimated = Math.ceil(size / conservativeBytesPerSecond * 1000) + 60000;
  const maxWait = isVideoMedia ? 900000 : 180000;
  return Math.max(fallback, Math.min(maxWait, estimated));
}

async function requirePublicMediaUrlForVmosUpload(
  mediaUrl: string,
  mediaLabel: string,
  onProgress?: (p: PublishProgress) => void,
): Promise<string> {
  const materializedTelegramPath = await materializeTelegramFileForVmosUpload(mediaUrl, mediaLabel, onProgress);
  if (materializedTelegramPath) {
    mediaUrl = materializedTelegramPath;
  }

  if (isPublicHttpMediaUrl(mediaUrl)) {
    const reachable = await checkPublicMediaReachability(mediaUrl);
    if (!reachable.ok) {
      throw new Error(`${mediaLabel}公网 URL 不可达，已停止发布，未回退慢速通道：${mediaUrl}；${reachable.detail}`);
    }
    onProgress?.({
      step: `已确认${mediaLabel}公网 URL 可访问，使用智能體手機直传...`,
      done: false,
    });
    return mediaUrl;
  }

  const publicBaseUrl = getVmosMediaStagingPublicBaseUrl();
  if (!isUsableVmosMediaStagingBaseUrl(publicBaseUrl)) {
    throw new Error(`${mediaLabel}公网上传未配置可用 VMOS_MEDIA_STAGING_PUBLIC_BASE_URL，已停止发布，未回退慢速通道`);
  }

  const stagingDir = getVmosMediaStagingDir();
  fs.mkdirSync(stagingDir, { recursive: true });

  let fileName: string;
  let targetPath: string;
  if (mediaUrl.startsWith("data:")) {
    const parsed = parseDataUrlMedia(mediaUrl);
    if (!parsed) throw new Error(`${mediaLabel} data URL 解析失败，无法生成公网直传 URL`);
    const ext = inferMediaExtension(mediaUrl);
    fileName = `${hashString(parsed.base64, 24)}.${ext}`;
    targetPath = path.join(stagingDir, fileName);
    if (!fs.existsSync(targetPath)) {
      fs.writeFileSync(targetPath, Buffer.from(parsed.base64, "base64"));
    }
  } else {
    const localPath = resolveLocalMediaFilePath(mediaUrl);
    if (!localPath) {
      throw new Error(`${mediaLabel}不是公网 URL，也不是可读取的本地文件，已停止发布，未回退慢速通道`);
    }
    const stat = fs.statSync(localPath);
    const ext = path.extname(localPath) || `.${inferMediaExtension(localPath)}`;
    fileName = `${hashString(`${localPath}:${stat.size}:${stat.mtimeMs}`, 24)}${ext}`;
    targetPath = path.join(stagingDir, fileName);
    if (!fs.existsSync(targetPath)) {
      fs.copyFileSync(localPath, targetPath);
    }
  }

  const publicUrl = buildVmosStagingPublicUrl(fileName);
  if (!publicUrl) {
    throw new Error(`${mediaLabel}公网上传 URL 生成失败，已停止发布，未回退慢速通道`);
  }
  uploadVmosStagedFileBySsh(targetPath, fileName);
  const reachable = await checkPublicMediaReachability(publicUrl);
  if (!reachable.ok) {
    throw new Error(`${mediaLabel}公网 staging 文件不可达，已停止发布，未回退慢速通道：${publicUrl}；${reachable.detail}`);
  }
  onProgress?.({
    step: "已準備可直傳媒體 URL，改用智能體手機直傳以加快上傳...",
    done: false,
  });
  return publicUrl;
}

function readDeviceMediaStagingCache(): Record<string, DeviceMediaStagingCacheEntry> {
  try {
    if (!fs.existsSync(DEVICE_MEDIA_STAGING_CACHE_FILE)) return {};
    const raw = JSON.parse(fs.readFileSync(DEVICE_MEDIA_STAGING_CACHE_FILE, "utf8"));
    return raw && typeof raw === "object" ? raw : {};
  } catch {
    return {};
  }
}

function writeDeviceMediaStagingCache(cache: Record<string, DeviceMediaStagingCacheEntry>) {
  try {
    fs.mkdirSync(path.dirname(DEVICE_MEDIA_STAGING_CACHE_FILE), { recursive: true });
    const entries = Object.entries(cache)
      .sort((a, b) => String(b[1]?.updatedAt || "").localeCompare(String(a[1]?.updatedAt || "")))
      .slice(0, 300);
    fs.writeFileSync(
      DEVICE_MEDIA_STAGING_CACHE_FILE,
      JSON.stringify(Object.fromEntries(entries), null, 2),
      "utf8",
    );
  } catch {
    // Cache misses are acceptable; publishing can still stage the media normally.
  }
}

async function getReusableStagedMediaPath(
  config: VmosConfig,
  padCode: string,
  mediaUrl: string,
  fallbackRemotePath?: string,
): Promise<string | null> {
  const cache = readDeviceMediaStagingCache();
  const entry = cache[getDeviceMediaStagingKey(padCode, mediaUrl)];
  const remotePath = entry?.remotePath || fallbackRemotePath;
  if (!remotePath) return null;
  if (entry?.remotePath && fallbackRemotePath && entry.remotePath !== fallbackRemotePath) {
    delete cache[entry.key];
    writeDeviceMediaStagingCache(cache);
    return null;
  }
  const isVideoMedia = isVideoMediaUrl(mediaUrl);
  try {
    const exists = await execAdbForText(
      config,
      padCode,
      `[ -s ${shellSingleQuote(remotePath)} ] && echo EXISTS || echo MISSING`,
      8000,
      500,
    );
    if (!/EXISTS/.test(exists)) {
      if (entry?.key) {
        delete cache[entry.key];
        writeDeviceMediaStagingCache(cache);
      }
      return null;
    }

    const indexed = await waitForMediaIndexed(config, padCode, remotePath, isVideoMedia, 5000);
    if (!indexed) {
      await execAdbForText(
        config,
        padCode,
        `am broadcast -a android.intent.action.MEDIA_SCANNER_SCAN_FILE -d file://${remotePath}`,
        8000,
        500,
      ).catch(() => "");
      if (!await waitForMediaIndexed(config, padCode, remotePath, isVideoMedia, 8000)) {
        return null;
      }
    }

    rememberStagedMediaPath(padCode, mediaUrl, remotePath);
    return remotePath;
  } catch {
    return null;
  }
}

function rememberStagedMediaPath(
  padCode: string,
  mediaUrl: string,
  remotePath: string,
) {
  const key = getDeviceMediaStagingKey(padCode, mediaUrl);
  const cache = readDeviceMediaStagingCache();
  cache[key] = {
    key,
    padCode,
    mediaHash: hashString(mediaUrl, 32),
    mediaKind: isVideoMediaUrl(mediaUrl) ? "video" : "image",
    remotePath,
    updatedAt: new Date().toISOString(),
  };
  writeDeviceMediaStagingCache(cache);
}

function platformKeepsInlineMedia(platform: Platform): boolean {
  return platform === "instagram" || platform === "threads";
}

function shouldUseAcpThreadsFastTextPath(padCode: string, mediaUrl?: string): boolean {
  return padCode === ACP_THREADS_FAST_PAD_CODE && !mediaUrl;
}

export function shouldUseThreadsShareIntentPath(padCode: string, mediaUrl?: string): boolean {
  void padCode;
  void mediaUrl;
  // Threads 发布统一走系统分享入口，保持和已跑通的服务器测试链路一致。
  // 这条路径避开应用内首页/图库/键盘态差异导致的坐标漂移。
  return true;
}

function isAcpPad(padCode: string): boolean {
  return /^ACP/i.test(String(padCode || "").trim()) || ACP_THREADS_ALT_PAD_CODES.has(padCode);
}

function encodeBase64Utf8(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let binary = "";
  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }
  return btoa(binary);
}

function shellSingleQuote(value: string): string {
  return `'${value.replace(/'/g, "'\\''")}'`;
}

function shellDecodedTextArg(text: string): string {
  return `"$(printf %s ${shellSingleQuote(encodeBase64Utf8(text))} | base64 -d)"`;
}

function shellDoubleQuote(value: string): string {
  return `"${value.replace(/(["\\$`])/g, "\\$1")}"`;
}

function getThreadsShareMimeType(mediaUrl?: string): string {
  if (!mediaUrl) return "text/plain";
  if (isVideoMediaUrl(mediaUrl)) return "video/mp4";
  const ext = getMediaExtension(mediaUrl);
  if (ext === "png") return "image/png";
  if (ext === "webp") return "image/webp";
  return "image/jpeg";
}

function getTelegramShareMimeType(mediaUrl?: string): string {
  return getThreadsShareMimeType(mediaUrl);
}

export function buildThreadsShareIntentCommand(input: {
  caption?: string;
  contentUri?: string;
  mimeType?: string;
}): string {
  const mimeType = input.mimeType || (input.contentUri ? "image/jpeg" : "text/plain");
  const args = [
    `am force-stop ${THREADS_PACKAGE}`,
    "sleep 1",
    [
      "am start -W",
      "-a android.intent.action.SEND",
      `-t ${shellSingleQuote(mimeType)}`,
      `-n ${THREADS_SHARE_HANDLER}`,
      input.contentUri ? "--grant-read-uri-permission" : "",
      input.contentUri ? `--eu android.intent.extra.STREAM ${shellSingleQuote(input.contentUri)}` : "",
      input.caption ? `--es android.intent.extra.TEXT ${shellDecodedTextArg(input.caption)}` : "",
      "2>&1",
    ].filter(Boolean).join(" "),
  ];
  return args.join("; ");
}

function getXmlAttr(node: string, name: string): string {
  const match = node.match(new RegExp(`${name}="([^"]*)"`));
  return match?.[1] ?? "";
}

function decodeXmlAttr(value: string): string {
  return value
    .replace(/&quot;/g, "\"")
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&");
}

function parseBoundsCenter(bounds: string): { x: number; y: number } | null {
  const match = bounds.match(/\[(\d+),(\d+)\]\[(\d+),(\d+)\]/);
  if (!match) return null;
  const [, left, top, right, bottom] = match.map(Number);
  if (![left, top, right, bottom].every(Number.isFinite) || right <= left || bottom <= top) return null;
  return {
    x: Math.round((left + right) / 2),
    y: Math.round((top + bottom) / 2),
  };
}

function parseBoundsRect(bounds: string): { left: number; top: number; right: number; bottom: number; width: number; height: number } | null {
  const match = bounds.match(/\[(\d+),(\d+)\]\[(\d+),(\d+)\]/);
  if (!match) return null;
  const [, left, top, right, bottom] = match.map(Number);
  if (![left, top, right, bottom].every(Number.isFinite) || right <= left || bottom <= top) return null;
  return { left, top, right, bottom, width: right - left, height: bottom - top };
}

function findAndroidPermissionDialogButtonTarget(
  uiXml: string,
  preference: "allow" | "deny" = "deny",
): { x: number; y: number } | null {
  const nodes = uiXml.match(/<node\b[^>]*>/g) ?? [];
  const candidates: Array<{ x: number; y: number; score: number }> = [];

  for (const node of nodes) {
    const text = `${decodeXmlAttr(getXmlAttr(node, "text"))} ${decodeXmlAttr(getXmlAttr(node, "content-desc"))}`.trim();
    const center = parseBoundsCenter(getXmlAttr(node, "bounds"));
    if (!center || !text) continue;

    let score = 0;
    if (preference === "deny") {
      if (/^(不允許|不允许|Deny|Don['’]?t allow|拒絕|拒绝)$/i.test(text)) score += 20;
      if (/不允許|不允许|Deny|Don['’]?t allow|拒絕|拒绝/i.test(text)) score += 10;
    } else {
      if (/使用應用程式時|使用应用程序时|使用应用程式时|While using/i.test(text)) score += 20;
      if (/僅允許這一次|仅允许这一次|Only this time/i.test(text)) score += 8;
      if (/允許|允许|Allow/i.test(text)) score += 6;
    }
    if (/android\.widget\.Button|Button/i.test(getXmlAttr(node, "class"))) score += 3;
    if (/true/i.test(getXmlAttr(node, "clickable"))) score += 3;
    if (center.x >= 80 && center.x <= 640 && center.y >= 520 && center.y <= 1250) score += 2;
    if (score >= 10) candidates.push({ ...center, score });
  }

  const best = candidates.sort((a, b) => b.score - a.score || b.y - a.y)[0];
  return best ? { x: best.x, y: best.y } : null;
}

