  const right = Math.min(width - 1, Math.floor(width * 0.80));
  const top = Math.max(0, Math.floor(height * 0.50));
  const bottom = Math.min(height - 1, Math.floor(height * 0.69));
  let dark = 0;
  let total = 0;
