  const bottomReplyLeftMutedGlyph = ratio(0.04, 0.925, 0.44, 0.985, isMutedGlyph);
  return topWhite > 0.62
    && backArrow > 0.025
    && title > 0.030
    && topRightActions > 0.025
    && bottomReplyPill > 0.34
    && (bottomReplyLeftContent > 0.006 || bottomReplyLeftMutedGlyph > 0.010);
