function classifyTelegramLoginChallengeText(text: string, savedEmail?: string): { state: AccountSessionResult["state"]; message: string } {
  const normalized = String(text || "")
    .replace(/\s+password="(?:true|false)"/gi, "")
    .replace(/\s+/g, " ");
  if (/EMAIL_NOT_ALLOWED|email domain is not allowed/i.test(normalized)) {
    return {
      state: "challenge_manual",
      message: "Telegram 返回 Email 不可用，平台拒絕目前 Email 網域或登入方式。自動流程已停止在此步；請依截圖人工更換 Email/Google 登入方式後，再檢測登入狀態。",
    };
  }
  if (/\bSorry\b/i.test(normalized)) {
    return {
      state: "challenge_manual",
      message: "Telegram 登入頁返回錯誤彈窗。自動流程已停止在此步，避免繼續誤操作；請依截圖查看具體錯誤短語後人工處理，再檢測登入狀態。",
    };
  }
  if (/SMS Fee|High SMS Costs|Verification Required|Support via Telegram Premium|Sign up for US\$|Telegram Premium|短信費|簡訊費|短信验证|簡訊驗證/i.test(normalized)) {
    return {
      state: "challenge_manual",
      message: "Telegram 自動登入已走到最後的短信付費/短信驗證階段。此階段需要人工介入處理；請依截圖在智能體手機內完成後再檢測登入狀態。",
    };
  }
  if (/verification code|login code|code was sent|enter code|验证码|驗證碼|登入碼|登录码|代碼|代码/i.test(normalized)) {
    return {
      state: "challenge_otp",
      message: "Telegram 已進入一次性驗證碼頁。請直接在 Bot 輸入收到的驗證碼；驗證碼不會預先保存。",
    };
  }
  if (/two-step|two step|cloud password|password|二級密碼|两步验证|兩步驗證|雲端密碼|云端密码/i.test(normalized)) {
    return {
      state: "challenge_manual",
      message: "Telegram 需要二級密碼/雲端密碼。若已保存二級密碼仍未通過，請按截圖人工輸入或重新設定登入資料。",
    };
  }
  if (/login email|choose a login email|your email|email address|sign in with google|google|登入 Email|登入信箱|登录邮箱/i.test(normalized)) {
    return {
      state: "challenge_manual",
      message: savedEmail
        ? `Telegram 要求設定或選擇登入 Email/Google。已保存登入 Email：${savedEmail}；系統會優先嘗試填入，若進入 Google 授權或驗證頁，請按截圖人工完成後再檢測登入狀態。`
        : "Telegram 要求設定或選擇登入 Email/Google。尚未保存登入 Email；請按截圖在智能體手機內人工完成，或返回帳號管理補充 Email 後再重試。",
    };
  }
  if (/start messaging|your phone|phone number|country|國家|国家|手機號碼|手机号码/i.test(normalized)) {
    return {
      state: "logged_out",
      message: "Telegram 仍停留在手機號登入頁，手機號可能未提交成功，請檢查截圖後重試。",
    };
  }
  if (/too many attempts|flood|try again later|error|錯誤|错误/i.test(normalized)) {
    return {
      state: "failed",
      message: "Telegram 登入被平台限制或出現錯誤，請按截圖處理後再重試。",
    };
  }
  return {
    state: "challenge_manual",
    message: "Telegram 登入流程停在需要人工確認的頁面。請查看截圖完成當前步驟，完成後再檢測登入狀態。",
  };
}

async function classifyTelegramSmsFeeScreenshot(screenshotUrl?: string): Promise<AccountSessionResult | null> {
  if (!screenshotUrl) return null;
  try {
    const { callGemini, extractText, getInlineData } = await import("./gemini-client");
    const inlineData = await getInlineData(screenshotUrl).catch(() => null);
    if (!inlineData) return null;
    const prompt = `看這張 Telegram Android 截圖，只判斷它是否是「SMS Fee / High SMS Costs / Verification Required / Telegram Premium 付費短信驗證」頁面。

嚴格只返回 JSON：
{"is_sms_fee": true/false, "evidence": "一句話依據"}`;
    const raw = await callGemini(
      PUBLISH_VERIFY_MODEL,
      [{ role: "user", parts: [{ text: prompt }, { inlineData }] }],
      { maxOutputTokens: 300, temperature: 0 },
    );
    const text = (extractText(raw) || "").trim().replace(/^```json\s*/i, "").replace(/```\s*$/i, "");
    const jsonMatch = text.match(/\{[\s\S]*?\}/);
    if (!jsonMatch) return null;
    const parsed = JSON.parse(jsonMatch[0]);
    if (!parsed?.is_sms_fee) return null;
    return {
      ok: false,
      state: "challenge_manual",
      message: `Telegram 自動登入已走到最後的短信付費/短信驗證階段。此階段視為自動流程完成，需要人工介入處理；請依截圖在智能體手機內完成後再檢測登入狀態。${parsed.evidence ? `\n\n識別依據：${String(parsed.evidence).slice(0, 160)}` : ""}`,
      screenshotUrl,
    };
  } catch {
    return null;
  }
}

