async function dismissTelegramCommonBlockerIfPossible(
  config: VmosConfig,
  padCode: string,
  screenshotUrl?: string,
): Promise<boolean> {
  if (await dismissAndroidPermissionDialog(config, padCode, "allow").catch(() => false)) {
    return true;
  }
  if (await dismissThreadsSystemCrashDialogIfPossible(config, padCode, screenshotUrl).catch(() => false)) {
    return true;
  }
  const uiXml = await withTimeout(dumpUiXml(config, padCode), 2_500, "telegram blocker ui dump timeout").catch(() => "");
  const text = normalizeSingleLine(uiXml);
  if (!text) return false;
  const closeTarget = findThreadsTextTargetFromUiXml(
    uiXml,
    [
      /^Not now$|^Skip$|^Later$|^Cancel$|^OK$|^Close$/i,
      /^稍後再說$|^稍后再说$|^略過$|^跳過$|^取消$|^確定$|^确定$|^關閉$|^关闭$/i,
      /^允許$|^允许$|^Allow$/i,
    ],
    { preferTop: false, requireClickable: true },
  );
  if (closeTarget && !/刪除|删除|Delete|Remove|移除|Log out|登出|退出/i.test(text)) {
    await tapViaAdbAbsoluteQuick(config, padCode, closeTarget.x, closeTarget.y, 1200);
    return true;
  }
  return false;
}

function normalizeTelegramPhoneForInput(phone: string): string {
  const compact = String(phone || "").replace(/[^\d+]/g, "");
  if (/^\+?886\d{8,10}$/.test(compact)) return compact.replace(/^\+?886/, "").replace(/^0+/, "");
  return compact;
}

function splitTelegramPhoneForLogin(phone: string): { countryCode: string; localNumber: string } {
  const compact = normalizeTelegramPhoneForInput(phone);
  if (/^\+?86\d{11}$/.test(compact)) return { countryCode: "86", localNumber: compact.replace(/^\+?86/, "") };
  if (/^\+?886\d{8,10}$/.test(compact)) return { countryCode: "886", localNumber: compact.replace(/^\+?886/, "").replace(/^0+/, "") };
  const withoutPlus = compact.replace(/^\+/, "");
  return { countryCode: "", localNumber: withoutPlus };
}

function adbDigitKeySequence(value: string): string {
  return String(value || "")
    .replace(/\D/g, "")
    .split("")
    .map((digit) => `input keyevent KEYCODE_${digit}`)
    .join("; ");
}

function adbBackspaceSequence(count: number): string {
  return Array.from({ length: Math.max(0, count) }, () => "input keyevent KEYCODE_DEL").join("; ");
}

function adbTapBackspaceSequence(count: number): string {
  return Array.from({ length: Math.max(0, count) }, () => "input tap 594 1194; sleep 0.08").join("; ");
}

function adbSelectAllTextSequence(): string {
  return [
    "input keycombination KEYCODE_CTRL_LEFT KEYCODE_A",
    "sleep 0.2",
  ].join("; ");
}

function adbSafePhoneText(value: string): string {
  const compact = String(value || "").replace(/[^\d+]/g, "");
  const full = compact.startsWith("+") ? compact : `+${compact}`;
  return full.replace(/^\+/, "\\+");
}

function adbSafeAsciiText(value: string): string {
  return String(value || "")
    .replace(/\\/g, "\\\\")
    .replace(/ /g, "%s")
    .replace(/'/g, "\\'");
}

function adbSafeEmailText(value: string): string {
  return String(value || "")
    .trim()
    .replace(/\\/g, "\\\\")
    .replace(/ /g, "%s")
    .replace(/@/g, "\\@")
    .replace(/'/g, "\\'");
}

function maskInlineSecret(value?: string | null): string {
  const raw = String(value || "").trim();
  if (!raw) return "";
  if (raw.includes("@")) {
    const [name, domain] = raw.split("@");
    return `${name.slice(0, 2)}***@${domain || "***"}`;
  }
  if (raw.length <= 4) return "***";
  return `${raw.slice(0, 2)}***${raw.slice(-2)}`;
}

