async function fallbackThreadsLoginActivityClassification(
  config: VmosConfig,
  padCode: string,
  current: { page: string; confidence: number; evidence: string },
): Promise<{ page: string; confidence: number; evidence: string }> {
  if (current.page !== "unknown") return current;
  const focusText = await detectThreadsLoginActivityInFocus(config, padCode);
  if (!focusText) return current;
  return {
    page: "login_account_picker",
    confidence: Math.max(current.confidence, 0.82),
    evidence: `前台是 Threads LoginActivity，视觉模型误判为 unknown；${current.evidence || focusText.slice(0, 80)}`,
  };
}

async function classifyThreadsPage(
  config: VmosConfig,
  padCode: string,
): Promise<{ page: string; confidence: number; evidence: string }> {
  const localState = await classifyThreadsPageOnDevice(config, padCode).catch(() => null);
  if (localState) {
    if (localState.page === "home_feed" || localState.page === "profile_page") {
      return { page: localState.page, confidence: 0.96, evidence: localState.reason };
    }
    if (localState.page === "system_dialog") {
      return { page: "system_dialog", confidence: 0.9, evidence: localState.reason };
    }
    if (localState.page === "challenge") {
      return { page: "challenge_other", confidence: 0.88, evidence: localState.reason };
    }
    if (localState.page === "login_required") {
      const page = /PHONE|VERIFICATION|OTP|验证码|驗證碼|手機|手机/i.test(localState.reason)
        ? "otp_input"
        : "login_account_picker";
      return { page, confidence: 0.9, evidence: localState.reason };
    }
  }

  const { callGemini, extractText, getInlineData } = await import("./gemini-client");
  const shotUrl = await screenshot(config, padCode);
  const inlineData = await getInlineData(shotUrl).catch(() => null);
  if (!inlineData) return { page: "unknown", confidence: 0, evidence: "截图失败" };

  const prompt = `看这张 Android Threads (com.instagram.barcelona) 截图，判断当前页面类型。

类型枚举：
- home_feed              主页 feed（已登录，看到他人帖子流）
- profile_page           个人主页（看到自己头像 + 用户名）
- login_account_picker   登录入口/账号选择页（Threads 欢迎页中只有「使用 Instagram 帳號登入 / Log in with Instagram」白色卡片，或历史 IG 账号卡片 +「使用其他帳號」链接，无输入框）
- login_username_form    登录-用户名表单（单一文本输入框 + 「下一步」按钮）
- login_password_form    登录-密码表单（有密码输入框 + 「登入/Log in」按钮）
- login_2fa_choice       登录-2FA 验证方式选择页
- login_2fa_device_push  登录-等待另一设备批准
- otp_input              需要输入验证码（短信/邮件/2FA）
- save_login_info        保存登录信息提示（「儲存您的登入資料？」）
- system_dialog          系统弹窗（权限请求/通知）
- account_disabled       账号已被停用
- challenge_other        其他需要人工的挑战页
- unknown                都不像

严格只返回 JSON：
{"page": "<枚举值>", "confidence": 0.0-1.0, "evidence": "判断依据简述"}`;

  let raw: unknown;
  try {
    raw = await callGemini(
      PUBLISH_VERIFY_MODEL,
      [{ role: "user", parts: [{ text: prompt }, { inlineData }] }],
      { maxOutputTokens: 200, temperature: 0 },
    );
  } catch (error: any) {
    return fallbackThreadsLoginActivityClassification(config, padCode, {
      page: "unknown",
      confidence: 0,
      evidence: `视觉模型不可用：${error?.message || error}`,
    });
  }
  const text = (extractText(raw) || "").trim().replace(/^```json\s*/i, "").replace(/```\s*$/, "");
  // 用更宽松的正则匹配 JSON 对象（允许 evidence 里有引号）
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (!jsonMatch) {
    return fallbackThreadsLoginActivityClassification(config, padCode, {
      page: "unknown",
      confidence: 0,
      evidence: text.slice(0, 80),
    });
  }
  try {
    const json = JSON.parse(jsonMatch[0]);
    return fallbackThreadsLoginActivityClassification(config, padCode, {
      page: json.page || "unknown",
      confidence: json.confidence || 0,
      evidence: json.evidence || "",
    });
  } catch {
    // 尝试直接解析整个 text
    try {
      const json = JSON.parse(text);
      return fallbackThreadsLoginActivityClassification(config, padCode, {
        page: json.page || "unknown",
        confidence: json.confidence || 0,
        evidence: json.evidence || "",
      });
    } catch {
      return fallbackThreadsLoginActivityClassification(config, padCode, {
        page: "unknown",
        confidence: 0,
        evidence: text.slice(0, 80),
      });
    }
  }
}

async function classifyThreadsLoginTransitionVisually(
  config: VmosConfig,
  padCode: string,
): Promise<{ page: string; evidence: string } | null> {
  const { callGemini, extractText, getInlineData } = await import("./gemini-client");
  const shotUrl = await screenshot(config, padCode);
  const inlineData = await getInlineData(shotUrl).catch(() => null);
  if (!inlineData) return null;

  const prompt = `看这张 Android Threads / Instagram 登录流程截图，只判断当前是否是登录后的中间页。

枚举：
- save_login_info：出现「儲存登入資料? / Save login info」页面，要求保存或稍后再说。
- login_form：仍是用户名/密码登录表单或 Threads 登录入口。
- challenge：验证码、2FA、安全验证、账号异常、人工确认页。
- home_or_profile：已经进入 Threads 首页或个人页。
- unknown：无法确认。

严格只返回 JSON：
{"page":"<枚举>","evidence":"短原因"}`;

  try {
    const raw = await callGemini(
      PUBLISH_VERIFY_MODEL,
      [{ role: "user", parts: [{ text: prompt }, { inlineData }] }],
      { maxOutputTokens: 120, temperature: 0 },
    );
    const text = (extractText(raw) || "").trim().replace(/^```json\s*/i, "").replace(/```\s*$/, "");
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (!jsonMatch) return { page: "unknown", evidence: text.slice(0, 120) };
    const json = JSON.parse(jsonMatch[0]);
    return {
      page: String(json.page || "unknown"),
      evidence: String(json.evidence || ""),
    };
  } catch (error: any) {
    return { page: "unknown", evidence: `视觉判定不可用：${error?.message || error}` };
  }
}

async function findButtonOnScreen(
  config: VmosConfig,
  padCode: string,
  targetDescription: string,
  timeoutMs = 25000,
): Promise<{ x: number; y: number } | null> {
  const { callGemini, extractText, getInlineData } = await import("./gemini-client");
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const shotUrl = await screenshot(config, padCode);
    const inlineData = await getInlineData(shotUrl).catch(() => null);
    if (!inlineData) { await delay(2000); continue; }

    const prompt = `看这张 Android 手机截图（屏幕分辨率 720x1600，左上角=(0,0)，右下角=(720,1600)）。

任务是找一个特定 UI 元素的中心点像素坐标。
目标：${targetDescription}

注意：
- x ∈ [0, 720]，y ∈ [0, 1600]
- 不要把不同按钮搞混

严格只返回 JSON（不要任何其他文字）：
{"found": true/false, "x": 整数, "y": 整数, "note": "短描述"}`;

    const raw = await callGemini(
      PUBLISH_VERIFY_MODEL,
      [{ role: "user", parts: [{ text: prompt }, { inlineData }] }],
      { maxOutputTokens: 80, temperature: 0 },
    );
    const text = (extractText(raw) || "").trim();
    const jsonMatch = text.match(/\{[^}]+\}/);
    if (!jsonMatch) { await delay(2000); continue; }
    try {
      const json = JSON.parse(jsonMatch[0]);
      if (json.found && typeof json.x === "number" && typeof json.y === "number") {
        const x = Math.round(json.x);
        const y = Math.round(json.y);
        if (x >= 0 && x <= 720 && y >= 0 && y <= 1600) {
          return { x, y };
        }
      }
    } catch {}
    await delay(2000);
  }
  return null;
}

