function findThreadsProfileAvatarEditTarget(uiXml: string): { x: number; y: number } | null {
  return findThreadsTextTargetFromUiXml(
    uiXml,
    [
      /更換大頭貼照|更换头像|更換頭像|更换大头贴照|更換個人照片|更换个人照片/i,
      /Change profile (photo|picture)|Edit profile (photo|picture)|New profile picture/i,
    ],
    { minY: 150, maxY: 460, preferTop: true },
  );
}

function findThreadsProfileAvatarPickerTarget(uiXml: string): { x: number; y: number } | null {
  return findThreadsTextTargetFromUiXml(
    uiXml,
    [
      /從相簿選擇|从相册选择|從圖庫選擇|从图库选择|選擇相片|选择照片|選擇大頭貼/i,
      /Choose from library|Select from gallery|Upload photo/i,
    ],
    { minY: 240, maxY: 1300, preferTop: true },
  );
}

function findThreadsProfileAvatarNewPhotoTarget(uiXml: string): { x: number; y: number } | null {
  return findThreadsTextTargetFromUiXml(
    uiXml,
    [
      /新大頭貼照|新大头贴照|新增大頭貼|新增大头贴|新頭像|新头像|更換大頭貼照|更换大头贴照/i,
      /New profile (photo|picture)|New photo|Change profile (photo|picture)/i,
    ],
    { minY: 640, maxY: 1300, preferTop: true },
  );
}

function isThreadsAvatarInstagramImportOnlyUiXml(uiXml: string): boolean {
  const normalized = normalizeSingleLine(decodeXmlAttr(uiXml));
  if (!normalized) return false;
  const hasNewPhoto = /新大頭貼照|新大头贴照|新增大頭貼|新增大头贴|新頭像|新头像|New profile (photo|picture)|New photo/i.test(normalized);
  if (hasNewPhoto) return false;
  const hasInstagramImport = /Instagram/i.test(normalized)
    && /(匯入|汇入|導入|导入|Import|登入|登录|Log in)/i.test(normalized);
  const hasLocalPicker = /(相簿|相册|圖庫|图库|選擇相片|选择照片|Choose from library|Select from gallery|Upload photo)/i.test(normalized);
  return hasInstagramImport && !hasLocalPicker;
}

async function detectThreadsAvatarInstagramImportOnlyByScreenshot(screenshotUrl?: string): Promise<boolean> {
  if (!screenshotUrl || typeof fetch !== "function") return false;
  const response = await fetchWithTimeout(screenshotUrl, {}, 8_000);
  if (!response.ok) return false;
  const buffer = Buffer.from(await response.arrayBuffer());
  const sharp = (await import("sharp")).default;
  const { data, info } = await sharp(buffer).resize(720, 1600, { fit: "fill" }).removeAlpha().raw().toBuffer({ resolveWithObject: true });
  const idx = (x: number, y: number) => (Math.max(0, Math.min(info.height - 1, Math.round(y))) * info.width + Math.max(0, Math.min(info.width - 1, Math.round(x)))) * 3;
  const ratio = (left: number, top: number, width: number, height: number, pred: (r: number, g: number, b: number) => boolean) => {
    let total = 0;
    let matched = 0;
    for (let y = top; y < top + height; y += 5) {
      for (let x = left; x < left + width; x += 5) {
        const i = idx(x, y);
        total += 1;
        if (pred(data[i], data[i + 1], data[i + 2])) matched += 1;
      }
    }
    return total ? matched / total : 0;
  };
  const bottomSheetWhite = ratio(25, 1290, 670, 255, (r, g, b) => r > 236 && g > 236 && b > 236);
  const dimmedEditArea = ratio(45, 185, 630, 980, (r, g, b) => {
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    return max < 225 && max - min < 55;
  });
  const localPickerGrid = ratio(20, 760, 680, 500, (r, g, b) => {
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    return max - min > 45 && max < 245;
  });
  return bottomSheetWhite > 0.82 && dimmedEditArea > 0.58 && localPickerGrid < 0.28;
}

async function assertThreadsAvatarDirectUploadStillAvailable(
  config: VmosConfig,
  padCode: string,
  context: string,
): Promise<void> {
  const uiXml = await dumpUiXml(config, padCode).catch(() => "");
  const focus = await execAdbForText(
    config,
    padCode,
    `dumpsys activity activities 2>/dev/null | grep -E "mResumedActivity|topResumedActivity" | head -n 5`,
    8_000,
    400,
  ).catch(() => "");
  const shotUrl = await screenshot(config, padCode).catch(() => undefined);
  const importOnlyByScreenshot = await detectThreadsAvatarInstagramImportOnlyByScreenshot(shotUrl).catch(() => false);
  if (/com\.android\.chrome|CustomTabActivity/i.test(focus) || isThreadsAvatarInstagramImportOnlyUiXml(uiXml) || importOnlyByScreenshot) {
    throw new Error(buildThreadsBlockedError(
      `${context}：Threads 目前只顯示「從 Instagram 匯入」頭像入口，沒有本機相簿/圖庫入口；需要先登入並修改 Instagram 頭像後再匯入，無法在 Threads 內直接上傳新頭像。`,
      shotUrl,
    ));
  }
}

async function tapThreadsProfileAvatarSaveOrNext(
  config: VmosConfig,
  padCode: string,
  waitMs = 1800,
): Promise<boolean> {
  const uiXml = await dumpUiXml(config, padCode).catch(() => "");
  let target = findThreadsTextTargetFromUiXml(
    uiXml,
    [/^完成$|^Done$|^下一步$|^Next$|^儲存$|^保存$|^Save$|^套用$|^Apply$/i],
    { maxY: 260, preferTop: true },
  );
  target ||= findThreadsTextTargetFromUiXml(
    uiXml,
    [/^完成$|^Done$|^下一步$|^Next$|^儲存$|^保存$|^Save$|^套用$|^Apply$/i],
    { minY: 1300, preferTop: false },
  );
  if (target) {
    const tapPoint = await scaleUiXmlPointToPhysicalTap(config, padCode, target);
    await tapViaAdbAbsolute(config, padCode, tapPoint.x, tapPoint.y, waitMs);
    return true;
  }
  if (isAcpPad(padCode)) {
    const focus = await execAdbForText(
      config,
      padCode,
      `dumpsys activity activities 2>/dev/null | grep -E "mResumedActivity|topResumedActivity" | head -n 5`,
      8_000,
      400,
    ).catch(() => "");
    if (/MediaCaptureActivity/i.test(focus)) {
      await tapCloud720Point(config, padCode, 640, 1230, waitMs);
      return true;
    }
  }
  const shotUrl = await screenshot(config, padCode).catch(() => undefined);
  if (await detectThreadsAvatarSystemCropEditorByScreenshot(shotUrl).catch(() => false)) {
    if (isAcpPad(padCode)) {
      await tapCloud720Point(config, padCode, 640, 1230, waitMs);
      return true;
    }
    const fallback = await scaleReferencePointToPhysicalTap(config, padCode, { x: 638, y: 1532 }, FIXED_VMOS_SCREEN);
    await tapViaAdbAbsolute(config, padCode, fallback.x, fallback.y, waitMs);
    return true;
  }
  const fallback = await scaleReferencePointToPhysicalTap(config, padCode, { x: 640, y: 145 }, FIXED_VMOS_SCREEN);
  await tapViaAdbAbsolute(config, padCode, fallback.x, fallback.y, waitMs);
  return true;
}

function isThreadsAvatarPostSelectionUiXml(uiXml: string): boolean {
  const normalized = normalizeSingleLine(decodeXmlAttr(uiXml));
  if (!normalized) return false;
  if (isThreadsEditProfilePageUiXml(normalized)) return false;
  if (/裁切|裁剪|Crop|Move and scale|縮放|缩放|調整|调整/i.test(normalized)) return true;
  if (/相片|照片|圖庫|图库|媒體|媒体|Photos?|Gallery|Albums?|Recents?|Camera/i.test(normalized)) return false;
  return /完成|Done|下一步|Next|儲存|保存|Save|套用|Apply/i.test(normalized);
}

async function waitForThreadsAvatarSelectionAdvance(
  config: VmosConfig,
  padCode: string,
  timeoutMs = 5500,
): Promise<boolean> {
  const deadline = Date.now() + timeoutMs;
  let lastShotUrl: string | undefined;
  while (Date.now() < deadline) {
    await dismissAndroidPermissionDialog(config, padCode, "allow").catch(() => false);
    const uiXml = await dumpUiXml(config, padCode).catch(() => "");
    if (isThreadsAvatarPostSelectionUiXml(uiXml)) return true;
    lastShotUrl = await screenshot(config, padCode).catch(() => lastShotUrl);
    if (await detectThreadsAvatarSystemCropEditorByScreenshot(lastShotUrl).catch(() => false)) return true;
    await delay(650);
  }
  return false;
}

export async function updateThreadsProfileAvatar(
  config: VmosConfig,
  padCode: string,
  imageUrl: string,
  onProgress?: (progress: PublishProgress) => void,
): Promise<ThreadsProfileUpdateResult> {
  const targetImageUrl = normalizeSingleLine(imageUrl);
  if (!targetImageUrl) throw new Error("头像图片不能为空");
  if (isVideoMediaUrl(targetImageUrl)) throw new Error("头像只支持图片，不支持视频");

  const remotePath = `/sdcard/Download/threads-profile-avatar-${Date.now()}.jpg`;
  const staging = startDeviceMediaStaging(config, padCode, targetImageUrl, remotePath, onProgress, { reuse: false });
  const opened = await openThreadsEditProfilePage(config, padCode, onProgress);
  await assertThreadsActionNotBlocked(config, padCode, "頭像修改打開編輯個人資料後檢測到帳號狀態阻斷");
  const stagedRemotePath = await withTimeout(
    staging.wait("等待頭像圖片寫入智能體手機圖庫..."),
    60_000,
    "頭像圖片寫入智能體手機圖庫逾時，請稍後重試",
  );
  await assertThreadsActionNotBlocked(config, padCode, "頭像修改等待圖片寫入後檢測到帳號狀態阻斷");
  await execAdbForText(
    config,
    padCode,
    `am broadcast -a android.intent.action.MEDIA_SCANNER_SCAN_FILE -d file://${stagedRemotePath}`,
    8_000,
    700,
  ).catch(() => "");

  let uiXml = opened.uiXml;
  let avatarTarget = findThreadsProfileAvatarEditTarget(uiXml);
  let avatarTargetSource: ThreadsProfileLinkTargetSource | null = avatarTarget ? "xml" : null;
  if (!avatarTarget && isAcpPad(padCode)) {
    const shotUrl = opened.screenshotUrl || await screenshot(config, padCode).catch(() => undefined);
    avatarTarget = await locateThreadsEditProfileAvatarFromScreenshot(shotUrl).catch(() => null);
    avatarTargetSource = avatarTarget ? "vision" : null;
  }
  if (!avatarTarget) {
    const shotUrl = opened.screenshotUrl || await screenshot(config, padCode).catch(() => undefined);
    avatarTarget = shotUrl
      ? await locateThreadsButtonByVision(
          shotUrl,
          "Threads 编辑个人资料页面顶部头像区域或「更换大头贴照 / Change profile photo」按钮中心点；不要选姓名、用户名、个人简介、Links、性别或右上 Done",
        ).catch(() => null)
      : null;
    if (avatarTarget) avatarTargetSource = "vision";
  }
  if (!avatarTarget) {
    avatarTarget = isAcpPad(padCode)
      ? { x: 595, y: 270 }
      : await scaleReferencePointToPhysicalTap(config, padCode, { x: 360, y: 318 }, FIXED_VMOS_SCREEN);
    avatarTargetSource = "fallback";
  }

  onProgress?.({ step: "打开 Threads 头像设置...", done: false });
  const avatarTapPoint = avatarTargetSource === "vision"
    ? avatarTarget
    : avatarTarget;
  await tapCloud720Point(config, padCode, avatarTapPoint.x, avatarTapPoint.y, 1800);
  await dismissAndroidPermissionDialog(config, padCode, "allow").catch(() => false);
  await delay(900);
  await assertThreadsActionNotBlocked(config, padCode, "頭像修改點擊頭像後檢測到帳號狀態阻斷");

  uiXml = await dumpUiXml(config, padCode).catch(() => "");
  const newPhotoTarget = findThreadsProfileAvatarNewPhotoTarget(uiXml);
  if (newPhotoTarget) {
    const newPhotoTap = await scaleUiXmlPointToPhysicalTap(config, padCode, newPhotoTarget);
    onProgress?.({ step: "选择「新大頭貼」...", done: false });
    await tapViaAdbAbsolute(config, padCode, newPhotoTap.x, newPhotoTap.y, 2200);
    await dismissAndroidPermissionDialog(config, padCode, "allow").catch(() => false);
    await delay(900);
    await assertThreadsActionNotBlocked(config, padCode, "頭像修改點擊新大頭貼後檢測到帳號狀態阻斷");
    await assertThreadsAvatarDirectUploadStillAvailable(config, padCode, "點擊「新大頭貼」後");
  } else if (isAcpPad(padCode)) {
    const sourceShotUrl = await screenshot(config, padCode).catch(() => undefined);
    if (await detectThreadsAvatarInstagramImportOnlyByScreenshot(sourceShotUrl).catch(() => false)) {
      onProgress?.({ step: "选择「新大頭貼」...", done: false });
      await tapCloud720Point(config, padCode, 360, 1190, 2200);
      await dismissAndroidPermissionDialog(config, padCode, "allow").catch(() => false);
      await delay(900);
      await assertThreadsActionNotBlocked(config, padCode, "頭像修改點擊新大頭貼後檢測到帳號狀態阻斷");
      await assertThreadsAvatarDirectUploadStillAvailable(config, padCode, "點擊「新大頭貼」後");
    } else {
      await assertThreadsAvatarDirectUploadStillAvailable(config, padCode, "Threads 頭像來源列表中");
    }
  } else {
    await assertThreadsAvatarDirectUploadStillAvailable(config, padCode, "Threads 頭像來源列表中");
  }

  uiXml = await dumpUiXml(config, padCode).catch(() => "");
  const afterAvatarSourceShot = isAcpPad(padCode) ? await screenshot(config, padCode).catch(() => undefined) : undefined;
  const stillOnEditProfileAfterSource = isThreadsEditProfilePageUiXml(uiXml)
    || await detectThreadsEditProfilePageByScreenshotHeuristic(afterAvatarSourceShot).catch(() => false);
  if (isAcpPad(padCode) && stillOnEditProfileAfterSource) {
    onProgress?.({ step: "頭像入口仍停在編輯頁，重新點擊頭像加號...", done: false });
    for (const point of [{ x: 595, y: 270 }, { x: 595, y: 340 }]) {
      await tapCloud720Point(config, padCode, point.x, point.y, 1800);
      await dismissAndroidPermissionDialog(config, padCode, "allow").catch(() => false);
      await delay(900);
      uiXml = await dumpUiXml(config, padCode).catch(() => "");
      const retryShot = await screenshot(config, padCode).catch(() => undefined);
      if (!isThreadsEditProfilePageUiXml(uiXml) && !await detectThreadsEditProfilePageByScreenshotHeuristic(retryShot).catch(() => false)) break;
    }
    const retryShot = await screenshot(config, padCode).catch(() => undefined);
    uiXml = await dumpUiXml(config, padCode).catch(() => "");
    if (isThreadsEditProfilePageUiXml(uiXml) || await detectThreadsEditProfilePageByScreenshotHeuristic(retryShot).catch(() => false)) {
      const shot = await screenshot(config, padCode).catch(() => undefined);
      throw new Error(`點擊頭像入口後仍停在 Threads 編輯頁，未進入圖庫${shot ? `，截图：${shot}` : ""}`);
    }
  }

  uiXml = await dumpUiXml(config, padCode).catch(() => "");
  const pickerTarget = findThreadsProfileAvatarPickerTarget(uiXml);
  if (pickerTarget) {
    const pickerTap = await scaleUiXmlPointToPhysicalTap(config, padCode, pickerTarget);
    await tapViaAdbAbsolute(config, padCode, pickerTap.x, pickerTap.y, 2200);
    await dismissAndroidPermissionDialog(config, padCode, "allow").catch(() => false);
    await delay(900);
    await assertThreadsActionNotBlocked(config, padCode, "頭像修改點擊頭像來源後檢測到帳號狀態阻斷");
    await assertThreadsAvatarDirectUploadStillAvailable(config, padCode, "點擊 Threads 頭像來源後");
  }

  onProgress?.({ step: "选择新的头像图片...", done: false });
  const beforeSelectShot = await screenshot(config, padCode).catch(() => undefined);
  if (isAcpPad(padCode) && await detectThreadsEditProfilePageByScreenshotHeuristic(beforeSelectShot).catch(() => false)) {
    throw new Error(`尚未進入圖庫，仍停在 Threads 編輯頁${beforeSelectShot ? `，截图：${beforeSelectShot}` : ""}`);
  }
  let selected = false;
  if (isAcpPad(padCode)) {
    await tapCloud720Point(config, padCode, 650, 113, 1800);
    await dismissAndroidPermissionDialog(config, padCode, "allow").catch(() => false);
    await delay(900);
    const afterTopDoneShot = await screenshot(config, padCode).catch(() => undefined);
    if (
      await detectThreadsAvatarSystemCropEditorByScreenshot(afterTopDoneShot).catch(() => false)
    ) {
      selected = true;
    }
  }
  const initialSelectionShot = await screenshot(config, padCode).catch(() => undefined);
  if (
    await detectThreadsAvatarSelectionReadyByScreenshot(initialSelectionShot).catch(() => false)
    || await detectThreadsAvatarSystemCropEditorByScreenshot(initialSelectionShot).catch(() => false)
  ) {
    selected = true;
  }
  for (let attempt = 0; attempt < 6 && !selected; attempt += 1) {
    const shotUrl = await screenshot(config, padCode).catch(() => undefined);
    const selectionReady = await detectThreadsAvatarSelectionReadyByScreenshot(shotUrl).catch(() => false);
    if (selectionReady || await detectThreadsAvatarSystemCropEditorByScreenshot(shotUrl).catch(() => false)) {
      selected = true;
      break;
    }
    const refPoint = shotUrl ? await locateThreadsGalleryReferenceImage(shotUrl, targetImageUrl).catch(() => null) : null;
    const tapPoint = refPoint
      || (selectionReady && isAcpPad(padCode)
        ? { x: 90 + (attempt % 4) * 180, y: 990 + Math.floor(attempt / 4) * 180 }
        : { x: 120 + attempt * 170, y: attempt < 2 ? 330 : 520 });
    if (isAcpPad(padCode)) {
      await tapCloud720Point(config, padCode, tapPoint.x, tapPoint.y, 1800);
    } else {
      await tapViaAdbAbsolute(config, padCode, tapPoint.x, tapPoint.y, 1800);
    }
    await dismissAndroidPermissionDialog(config, padCode, "allow").catch(() => false);
    await delay(700);
    const nextXml = normalizeSingleLine(await dumpUiXml(config, padCode).catch(() => ""));
    if (isThreadsAvatarPostSelectionUiXml(nextXml)) {
      selected = true;
      break;
    }
    if ((await getThreadsGallerySelectedMarkers(config, padCode).catch(() => [])).length > 0) {
      selected = true;
      break;
    }
    selected = await waitForThreadsAvatarSelectionAdvance(config, padCode).catch(() => false);
  }
  if (!selected) {
    const afterSelectionXml = await dumpUiXml(config, padCode).catch(() => "");
    const afterSelectionShot = await screenshot(config, padCode).catch(() => undefined);
    if (
      isThreadsEditProfilePageUiXml(afterSelectionXml)
      || await detectThreadsEditProfilePageByScreenshotHeuristic(afterSelectionShot).catch(() => false)
    ) {
      selected = true;
    }
  }
  if (!selected) {
    const shot = await screenshot(config, padCode).catch(() => undefined);
    throw new Error(`未能在图库中选择新的头像图片${shot ? `，截图：${shot}` : ""}`);
  }
  await assertThreadsActionNotBlocked(config, padCode, "頭像修改選擇圖片後檢測到帳號狀態阻斷");

  onProgress?.({ step: "确认头像裁剪与保存...", done: false });
  for (let attempt = 0; attempt < 5; attempt += 1) {
    const ui = await dumpUiXml(config, padCode).catch(() => "");
    if (isThreadsEditProfilePageUiXml(ui)) break;
    await tapThreadsProfileAvatarSaveOrNext(config, padCode, 2200).catch(() => undefined);
    await dismissAndroidPermissionDialog(config, padCode, "allow").catch(() => false);
    await delay(1100);
    const focusAfterSaveTap = await execAdbForText(
      config,
      padCode,
      `dumpsys activity activities 2>/dev/null | grep -E "mResumedActivity|topResumedActivity" | head -n 5`,
      8_000,
      400,
    ).catch(() => "");
    if (!/MediaCaptureActivity/i.test(focusAfterSaveTap)) break;
  }

  const afterAvatarXml = await dumpUiXml(config, padCode).catch(() => "");
  if (isThreadsEditProfilePageUiXml(afterAvatarXml)) {
    await assertThreadsActionNotBlocked(config, padCode, "頭像修改準備保存時檢測到帳號狀態阻斷");
    if (isAcpPad(padCode)) {
      await tapCloud720Point(config, padCode, 642, 118, 2600).catch(() => undefined);
    } else {
      await saveThreadsEditProfilePage(config, padCode);
    }
    await assertThreadsActionNotBlocked(config, padCode, "頭像修改保存後檢測到帳號狀態阻斷");
  }
  await delay(1600);
  const finalShot = await screenshot(config, padCode).catch(() => undefined);
  onProgress?.({ step: "Threads 头像已提交", done: true });

  return {
    ok: true,
    state: "submitted",
    detail: "已完成头像选择与保存动作，请以截图确认头像是否已刷新",
    screenshotUrl: finalShot,
  };
}

export async function updateThreadsProfileLink(
  config: VmosConfig,
  padCode: string,
  link: string,
  onProgress?: (progress: PublishProgress) => void,
): Promise<ThreadsProfileLinkResult> {
  const targetLink = normalizeSingleLine(link);
  if (!targetLink) throw new Error("链接不能为空");

  onProgress?.({ step: "启动 Threads 并打开个人主页...", done: false });
  const profile = await openThreadsProfileForAccountQuery(config, padCode, onProgress);
  if (!profile.ok) {
    throw new Error(profile.error || "未能打开 Threads 个人主页");
  }

  if (profile.profileLikely && !isAcpPad(padCode)) {
    for (let i = 0; i < 3; i += 1) {
      await execAdbForText(config, padCode, "input swipe 360 560 360 1180 420", 8_000, 500).catch(() => "");
      await delay(500);
    }
  }

  let uiXml = isAcpPad(padCode) ? "" : await dumpUiXml(config, padCode).catch(() => "");
  let editTarget = isAcpPad(padCode)
    ? await scaleReferencePointToPhysicalTap(config, padCode, { x: 192, y: 656 }, FIXED_VMOS_SCREEN)
    : uiXml
    ? findThreadsTextTargetFromUiXml(
        uiXml,
        [/編輯個人檔案|编辑个人档案|編輯個人資料|编辑个人资料|編輯主页|编辑主页|Edit profile/i],
        { preferTop: true },
      )
    : null;
  let editTargetSource: ThreadsProfileLinkTargetSource | null = editTarget ? (isAcpPad(padCode) ? "fallback" : "xml") : null;
  const profileShotUrl = await screenshot(config, padCode).catch(() => profile.screenshotUrl);
  const editVisionShotUrl = profileShotUrl || profile.screenshotUrl;
  if (!editTarget && editVisionShotUrl) {
    editTarget = await locateThreadsButtonByVision(
      editVisionShotUrl,
      "Threads 自己个人主页上的「编辑个人档案 / 编辑个人资料 / 编辑主页 / Edit profile」按钮中心点；不要选分享个人档案、关注、返回键或底部导航",
    ).catch(() => null);
    if (editTarget) editTargetSource = "vision";
  }
  if (!editTarget && profile.profileLikely) {
    editTarget = isAcpPad(padCode)
      ? await scaleReferencePointToPhysicalTap(config, padCode, { x: 192, y: 656 }, FIXED_VMOS_SCREEN)
      : await scaleReferencePointToPhysicalTap(config, padCode, { x: 176, y: 596 }, FIXED_VMOS_SCREEN);
    editTargetSource = "fallback";
  }
  if (!editTarget) throw new Error("未找到 Threads 个人主页的编辑按钮");

  onProgress?.({ step: "进入编辑个人资料页面...", done: false });
  if (isAcpPad(padCode)) {
    const editPoint = padCode === ACP_THREADS_FAST_PAD_CODE ? { x: 176, y: 532 } : { x: 192, y: 656 };
    await tapCloud720Point(config, padCode, editPoint.x, editPoint.y, 2800);
  } else {
    const editTapPoint = await resolveThreadsProfileLinkTapPoint(config, padCode, editTarget, editTargetSource || "fallback");
    await tapViaAdbAbsoluteQuick(config, padCode, editTapPoint.x, editTapPoint.y, 1800);
  }
  await delay(900);
  await dismissThreadsSystemCrashDialogIfPossible(config, padCode).catch(() => false);
  await delay(700);
  if (isAcpPad(padCode)) {
    uiXml = "";
  } else {
    await assertThreadsActionNotBlocked(config, padCode, "連結修改點擊編輯個人資料後檢測到帳號狀態阻斷");
    for (let attempt = 0; attempt < 6; attempt += 1) {
      uiXml = await dumpUiXml(config, padCode).catch(() => "");
      if (isThreadsEditProfilePageUiXml(uiXml)) break;
      await assertThreadsActionNotBlocked(config, padCode, "連結修改等待編輯頁時檢測到帳號狀態阻斷");
      await delay(700);
    }
  }
  let preResolvedAddLinkTarget: { x: number; y: number } | null = null;
  let preResolvedAddLinkTargetSource: ThreadsProfileLinkTargetSource | null = null;
  if (isAcpPad(padCode)) {
    preResolvedAddLinkTarget = await scaleReferencePointToPhysicalTap(config, padCode, { x: 610, y: 867 }, FIXED_VMOS_SCREEN);
    preResolvedAddLinkTargetSource = "fallback";
  } else if (!isThreadsEditProfilePageUiXml(uiXml)) {
    const currentShot = await screenshot(config, padCode).catch(() => undefined);
    preResolvedAddLinkTarget = currentShot
      ? await locateThreadsButtonByVision(
          currentShot,
          "Threads 编辑个人资料页面中「Links / 連結 / 链接」管理入口的中心点，通常显示为「Links 0 >」；不要选姓名、用户名、个人简介、性别、Podcast、返回键或右上 Done",
        ).catch(() => null)
      : null;
    if (preResolvedAddLinkTarget) {
      preResolvedAddLinkTargetSource = "vision";
    } else {
      preResolvedAddLinkTarget = await scaleReferencePointToPhysicalTap(config, padCode, { x: 610, y: 867 }, FIXED_VMOS_SCREEN);
      preResolvedAddLinkTargetSource = "fallback";
    }
  }
  let resolvedAddLinkTarget: { x: number; y: number } | null = preResolvedAddLinkTarget;
  let resolvedAddLinkTargetSource: ThreadsProfileLinkTargetSource | null = preResolvedAddLinkTargetSource;
  for (let attempt = 0; attempt < 3 && !resolvedAddLinkTarget; attempt += 1) {
    const normalizedXml = normalizeSingleLine(uiXml);
    const addLinkCandidates = [
      /^(Links?|連結|链接)(?:\s*\d+)?$/i,
      /Links?\s*\d+|連結\s*\d+|链接\s*\d+/i,
      /編輯個人檔案|编辑个人档案|編輯個人資料|编辑个人资料|Edit profile/i,
    ];
    if (addLinkCandidates.some((pattern) => pattern.test(normalizedXml))) {
      resolvedAddLinkTarget = findThreadsTextTargetFromUiXml(
        uiXml,
        [/^(Links?|連結|链接)(?:\s*\d+)?$/i, /Links?\s*\d+|連結\s*\d+|链接\s*\d+/i],
        { minY: 220, maxY: 1380 },
      );
      if (resolvedAddLinkTarget) resolvedAddLinkTargetSource = "xml";
    }
    if (!resolvedAddLinkTarget) {
      const shotUrl = await screenshot(config, padCode).catch(() => undefined);
      resolvedAddLinkTarget = shotUrl
        ? await locateThreadsButtonByVision(
            shotUrl,
            "Threads 编辑个人资料页面中「Links / 連結 / 链接」管理入口的中心点，通常显示为「Links 0 >」；不要选姓名、用户名、个人简介、性别或返回键",
          ).catch(() => null)
        : null;
      if (resolvedAddLinkTarget) resolvedAddLinkTargetSource = "vision";
    }
    if (!resolvedAddLinkTarget && attempt < 2) {
      const swipeCmd = attempt === 0
        ? "input swipe 360 620 360 1120 420"
        : "input swipe 360 1050 360 540 420";
      await execAdbForText(config, padCode, swipeCmd, 8_000, 700).catch(() => "");
      await delay(900);
      uiXml = await dumpUiXml(config, padCode).catch(() => "");
    }
  }
  if (!resolvedAddLinkTarget) {
    resolvedAddLinkTarget = await scaleReferencePointToPhysicalTap(config, padCode, { x: 610, y: 867 }, FIXED_VMOS_SCREEN);
    resolvedAddLinkTargetSource = "fallback";
  }
  if (!resolvedAddLinkTarget) throw new Error("进入编辑个人资料后未识别到 Links 入口");
  onProgress?.({ step: "打开新增链接输入框...", done: false });
  if (isAcpPad(padCode)) {
    await tapCloud720Point(config, padCode, 610, 867, 2200);
    await delay(700);
    uiXml = await dumpUiXml(config, padCode).catch(() => "");
    if (!isThreadsProfileLinksPageUiXml(uiXml) && !findThreadsProfileLinkInputTarget(uiXml) && !findThreadsProfileAddLinkRowTarget(uiXml)) {
      await tapCloud720Point(config, padCode, 610, 1336, 2200);
    }
  } else {
    const addLinkTapPoint = await resolveThreadsProfileLinkTapPoint(
      config,
      padCode,
      resolvedAddLinkTarget,
      resolvedAddLinkTargetSource || "fallback",
    );
    await tapViaAdbAbsolute(config, padCode, addLinkTapPoint.x, addLinkTapPoint.y, 2400);
  }
  await dismissThreadsSystemCrashDialogIfPossible(config, padCode).catch(() => false);
  await delay(700);
  if (isAcpPad(padCode)) {
    await tapCloud720Point(config, padCode, 360, 360, 1800);
    await delay(900);
    uiXml = "";
  } else {
    await assertThreadsActionNotBlocked(config, padCode, "連結修改點擊 Links 後檢測到帳號狀態阻斷");

    for (let attempt = 0; attempt < 5; attempt += 1) {
      uiXml = await dumpUiXml(config, padCode).catch(() => "");
      if (isThreadsProfileLinksPageUiXml(uiXml) || findThreadsProfileLinkInputTarget(uiXml) || findThreadsProfileAddLinkRowTarget(uiXml)) break;
      await assertThreadsActionNotBlocked(config, padCode, "連結修改等待 Links 頁時檢測到帳號狀態阻斷");
      await delay(700);
    }
  }
  if (uiXml && isThreadsPostOptionsOrThreadDetailUiXml(uiXml)) {
    const currentShot = await screenshot(config, padCode).catch(() => undefined);
    throw new Error(`点击 Links 后未进入 Threads 链接管理页面${currentShot ? `，截图：${currentShot}` : ""}`);
  }
  let inputTarget = isAcpPad(padCode)
    ? await scaleReferencePointToPhysicalTap(config, padCode, { x: 360, y: 360 }, FIXED_VMOS_SCREEN)
    : findThreadsProfileLinkInputTarget(uiXml);
  let inputTargetSource: ThreadsProfileLinkTargetSource | null = inputTarget ? (isAcpPad(padCode) ? "fallback" : "xml") : null;
  if (!inputTarget) {
    const addLinkRowTarget = findThreadsProfileAddLinkRowTarget(uiXml);
    if (addLinkRowTarget) {
      const addLinkRowTapPoint = await scaleUiXmlPointToPhysicalTap(config, padCode, addLinkRowTarget);
      await tapViaAdbAbsolute(config, padCode, addLinkRowTapPoint.x, addLinkRowTapPoint.y, 1800);
      await dismissThreadsSystemCrashDialogIfPossible(config, padCode).catch(() => false);
      await delay(900);
      await assertThreadsActionNotBlocked(config, padCode, "連結修改點擊新增連結後檢測到帳號狀態阻斷");
      uiXml = await dumpUiXml(config, padCode).catch(() => "");
      inputTarget = findThreadsProfileLinkInputTarget(uiXml);
      if (inputTarget) inputTargetSource = "xml";
    }
  }
  if (!inputTarget) {
    const shotUrl = await screenshot(config, padCode).catch(() => undefined);
    inputTarget = shotUrl
      ? await locateThreadsButtonByVision(
          shotUrl,
          "Threads 新增链接页面中用于输入 URL/链接/网址的文本框中心点；不要选标题、名称、返回键或保存按钮",
        ).catch(() => null)
      : null;
    if (inputTarget) inputTargetSource = "vision";
  }
  if (!inputTarget) {
    const addLinkShotUrl = await screenshot(config, padCode).catch(() => undefined);
    const addLinkRowTarget = addLinkShotUrl
      ? await locateThreadsButtonByVision(
          addLinkShotUrl,
          "Threads「Links / 連結 / 链接」管理页面中用于新增普通网页/个人简介链接的「Add link / 新增連結 / 新增链接」行中心点；不要选 Podcast、Instagram、徽章、隐私设置或返回键",
        ).catch(() => null)
      : null;
    if (addLinkRowTarget) {
      await tapViaAdbAbsolute(config, padCode, addLinkRowTarget.x, addLinkRowTarget.y, 1800);
      await dismissThreadsSystemCrashDialogIfPossible(config, padCode).catch(() => false);
      await delay(900);
      await assertThreadsActionNotBlocked(config, padCode, "連結修改點擊新增連結後檢測到帳號狀態阻斷");
      uiXml = await dumpUiXml(config, padCode).catch(() => "");
      inputTarget = findThreadsProfileLinkInputTarget(uiXml);
      if (inputTarget) inputTargetSource = "xml";
      if (!inputTarget) {
        const retryInputShotUrl = await screenshot(config, padCode).catch(() => undefined);
        inputTarget = retryInputShotUrl
          ? await locateThreadsButtonByVision(
              retryInputShotUrl,
              "Threads 新增链接页面中用于输入 URL/链接/网址的文本框中心点；不要选标题、名称、返回键或保存按钮",
            ).catch(() => null)
          : null;
        if (inputTarget) inputTargetSource = "vision";
      }
    }
  }
  if (!inputTarget) {
    const addLinkFallback = await scaleReferencePointToPhysicalTap(config, padCode, { x: 180, y: 435 }, FIXED_VMOS_SCREEN);
    await tapViaAdbAbsolute(config, padCode, addLinkFallback.x, addLinkFallback.y, 1800);
    await dismissThreadsSystemCrashDialogIfPossible(config, padCode).catch(() => false);
    await delay(900);
    await assertThreadsActionNotBlocked(config, padCode, "連結修改 fallback 點擊新增連結後檢測到帳號狀態阻斷");
    uiXml = await dumpUiXml(config, padCode).catch(() => "");
    inputTarget = findThreadsProfileLinkInputTarget(uiXml);
    if (inputTarget) inputTargetSource = "xml";
    if (!inputTarget) {
      const inputShotUrl = await screenshot(config, padCode).catch(() => undefined);
      inputTarget = inputShotUrl
        ? await locateThreadsButtonByVision(
            inputShotUrl,
            "Threads 新增链接页面中用于输入 URL/链接/网址的文本框中心点；不要选标题、名称、返回键或保存按钮",
          ).catch(() => null)
        : null;
      if (inputTarget) inputTargetSource = "vision";
    }
    if (!inputTarget) {
      inputTarget = await scaleReferencePointToPhysicalTap(config, padCode, { x: 360, y: 360 }, FIXED_VMOS_SCREEN);
      inputTargetSource = "fallback";
    }
  }
  if (!inputTarget) {
    const normalizedAfterLinkTapXml = normalizeSingleLine(uiXml);
    if (!/編輯個人檔案|编辑个人档案|編輯個人資料|编辑个人资料|Edit profile/i.test(normalizedAfterLinkTapXml)) {
      await execAdbForText(config, padCode, "input keyevent KEYCODE_BACK", 8_000, 800).catch(() => "");
      await delay(900);
    }
    const lowerLinkTarget = await scaleReferencePointToPhysicalTap(config, padCode, { x: 610, y: 867 }, FIXED_VMOS_SCREEN);
    await tapViaAdbAbsolute(config, padCode, lowerLinkTarget.x, lowerLinkTarget.y, 2200);
    await dismissThreadsSystemCrashDialogIfPossible(config, padCode).catch(() => false);
    await delay(900);
    await assertThreadsActionNotBlocked(config, padCode, "連結修改重試點擊 Links 後檢測到帳號狀態阻斷");
    uiXml = await dumpUiXml(config, padCode).catch(() => "");
    inputTarget = findThreadsProfileLinkInputTarget(uiXml);
    if (inputTarget) inputTargetSource = "xml";
    if (!inputTarget) {
      const addLinkRowTarget = findThreadsProfileAddLinkRowTarget(uiXml);
      if (addLinkRowTarget) {
        const addLinkRowTapPoint = await scaleUiXmlPointToPhysicalTap(config, padCode, addLinkRowTarget);
        await tapViaAdbAbsolute(config, padCode, addLinkRowTapPoint.x, addLinkRowTapPoint.y, 1800);
        await dismissThreadsSystemCrashDialogIfPossible(config, padCode).catch(() => false);
        await delay(900);
        await assertThreadsActionNotBlocked(config, padCode, "連結修改重試點擊新增連結後檢測到帳號狀態阻斷");
        uiXml = await dumpUiXml(config, padCode).catch(() => "");
        inputTarget = findThreadsProfileLinkInputTarget(uiXml);
        if (inputTarget) inputTargetSource = "xml";
      }
    }
    if (!inputTarget) {
      const retryShotUrl = await screenshot(config, padCode).catch(() => undefined);
      inputTarget = retryShotUrl
        ? await locateThreadsButtonByVision(
            retryShotUrl,
            "Threads 新增链接页面中用于输入 URL/链接/网址的文本框中心点；不要选标题、名称、返回键或保存按钮",
          ).catch(() => null)
        : null;
      if (inputTarget) inputTargetSource = "vision";
    }
  }
  if (!inputTarget) throw new Error("未找到 Threads 链接输入框");

  const linkInputText = normalizeThreadsProfileLinkInput(targetLink);
  onProgress?.({ step: "填写个人简介链接...", done: false });
  const inputTapPoint = await resolveThreadsProfileLinkTapPoint(config, padCode, inputTarget, inputTargetSource || "fallback");
  if (isAcpPad(padCode)) {
    await tapCloud720Point(config, padCode, 360, 360, 900);
  } else {
    await tapViaAdbAbsolute(config, padCode, inputTapPoint.x, inputTapPoint.y, 900);
  }
  if (isAcpPad(padCode)) {
    await tapCloud720Point(config, padCode, 622, 360, 700).catch(() => undefined);
  } else {
    const clearLinkTarget = await scaleReferencePointToPhysicalTap(config, padCode, { x: 622, y: 385 }, FIXED_VMOS_SCREEN);
    await tapViaAdbAbsolute(config, padCode, clearLinkTarget.x, clearLinkTarget.y, 700).catch(() => undefined);
  }
  await delay(500);
  if (isAcpPad(padCode)) {
    await tapCloud720Point(config, padCode, 360, 360, 700);
  } else {
    await tapViaAdbAbsolute(config, padCode, inputTapPoint.x, inputTapPoint.y, 700);
  }
  await clearFocusedTextInput(config, padCode, 300);
  await typeTextViaAndroidInputText(config, padCode, linkInputText, 1600);
  await assertThreadsActionNotBlocked(config, padCode, "連結修改輸入網址後檢測到帳號狀態阻斷");

  let afterInputXml = await dumpUiXml(config, padCode).catch(() => "");
  if (hasReadableUiXml(afterInputXml) && !threadsProfileLinkAcceptedTextPresent(afterInputXml, targetLink)) {
    if (isAcpPad(padCode)) {
      await tapCloud720Point(config, padCode, 360, 360, 500);
    } else {
      await tapViaAdbAbsolute(config, padCode, inputTapPoint.x, inputTapPoint.y, 500);
    }
    await clearFocusedTextInput(config, padCode, 300);
    await typeTextViaAndroidInputText(config, padCode, linkInputText, 1600);
    await assertThreadsActionNotBlocked(config, padCode, "連結修改重新輸入網址後檢測到帳號狀態阻斷");
    afterInputXml = await dumpUiXml(config, padCode).catch(() => "");
  }

  onProgress?.({ step: "保存链接...", done: false });
  if (isAcpPad(padCode)) {
    await tapCloud720Point(config, padCode, 666, 1515, 1200).catch(() => undefined);
  } else {
    const keyboardConfirmTarget = await scaleReferencePointToPhysicalTap(config, padCode, { x: 666, y: 1515 }, FIXED_VMOS_SCREEN);
    await tapViaAdbAbsolute(config, padCode, keyboardConfirmTarget.x, keyboardConfirmTarget.y, 1200).catch(() => undefined);
  }
  await delay(700);
  await assertThreadsActionNotBlocked(config, padCode, "連結修改準備保存時檢測到帳號狀態阻斷");
  const savePatterns = [/^完成$|^Done$|^儲存$|^保存$|^Save$|^新增$|^添加$|^Add$/i];
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const currentXml = await dumpUiXml(config, padCode).catch(() => "");
    await assertThreadsActionNotBlocked(config, padCode, "連結修改保存時檢測到帳號狀態阻斷");
    if (isThreadsPostOptionsOrThreadDetailUiXml(currentXml)) {
      const currentShot = await screenshot(config, padCode).catch(() => undefined);
      throw new Error(`保存链接前已离开链接编辑页面${currentShot ? `，截图：${currentShot}` : ""}`);
    }
    const saveTarget = findThreadsTextTargetFromUiXml(currentXml, savePatterns, { maxY: 220, preferTop: true });
    if (!saveTarget) {
      if (isAcpPad(padCode)) {
        await tapCloud720Point(config, padCode, 640, 145, 2200);
      } else {
        const doneFallback = await scaleReferencePointToPhysicalTap(config, padCode, { x: 640, y: 145 }, FIXED_VMOS_SCREEN);
        await tapViaAdbAbsolute(config, padCode, doneFallback.x, doneFallback.y, 2200);
      }
    } else {
      const saveTapPoint = await scaleUiXmlPointToPhysicalTap(config, padCode, saveTarget);
      await tapViaAdbAbsolute(config, padCode, saveTapPoint.x, saveTapPoint.y, 2600);
    }
    const nextXml = await dumpUiXml(config, padCode).catch(() => "");
    await assertThreadsActionNotBlocked(config, padCode, "連結修改保存後檢測到帳號狀態阻斷");
    if (/編輯個人檔案|编辑个人档案|Edit profile/i.test(normalizeSingleLine(nextXml)) && threadsProfileLinkAcceptedTextPresent(nextXml, targetLink)) {
      continue;
    }
    if (!/新增連結|新增链接|Add link|URL|網址|网址/i.test(normalizeSingleLine(nextXml))) {
      break;
    }
  }

  const beforeFinalXml = await dumpUiXml(config, padCode).catch(() => "");
  if (/新增連結|新增链接|Add link|URL|網址|网址|編輯個人檔案|编辑个人档案|Edit profile/i.test(normalizeSingleLine(beforeFinalXml))) {
    await execAdbForText(config, padCode, "input keyevent KEYCODE_BACK", 8_000, 800).catch(() => "");
    await delay(1800);
    await assertThreadsActionNotBlocked(config, padCode, "連結修改返回資料頁後檢測到帳號狀態阻斷");
  }
  await dismissThreadsSystemCrashDialogIfPossible(config, padCode).catch(() => false);
  await delay(700);
  const finalXml = await dumpUiXml(config, padCode).catch(() => "");
  const finalShot = await screenshot(config, padCode).catch(() => undefined);
  const verified = threadsProfileLinkAcceptedTextPresent(finalXml, targetLink);
  onProgress?.({ step: verified ? "个人简介链接已更新" : "链接已提交，等待人工确认", done: true });

  return {
    ok: true,
    state: verified ? "verified" : "submitted",
    detail: verified ? "Threads 个人简介中已看到目标链接" : "已完成保存动作，但当前截图/XML 未直接确认链接显示",
    screenshotUrl: finalShot,
  };
}

export async function queryThreadsAccount(
  config: VmosConfig,
  padCode: string,
): Promise<PadAccountInfo> {
  // Explicit status checks must verify the real VMOS foreground state.
  // Android AccountManager can retain old Instagram/Threads accounts after app
  // data is cleared, so it is only usable as metadata after the profile page is
  // confirmed below. Trusting it first creates false "logged in" states.
  const profilePage = await openThreadsProfileForAccountQuery(config, padCode).catch((error) => ({
    ok: false as const,
    error: error instanceof Error ? error.message : String(error),
  }));
  if (!profilePage.ok) {
    return { padCode, platform: "threads", method: "failed", error: profilePage.error, screenshotUrl: profilePage.screenshotUrl };
  }

  let uiProfileCue = false;
  let uiXmlHadNodes = false;

  // ── 方案一：只从 Threads 个人页 UI 提取账号 ───────────────────────────────
  try {
    const uiXml = await dumpUiXml(config, padCode).catch(() => "");
    uiXmlHadNodes = /<node\b/i.test(uiXml);
    uiProfileCue = uiXml ? hasThreadsProfileUiCue(uiXml) : false;
    const username = uiXml ? extractThreadsProfileUsernameFromUiXml(uiXml) : null;
    if (username) {
      const result = { padCode, platform: "threads" as const, username, loggedIn: true, method: "adb" as const, screenshotUrl: profilePage.screenshotUrl };
      rememberThreadsAccountQuery(padCode, result);
      return result;
    }
    if (uiXmlHadNodes && !uiProfileCue && !profilePage.profileLikely) {
      return { padCode, platform: "threads", method: "failed", error: "未能确认当前画面是 Threads 个人页，已停止账号猜测", screenshotUrl: profilePage.screenshotUrl };
    }
  } catch {}

  // VMOS ADB task output can truncate long uiautomator XML before the profile
  // username appears. For account checks, query only short text attributes so
  // the username/profile cues fit inside the task result.
  try {
    const texts = await dumpUiTextAttributes(config, padCode);
    if (texts.length > 0) {
      uiProfileCue = uiProfileCue || hasThreadsProfileTextCue(texts);
      const username = extractThreadsProfileUsernameFromTexts(texts);
      if (username) {
        const result = { padCode, platform: "threads" as const, username, loggedIn: true, method: "adb" as const, screenshotUrl: profilePage.screenshotUrl };
        rememberThreadsAccountQuery(padCode, result);
        return result;
      }
    }
  } catch {}

  // ── 方案二：仅在已打开个人页后使用截图辅助识别 ───────────────────────────
  try {
    if (!profilePage.profileLikely && !uiProfileCue && uiXmlHadNodes) {
      return { padCode, platform: "threads", method: "failed", error: "未能确认当前画面是 Threads 个人页，已停止视觉识别", screenshotUrl: profilePage.screenshotUrl };
    }
    const { callGemini, extractText, getInlineData } = await import("./gemini-client");

    const shotUrl = profilePage.screenshotUrl || await screenshot(config, padCode);
    const inlineData = await getInlineData(shotUrl).catch(() => null);
    if (!inlineData) throw new Error("截图获取失败");

    const raw = await callGemini(
      PUBLISH_VERIFY_MODEL,
      [{
        role: "user",
        parts: [
          {
            text: [
              "这是一张 Android 手机截图。只允许在 Threads 个人主页/Profile 页顶部或个人资料区识别已登录账号用户名。",
              "如果截图不是 Threads 个人主页，或只看到浏览器/Google/桌面/首页信息，必须返回 null。",
              "请找出个人主页上的用户名，通常以 @ 开头，或显示在头像/简介附近。",
              "只输出纯 JSON，格式：{\"username\":\"找到的用户名\",\"email\":\"找到的邮箱或null\"}",
              "如果找不到任何账号信息，输出：{\"username\":null,\"email\":null}",
              "不要输出 JSON 以外的任何内容。",
            ].join("\n"),
          },
          { inlineData },
        ],
      }],
      { maxOutputTokens: 120, temperature: 0 },
    );

    const rawText = (extractText(raw) || "").trim().replace(/^```json\s*/i, "").replace(/```\s*$/, "");
    if (rawText) {
      const jsonMatch = rawText.match(/\{[\s\S]*?\}/);
      if (jsonMatch) {
        try {
          const json: { username?: string | null; email?: string | null } = JSON.parse(jsonMatch[0]);
          const username = json.username && json.username !== "null"
            ? normalizeThreadsProfileUsername(json.username)
            : undefined;
          const email = json.email && json.email !== "null" ? json.email : undefined;
          if (username || email) {
            const result = { padCode, platform: "threads" as const, username, email, loggedIn: true, method: "vision" as const, screenshotUrl: shotUrl };
            rememberThreadsAccountQuery(padCode, result);
            return result;
          }
        } catch {}
      }
    }
  } catch {}

  const accountManagerAccount = profilePage.profileLikely || uiProfileCue
    ? await queryThreadsAccountFromAndroidAccountManager(config, padCode, 8_000).catch(() => null)
    : null;
  if (accountManagerAccount?.username || accountManagerAccount?.email) {
    const result = {
      padCode,
      platform: "threads" as const,
      username: accountManagerAccount.username,
      email: accountManagerAccount.email,
      loggedIn: true,
      method: "adb" as const,
      screenshotUrl: profilePage.screenshotUrl,
    };
    rememberThreadsAccountQuery(padCode, result);
    return result;
  }

  if (profilePage.profileLikely || uiProfileCue) {
    const result = {
      padCode,
      platform: "threads" as const,
      loggedIn: true,
      method: "adb" as const,
      error: "已确认进入 Threads 个人页，但未识别到可读用户名",
      screenshotUrl: profilePage.screenshotUrl,
    };
    rememberThreadsAccountQuery(padCode, result);
    return result;
  }

  return { padCode, platform: "threads", method: "failed", error: "未识别到账号", screenshotUrl: profilePage.screenshotUrl };
}

export type ThreadsAccountHotMetrics = {
  padCode: string;
  platform: "threads";
  username?: string;
  followers?: number;
  following?: number;
  likes?: number;
  views?: number;
  posts?: number;
  refreshedAt: string;
  method: "adb" | "vision" | "failed";
  screenshotUrl?: string;
  rawText?: string;
  error?: string;
};

function parseThreadsCompactMetricValue(raw: string): number | undefined {
  const normalized = String(raw || "")
    .trim()
    .replace(/,/g, "")
    .replace(/\s+/g, "");
  const match = normalized.match(/(\d+(?:\.\d+)?)([kKmM万萬億亿]?)/);
  if (!match) return undefined;
  const base = Number(match[1]);
  if (!Number.isFinite(base)) return undefined;
  const unit = match[2];
  const multiplier = /[kK]/.test(unit) ? 1_000
    : /[mM]/.test(unit) ? 1_000_000
      : /[万萬]/.test(unit) ? 10_000
        : /[億亿]/.test(unit) ? 100_000_000
          : 1;
  return Math.round(base * multiplier);
}

function assignThreadsHotMetric(out: Partial<ThreadsAccountHotMetrics>, label: string, value: number | undefined) {
  if (typeof value !== "number") return;
  if (/粉絲|粉丝|followers?/i.test(label)) out.followers = value;
  else if (/追蹤中|关注中|following/i.test(label)) out.following = value;
  else if (/串文|帖子|貼文|posts?|threads/i.test(label)) out.posts = value;
  else if (/讚|赞|likes?/i.test(label)) out.likes = value;
  else if (/瀏覽|浏览|觀看|观看|views?|plays?|impressions?/i.test(label)) out.views = value;
}

function extractThreadsAccountHotMetricsFromTexts(texts: string[]): Partial<ThreadsAccountHotMetrics> {
  const clean = texts.map((text) => normalizeSingleLine(text)).filter(Boolean);
  const out: Partial<ThreadsAccountHotMetrics> = {};
  const joined = clean.join("\n");
  const combinedPattern = /(\d+(?:[.,]\d+)?\s*(?:[kKmM万萬億亿])?)\s*(粉絲|粉丝|followers?|追蹤中|关注中|following|串文|帖子|貼文|posts?|threads|讚|赞|likes?|瀏覽|浏览|觀看|观看|views?|plays?|impressions?)/gi;
  for (const match of joined.matchAll(combinedPattern)) {
    assignThreadsHotMetric(out, match[2] || "", parseThreadsCompactMetricValue(match[1] || ""));
  }
  for (let index = 0; index < clean.length; index += 1) {
    const current = clean[index] || "";
    const next = clean[index + 1] || "";
    const prev = clean[index - 1] || "";
    if (/粉絲|粉丝|followers?|追蹤中|关注中|following|串文|帖子|貼文|posts?|threads|讚|赞|likes?|瀏覽|浏览|觀看|观看|views?|plays?|impressions?/i.test(current)) {
      assignThreadsHotMetric(out, current, parseThreadsCompactMetricValue(prev) ?? parseThreadsCompactMetricValue(next));
    } else if (/粉絲|粉丝|followers?|追蹤中|关注中|following|串文|帖子|貼文|posts?|threads|讚|赞|likes?|瀏覽|浏览|觀看|观看|views?|plays?|impressions?/i.test(next)) {
      assignThreadsHotMetric(out, next, parseThreadsCompactMetricValue(current));
    }
  }
  return out;
}

export async function queryThreadsAccountHotMetrics(
  config: VmosConfig,
  padCode: string,
  onProgress?: (progress: PublishProgress) => void,
): Promise<ThreadsAccountHotMetrics> {
  const refreshedAt = new Date().toISOString();
  const profilePage = await openThreadsProfileForAccountQuery(config, padCode, onProgress).catch((error) => ({
    ok: false as const,
    error: error instanceof Error ? error.message : String(error),
  }));
  if (!profilePage.ok) {
    return {
      padCode,
      platform: "threads",
      refreshedAt,
      method: "failed",
      error: profilePage.error,
      screenshotUrl: profilePage.screenshotUrl,
    };
  }

  const uiXml = await dumpUiXml(config, padCode).catch(() => "");
  const textsFromXml = (uiXml.match(/<node\b[^>]*>/g) ?? [])
    .flatMap((node) => [
      decodeXmlAttr(getXmlAttr(node, "text")),
      decodeXmlAttr(getXmlAttr(node, "content-desc")),
    ])
    .map((text) => normalizeSingleLine(text))
    .filter(Boolean);
  const shortTexts = await dumpUiTextAttributes(config, padCode).catch(() => []);
  const texts = Array.from(new Set([...textsFromXml, ...shortTexts.map((text) => normalizeSingleLine(text)).filter(Boolean)]));
  const stats = extractThreadsAccountHotMetricsFromTexts(texts);
  const username = extractThreadsProfileUsernameFromTexts(texts)
    || (uiXml ? extractThreadsProfileUsernameFromUiXml(uiXml) : null)
    || undefined;
  return {
    padCode,
    platform: "threads",
    username,
    followers: stats.followers,
    following: stats.following,
    likes: stats.likes,
    views: stats.views,
    posts: stats.posts,
    refreshedAt,
    method: "adb",
    screenshotUrl: profilePage.screenshotUrl,
    rawText: texts.slice(0, 80).join(" | "),
    error: (!stats.followers && !stats.following && !stats.likes && !stats.views && !stats.posts)
      ? "已进入 Threads 个人页，但未识别到可用热度数字"
      : undefined,
  };
}

export async function publishPost(
  config: VmosConfig,
  task: PublishTask,
  onProgress: (p: PublishProgress) => void,
  options: PublishRunOptions = {},
): Promise<PublishResult | void> {
  try {
    options.cancellationToken?.throwIfCancelled?.();
    if (task.platform === "telegram") {
      if (task.mediaUrl) {
        const isVideoMedia = isVideoMediaUrl(task.mediaUrl);
        const mediaLabel = isVideoMedia ? "视频" : "图片";
        onProgress({ step: `写入 Telegram ${mediaLabel}到智能體手機...`, done: false });
        await ensurePermissions(config, task.padCode, TELEGRAM_PACKAGE, MEDIA_PERMISSIONS);
        const remotePath = buildStableDeviceMediaRemotePath("telegram_group", task.mediaUrl);
        const stagedRemotePath = await stageMediaOnDevice(config, task.padCode, task.mediaUrl, remotePath, onProgress);
        options.cancellationToken?.throwIfCancelled?.();
        const contentUri = await queryMediaStoreContentUri(config, task.padCode, stagedRemotePath, isVideoMedia);
        if (!contentUri) {
          throw new Error(`${mediaLabel}已写入智能體手機，但未找到 MediaStore content:// 记录`);
        }
        return await publishTelegramGroupPost(config, {
          ...task,
          mediaContentUri: contentUri,
          mediaMimeType: getTelegramShareMimeType(task.mediaUrl),
        }, onProgress);
      }
      return await publishTelegramGroupPost(config, task, onProgress);
    }
    if (Array.isArray(config.accounts) && config.accounts.length > 1) {
      await listPads(config).catch(() => undefined);
    }
    if (task.platform === "threads") {
      return await publishThreads(config, task, onProgress, options);
    } else if (task.platform === "twitter") {
      await publishTwitter(config, task, onProgress);
    } else if (task.platform === "rednote") {
      return await publishRednoteWithRecovery(config, task, onProgress, options);
    } else {
      return await publishInstagram(config, task, onProgress);
    }
  } catch (err: unknown) {
    let msg = err instanceof Error ? err.message : String(err);
    const cancelled = isPublishCancellationMessage(msg);
    if (task.platform === "threads" && !cancelled && !/｜sample=/.test(msg)) {
      const samplePath = await captureThreadsPublishSample(config, task.padCode, {
        scenario: "publish-top-level-failure",
        mediaKind: !task.mediaUrl ? "text" : isVideoMediaUrl(task.mediaUrl) ? "video" : "image",
        step: "發布失敗",
        reason: msg,
      });
      msg = appendSamplePath(msg, samplePath);
    }
    onProgress({
      step: "發布失敗",
      done: true,
      error: msg,
      samplePath: extractSamplePathFromPublishMessage(msg),
      manualIntervention: !cancelled,
    });
    if (err instanceof Error && msg !== err.message) {
      throw new Error(msg);
    }
    throw err;
  }
}

