export function extractWarmupPostPreviewFromUiXml(uiXml: string): string {
  const values = Array.from(uiXml.matchAll(/\b(?:text|content-desc)="([^"]*)"/g))
    .map((match) => decodeXmlAttr(match[1] || "").trim())
    .filter(Boolean);
  const ignored = /^(关注|關注|已关注|已關注|热门|熱門|最新|最新貼文|熱門貼文|相关个人档案|相關個人檔案|查看动态|查看動態|分享新鲜事|分享新鮮事|回复|回覆|转发|轉發|申文|串文|取消|公開主頁|公开主页|私密主页|私密主頁|赞|讚|点赞|按讚|\d+|\d+[,.]?\d*次观看|\d+[,.]?\d*次觀看)$/;
  const candidates = values
    .map((value) => normalizeSingleLine(value))
    .filter((value) => value.length >= 4 && !ignored.test(value))
    .filter((value) => !/^[@#]?[a-z0-9_.-]+\s*(\d+\s*(分钟|小时|天)|\d+[mhds])?$/i.test(value));
  return normalizeSingleLine(candidates.join(" ")).slice(0, 120);
}

async function warmupExtractPostPreview(
  config: VmosConfig,
  padCode: string,
  screenshotUrl?: string,
  options: { allowVisionFallback?: boolean } = {},
): Promise<string> {
  const fallbackFromUi = async () => extractWarmupPostPreviewFromUiXml(await dumpUiXml(config, padCode).catch(() => ""));
  const uiPreview = await fallbackFromUi();
  if (uiPreview) return uiPreview.slice(0, 80);
  if (options.allowVisionFallback === false) return "";

  const shotUrl = screenshotUrl || await freezeScreenshotUrl(await screenshot(config, padCode));
  const inlineData = await getInlineData(shotUrl).catch(() => null);
  if (!inlineData) return "";

  const request = createTimeoutSignal(7000);
  try {
    const raw = await callGemini(
      PUBLISH_VERIFY_MODEL,
      [{
        role: "user",
        parts: [
          {
            text: `看这张 Threads 截图，提取当前屏幕中间区域最适合互动的那条帖子正文，最多 80 个中文字符。
优先提取主帖或当前可见回复上方的原帖内容，不要提取底部输入框、按钮、用户名、时间、点赞数。
只返回帖子正文，不要解释，不要输出“图片中的文字”。`,
          },
          { inlineData },
        ],
      }],
      { maxOutputTokens: 120, temperature: 0 },
      request.signal,
    );
    const text = normalizeSingleLine(extractText(raw))
      .replace(/^```(?:json)?\s*/i, "")
      .replace(/```\s*$/i, "")
      .replace(/^帖子正文[:：]\s*/i, "")
      .trim();
    const jsonText = text.match(/\{[\s\S]*?\}/)?.[0];
    if (jsonText) {
      const parsed = JSON.parse(jsonText);
      return normalizeSingleLine(String(parsed.text || "")).slice(0, 80);
    }
    if (!text || /图片中的文字|無法|无法|看不到|不能/i.test(text)) return "";
    return text.slice(0, 80);
  } catch {
    return "";
  } finally {
    request.cleanup();
  }
}

export function sanitizeWarmupComment(text: string): string {
  const cleaned = normalizeSingleLine(text)
    .replace(/^["'“”‘’]+|["'“”‘’]+$/g, "")
    .replace(/^(?:Space|Enter|Backspace|Shift|QWERTY)\s*(?=\p{Script=Han})/iu, "")
    .replace(/[#@][^\s，。,.!?！？]+/g, "")
    .replace(/[^\p{L}\p{N}\s，。！？、,.!?]/gu, "")
    .replace(/[，。！？、,.!?]{2,}/g, (value) => value.slice(0, 1))
    .replace(/\s+/g, " ")
    .slice(0, 80)
    .trim();
  return collapseRepeatedWarmupComment(cleaned);
}

export function hasRepeatedWarmupCommentText(text: string, comment: string): boolean {
  const normalizedText = normalizeSingleLine(text).replace(/\s+/g, "");
  const normalizedComment = normalizeSingleLine(comment).replace(/\s+/g, "");
  if (!normalizedText || !normalizedComment || normalizedComment.length < 3) return false;
  return normalizedText.includes(`${normalizedComment}${normalizedComment}`);
}

function hasThreadsReplyComposerRepeatedText(uiXml: string, comment: string): boolean {
  const nodes = uiXml.match(/<node\b[^>]*>/g) ?? [];
  return nodes.some((node) => {
    const className = getXmlAttr(node, "class");
    const resourceId = getXmlAttr(node, "resource-id");
    if (!className.includes("EditText") && !/composer/i.test(resourceId)) return false;
    const text = decodeXmlAttr(getXmlAttr(node, "text"));
    return hasRepeatedWarmupCommentText(text, comment);
  });
}

function collapseRepeatedWarmupComment(text: string): string {
  const normalized = normalizeSingleLine(text).trim();
  const compact = normalized.replace(/\s+/g, "");
  if (compact.length < 10) return normalized;

  for (let unitLength = 3; unitLength <= Math.floor(compact.length / 2); unitLength += 1) {
    const unit = compact.slice(0, unitLength);
    let offset = 0;
    let repeats = 0;
    while (compact.slice(offset, offset + unitLength) === unit) {
      repeats += 1;
      offset += unitLength;
    }
    const tail = compact.slice(offset);
    const tailIsPartialRepeat = tail.length > 0 && unit.startsWith(tail);
    if (repeats >= 2 && (offset === compact.length || tailIsPartialRepeat)) {
      return unit;
    }
  }

  const repeatedMiddle = compact.match(/^(.{0,8}?)(.{4,24})\2+(.*)$/u);
  if (repeatedMiddle) {
    const prefix = repeatedMiddle[1] || "";
    const unit = repeatedMiddle[2] || "";
    const suffix = repeatedMiddle[3] || "";
    if (!suffix || unit.startsWith(suffix)) {
      return `${prefix}${unit}`.trim();
    }
  }

  return normalized;
}

function warmupCommentContentLength(comment: string): number {
  return comment.replace(/[\s，。！？、,.!?]/g, "").length;
}

function warmupCompactSemanticText(text: string): string {
  return sanitizeWarmupComment(text)
    .replace(/https?:\/\/\S+/g, "")
    .replace(/[#@][^\s，。,.!?！？]+/g, "")
    .replace(/\s+/g, "")
    .toLowerCase();
}

function warmupTextSimilarity(a: string, b: string): number {
  const left = warmupCompactSemanticText(a);
  const right = warmupCompactSemanticText(b);
  if (!left || !right) return 0;
  if (left === right) return 1;
  if (left.includes(right) || right.includes(left)) {
    return Math.min(left.length, right.length) / Math.max(left.length, right.length);
  }
  const grams = (value: string) => {
    const result = new Set<string>();
    for (let i = 0; i < value.length - 1; i += 1) result.add(value.slice(i, i + 2));
    if (!result.size) result.add(value);
    return result;
  };
  const aGrams = grams(left);
  const bGrams = grams(right);
  let shared = 0;
  for (const gram of aGrams) {
    if (bGrams.has(gram)) shared++;
  }
  return shared / Math.max(aGrams.size, bGrams.size);
}

export function isNearDuplicateWarmupComment(comment: string, previous: Iterable<string>): boolean {
  const current = warmupCompactSemanticText(comment);
  if (!current) return true;
  for (const old of previous) {
    if (warmupTextSimilarity(current, old) >= 0.72) return true;
  }
  return false;
}

function warmupPostPreviewKey(preview: string): string {
  return warmupCompactSemanticText(preview).slice(0, 80);
}

async function warmupVisibleTextContainsNearDuplicateComment(
  config: VmosConfig,
  padCode: string,
  comment: string,
): Promise<boolean> {
  const current = warmupCompactSemanticText(comment);
  if (!current || current.length < 4) return false;
  const uiXml = await dumpUiXml(config, padCode, 5_500).catch(() => "");
  if (!uiXml) return false;
  const visibleTexts = Array.from(uiXml.matchAll(/\b(?:text|content-desc)="([^"]*)"/g))
    .map((match) => decodeXmlAttr(match[1] || ""))
    .map((text) => sanitizeWarmupComment(text))
    .filter((text) => text.length >= 4 && text.length <= 80);
  return isNearDuplicateWarmupComment(comment, visibleTexts);
}

function isShortLowInfoWarmupPost(postPreview: string): boolean {
  const compact = normalizeSingleLine(postPreview)
    .replace(/https?:\/\/\S+/g, "")
    .replace(/[#@][^\s，。,.!?！？]+/g, "")
    .replace(/\s+/g, "");
  if (!compact) return false;
  if (/股|投資|投资|買|賣|买|卖|量能|財報|财报|市場|市场|回撤|部位|工作|職場|职场|會議|会议|同事|創業|创业|政策|新聞|新闻/.test(compact)) {
    return false;
  }
  return compact.length <= 12;
}

function isShortMarketMoodWarmupPost(postPreview: string): boolean {
  const compact = normalizeSingleLine(postPreview)
    .replace(/https?:\/\/\S+/g, "")
    .replace(/[#@][^\s，。,.!?！？]+/g, "")
    .replace(/\s+/g, "");
  if (!compact) return false;
  return compact.length <= 28
    && /明天|明日|明早|下週|下周|希望|可能|期待|會變好|会变好|大漲|大涨|轉好|转好/.test(compact)
    && /股市|台股|股票|市場|市场|行情|盤|盘/.test(compact);
}

function isUsableShortWarmupReaction(text: string): boolean {
  const comment = sanitizeWarmupComment(text);
  const length = warmupCommentContentLength(comment);
  if (length < 2 || length > 8) return false;
  if (/[的之和與跟及在]$/.test(comment)) return false;
  if (collapseRepeatedWarmupComment(comment).replace(/\s+/g, "") !== comment.replace(/\s+/g, "")) return false;
  if (/^(不错|不錯|支持|好看|认同|認同|学到了|學到了)$/.test(comment)) return false;
  return /[\p{L}\p{N}]/u.test(comment);
}

function isThinWarmupComment(comment: string): boolean {
  const compact = sanitizeWarmupComment(comment).replace(/\s+/g, "");
  if (!compact) return true;
  if (/^(這個|这个)?(角度|觀察|观察|分享|內容|内容|感受|日常)(很|蠻|蛮|挺)?(自然|有趣|有意思|值得看|有參考感|有参考感|有共鳴|有共鸣|有畫面|有画面感)$/.test(compact)) {
    return true;
  }
  if (/^(這點|这点|這段|这段|這件事|这件事)(我也)?(有感|能理解|蠻有共鳴|蛮有共鸣)$/.test(compact)) {
    return true;
  }
  if (/^(後續|后续)(變化|变化)?(想再看|想看)$/.test(compact)) {
    return true;
  }
  return false;
}

function isAwkwardWarmupComment(comment: string): boolean {
  const compact = sanitizeWarmupComment(comment).replace(/\s+/g, "");
  if (!compact) return true;
  if (/那個心臟|那个心脏|心臟明天|心脏明天|那個心情那個|那个心情那个/.test(compact)) return true;
  if (/^(明天那個|明天那个|那個明天|那个明天)/.test(compact)) return true;
  if (/明天.{0,4}明天/.test(compact)) return true;
  return false;
}

export function isUsableWarmupComment(text: string): boolean {
  const comment = sanitizeWarmupComment(text);
  const length = warmupCommentContentLength(comment);
  if (length < 6 || length > 55) return false;
  if (/[的之和與跟及在]$/.test(comment)) return false;
  if (collapseRepeatedWarmupComment(comment).replace(/\s+/g, "") !== comment.replace(/\s+/g, "")) return false;
  if (isAwkwardWarmupComment(comment)) return false;
  if (isThinWarmupComment(comment)) return false;
  if (/^(不错|不錯|支持|好看|很强|很強|真的强|真的強|有意思|认同|認同|学到了|學到了|值得看|继续关注|繼續關注|期待后续|期待後續|说得很到位|說得很到位|确实有启发|確實有啟發|这个点我认同|這個點我認同)$/.test(comment)) {
    return false;
  }
  return /[\p{L}\p{N}]/u.test(comment);
}

function warmupCommentPersonaText(persona?: WarmupCommentPersona): string {
  return normalizeSingleLine([
    persona?.name,
    persona?.description,
    persona?.style,
    persona?.personality,
    persona?.language,
    ...(persona?.interests || []),
  ].filter(Boolean).join(" "));
}

function isCleanWarmupSearchKeywordToken(keyword: string): boolean {
  const cleaned = normalizeSingleLine(String(keyword || "")).replace(/^#/, "").trim();
  if (cleaned.length < 2 || cleaned.length > 8 || !/\p{Script=Han}/u.test(cleaned)) return false;
  if (/[，。,.!?！？、：:；;（）()[\]{}]/.test(cleaned)) return false;
  if (/\d/.test(cleaned)) return false;
  if (/[與与和及跟]/.test(cleaned)) return false;
  if (/是|為|为|一位|一個|一个|的人|歲|岁|喜歡|喜欢|常提到|分享|觀察|观察|自然|專業|专业|擅長|擅长|清楚|務實|务实|語氣|语气|口語|口语/.test(cleaned)) return false;
  if (/^(人設|人设|人格|自然口語|自然口语|繁體中文|简体中文|台灣地區|台湾地区|不限|真實|真实|風格|风格|直接|故事化|左右|附近|最近|日常|分享|老師|老师|博主|達人|达人|中介|仲介|顧問|顾问|專家|专家)$/.test(cleaned)) return false;
  return true;
}

function isUsableWarmupSearchKeywordToken(keyword: string): boolean {
  const cleaned = normalizeSingleLine(String(keyword || "")).replace(/^#/, "").trim();
  if (cleaned.length < 2 || cleaned.length > 10 || !/\p{Script=Han}/u.test(cleaned)) return false;
  if (/[，。,.!?！？、：:；;（）()[\]{}]/.test(cleaned)) return false;
  if (/[A-Za-z0-9]/.test(cleaned)) return false;
  if (/^(人設|人设|人格|語氣|语气|口吻|風格|风格|繁體中文|简体中文|台灣地區|台湾地区|不限|真實|真实|左右|附近|最近|日常|分享)$/.test(cleaned)) return false;
  if (/^(老師|老师|博主|達人|达人|中介|仲介|顧問|顾问|專家|专家|作者|創作者|创作者)$/.test(cleaned)) return false;
  return true;
}

function normalizeWarmupSearchKeywordLiteral(keyword: string): string {
  return normalizeSingleLine(String(keyword || ""))
    .replace(/^#/, "")
    .replace(/[「」『』"'“”‘’]/g, "")
    .replace(/^\d{1,3}\s*(?:歲|岁|years?\s*old)\s*/i, "")
    .replace(/(?:人設|人设|人格|口吻|語氣|语气|風格|风格|繁體中文|简体中文|台灣地區|台湾地区)/gu, "")
    .replace(/^(?:關注|关注|分享|喜歡|喜欢|常提到|常聊|想看|研究|觀察|观察)/u, "")
    .trim();
}

function normalizeWarmupSearchKeywordCandidate(keyword: string, persona?: WarmupCommentPersona): string {
  const personaName = normalizeSingleLine(String(persona?.name || "")).trim();
  let cleaned = normalizeSingleLine(String(keyword || ""))
    .replace(/^#/, "")
    .replace(/[「」『』"'“”‘’]/g, "")
    .replace(/^\d{1,3}\s*(?:歲|岁|years?\s*old)\s*/i, "")
    .trim();
  if (personaName && cleaned === personaName) {
    cleaned = cleaned
      .replace(/(?:老師|老师|博主|達人|达人|中介|仲介|顧問|顾问|專家|专家|玩家|作者|創作者|创作者)$/u, "")
      .trim();
  }
  cleaned = cleaned
    .replace(/(?:人設|人设|人格|口吻|語氣|语气|風格|风格|繁體中文|简体中文|台灣地區|台湾地区)/gu, "")
    .replace(/^(?:關注|关注|分享|喜歡|喜欢|常提到|常聊|想看|研究|觀察|观察)/u, "")
    .replace(/(?:老師|老师|博主|達人|达人|中介|仲介|顧問|顾问|專家|专家|玩家|作者|創作者|创作者)$/u, "")
    .trim();
  return cleaned;
}

function extractGenericWarmupKeywordCandidates(
  persona?: WarmupCommentPersona,
  explicitKeywords: string[] = [],
): string[] {
  const personaName = normalizeSingleLine(String(persona?.name || "")).trim();
  const sources = [
    ...explicitKeywords,
    ...(persona?.interests || []),
  ];
  const candidates: string[] = [];
  for (const source of sources) {
    const text = normalizeSingleLine(String(source || ""));
    if (!text) continue;
    for (const piece of text.split(/[，,。.!！？?、；;：:\s/|｜與与和及跟]+/u)) {
      const cleaned = normalizeWarmupSearchKeywordLiteral(piece);
      if (cleaned) candidates.push(cleaned);
    }
  }
  const personaNameCore = normalizeWarmupSearchKeywordLiteral(personaName);
  if (personaNameCore && personaNameCore !== personaName) candidates.push(personaNameCore);

  const seen = new Set<string>();
  return candidates
    .map((item) => normalizeWarmupSearchKeywordLiteral(item))
    .filter((item) => item.length >= 2 && item.length <= 12)
    .filter((item) => isUsableWarmupSearchKeywordToken(item))
    .filter((item) => !personaName || item !== personaName)
    .filter((item) => {
      const key = item.toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .slice(0, 12);
}

export function buildWarmupInterestKeywords(
  persona?: WarmupCommentPersona,
  explicitKeywords: string[] = [],
): string[] {
  const seen = new Set<string>();
  const keywords: string[] = [];
  for (const source of [...explicitKeywords, ...(persona?.interests || [])]) {
    const text = normalizeSingleLine(String(source || ""));
    if (!text) continue;
    for (const piece of text.split(/[，,。.!！？?、；;：:\s/|｜與与和及跟]+/u)) {
      const cleaned = normalizeWarmupSearchKeywordLiteral(piece);
      if (cleaned.length < 2 || cleaned.length > 10) continue;
      if (!/[\u3400-\u9fff]/.test(cleaned)) continue;
      if (/[A-Za-z0-9，。,.!?！？、：:；;（）()[\]{}]/.test(cleaned)) continue;
      if (isBannedWarmupSearchKeyword(cleaned)) continue;
      const key = cleaned.toLowerCase();
      if (seen.has(key)) continue;
      seen.add(key);
      keywords.push(cleaned);
    }
  }
  return keywords.slice(0, 8);
}

function isBannedWarmupSearchKeyword(item: string): boolean {
  return /^(人設|人设|人格|自然口語|自然口语|繁體中文|简体中文|台灣地區|台湾地区|不限|真實|真实|風格|风格|直接|故事化|老師|老师|博主|達人|达人|中介|仲介|顧問|顾问|專家|专家)$/.test(normalizeSingleLine(item));
}

function isWarmupSearchKeywordRelevantToPersona(
  keyword: string,
  persona?: WarmupCommentPersona,
  explicitKeywords: string[] = [],
): boolean {
  const cleaned = normalizeWarmupSearchKeywordCandidate(keyword, persona);
  const literal = normalizeWarmupSearchKeywordLiteral(keyword);
  const normalizedKeyword = normalizeWarmupRelevanceText(literal || cleaned).replace(/\s+/g, "");
  if (!isUsableWarmupSearchKeywordToken(literal || cleaned)) return false;
  const personaText = warmupCommentPersonaText(persona);
  const explicitSet = new Set(explicitKeywords.map((item) => normalizeWarmupRelevanceText(item).replace(/\s+/g, "")));
  if (explicitSet.has(normalizedKeyword)) return true;
  const personaNormalized = normalizeWarmupRelevanceText(personaText).replace(/\s+/g, "");
  if (personaNormalized.includes(normalizedKeyword)) return true;
  const extracted = extractGenericWarmupKeywordCandidates(persona, explicitKeywords)
    .map((item) => normalizeWarmupRelevanceText(item).replace(/\s+/g, ""));
  if (extracted.includes(normalizedKeyword)) return true;
  for (const item of extracted) {
    if (item.length >= 2 && normalizedKeyword.length >= 2 && (item.includes(normalizedKeyword) || normalizedKeyword.includes(item))) return true;
  }
  return false;
}

type WarmupRelevanceResult = {
  relevant: boolean;
  score: number;
  matched: string[];
  keywords: string[];
  reason: string;
};

function normalizeWarmupRelevanceText(value: string): string {
  return normalizeSingleLine(value)
    .replace(/https?:\/\/\S+/g, " ")
    .replace(/[#@][^\s，。,.!?！？]+/g, " ")
    .replace(/[^\p{L}\p{N}\s]/gu, " ")
    .replace(/\s+/g, " ")
    .toLowerCase()
    .trim();
}

function buildWarmupRelevanceKeywordSet(
  persona?: WarmupCommentPersona,
  explicitKeywords: string[] = [],
): string[] {
  const expanded = extractGenericWarmupKeywordCandidates(persona, explicitKeywords);

  const seen = new Set<string>();
  return expanded
    .map((item) => normalizeWarmupRelevanceText(String(item || "")).replace(/\s+/g, ""))
    .filter((item) => item.length >= 2 && item.length <= 16)
    .filter((item) => !/^(人設|人设|人格|自然口語|自然口语|繁體中文|简体中文|台灣地區|台湾地区|不限|真實|真实|風格|风格)$/.test(item))
    .filter((item) => {
      if (seen.has(item)) return false;
      seen.add(item);
      return true;
    })
    .slice(0, 24);
}

export function buildWarmupSearchKeywordCandidates(
  persona?: WarmupCommentPersona,
  explicitKeywords: string[] = [],
): string[] {
  const candidates = buildWarmupInterestKeywords(persona, explicitKeywords);
  const seen = new Set<string>();
  return candidates
    .map((item) => normalizeWarmupSearchKeywordLiteral(item))
    .filter((item) => isUsableWarmupSearchKeywordToken(item))
    .filter((item) => !isBannedWarmupSearchKeyword(item))
    .filter((item) => isWarmupSearchKeywordRelevantToPersona(item, persona, explicitKeywords))
    .filter((item) => {
      const key = item.toLowerCase().replace(/\s+/g, " ");
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .slice(0, 12);
}

async function buildWarmupSearchKeywords(
  persona?: WarmupCommentPersona,
  explicitKeywords: string[] = [],
): Promise<string[]> {
  const fallback = buildWarmupSearchKeywordCandidates(persona, explicitKeywords);
  if (fallback.length >= 2) return fallback;
  const personaText = warmupCommentPersonaText(persona);
  if (!personaText || !getGeminiEndpoint().apiKey) return fallback;
  const request = createTimeoutSignal(6_500);
  try {
    const raw = await callGemini(
      PUBLISH_VERIFY_MODEL,
      [{
        role: "user",
        parts: [{
          text: `根据这个 Threads 养号人设，生成 3-5 个最适合搜索相关内容的短关键词。
要求：
- 关键词必须直接对应人设兴趣/行业，不要抽取年龄、语言、语气、人格描述。
- 优先可在 Threads 搜索命中的自然短语。
- 必须全部是中文关键词，禁止英文、拼音、数字年龄、语言风格词。
- 只返回 JSON：{"keywords":["..."]}

人设：${personaText}
显式关键词：${explicitKeywords.join(", ")}`,
        }],
      }],
      { maxOutputTokens: 160, temperature: 0.2 },
      request.signal,
    );
    const text = normalizeSingleLine(extractText(raw)).replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/i, "");
    const jsonText = text.match(/\{[\s\S]*\}/)?.[0] || "";
    const parsed = jsonText ? JSON.parse(jsonText) : null;
    const modelKeywords = Array.isArray(parsed?.keywords) ? parsed.keywords.map((item: unknown) => String(item || "")) : [];
    const merged = [...modelKeywords, ...fallback];
    const seen = new Set<string>();
    return merged
      .map((item) => normalizeWarmupSearchKeywordLiteral(item))
      .filter((item) => item.length >= 2 && item.length <= 24)
      .filter((item) => /\p{Script=Han}/u.test(item))
      .filter((item) => isUsableWarmupSearchKeywordToken(item))
      .filter((item) => !isBannedWarmupSearchKeyword(item))
      .filter((item) => {
        const key = item.toLowerCase().replace(/\s+/g, " ");
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      })
      .slice(0, 12);
  } catch {
    return fallback;
  } finally {
    request.cleanup();
  }
}

function shuffleWarmupList<T>(items: T[]): T[] {
  const result = [...items];
  for (let i = result.length - 1; i > 0; i -= 1) {
    const j = warmupRandomInt(0, i);
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

export function scoreWarmupPostRelevance(
  postPreview: string,
  persona?: WarmupCommentPersona,
  explicitKeywords: string[] = [],
): WarmupRelevanceResult {
  const normalized = normalizeWarmupRelevanceText(postPreview).replace(/\s+/g, "");
  const keywords = buildWarmupRelevanceKeywordSet(persona, explicitKeywords);
  const matched: string[] = [];
  if (!normalized || normalized.length < 4 || !keywords.length) {
    return { relevant: false, score: 0, matched, keywords, reason: !normalized ? "empty-preview" : "no-keywords" };
  }

  let score = 0;
  for (const keyword of keywords) {
    if (keyword.length >= 2 && normalized.includes(keyword)) {
      matched.push(keyword);
      score += keyword.length >= 4 ? 5 : 3;
    }
  }

  const uniqueMatched = Array.from(new Set(matched)).slice(0, 8);
  const relevant = score >= 3 || uniqueMatched.some((item) => item.length >= 4);
  return {
    relevant,
    score,
    matched: uniqueMatched,
    keywords,
    reason: relevant ? `matched:${uniqueMatched.join(",")}` : "below-threshold",
  };
}

export function isUnsafeWarmupEngagementText(text: string): boolean {
  const normalized = normalizeSingleLine(decodeXmlAttr(text || ""));
  if (!normalized) return false;

  const modernPoliticalSignal = /共产党|共產黨|中共|民进党|民進黨|习近平|習近平|拜登|川普|郭文贵|郭文貴|政党|政黨|政治/i.test(normalized);
  const inflammatorySignal = /消灭|消滅|杀害|殺害|害死|屠杀|屠殺|仇恨|煽动|煽動|攻击|攻擊|辱骂|辱罵|骂|罵|人渣|畜生/i.test(normalized);
  if (modernPoliticalSignal && inflammatorySignal) return true;

  const severeEventSignal = /恐袭|恐襲|枪击|槍擊|杀人|殺人|命案|血腥|死亡|死伤|死傷|屠杀|屠殺|杀害|殺害/i.test(normalized);
  const politicizedArgumentSignal = /政治|政党|政黨|政府|政權|政权|選舉|选举|立場|立场|對立|对立/i.test(normalized);
  return severeEventSignal && politicizedArgumentSignal;
}

async function warmupSearchInterestSurface(
  config: VmosConfig,
  padCode: string,
  keyword: string,
  report: (step: string) => void,
): Promise<void> {
  const screen = await getScreenSize(config, padCode).catch(() => BASE_SCREEN);
  const point = (xRatio: number, yRatio: number) => ({
    x: Math.round(screen.width * xRatio),
    y: Math.round(screen.height * yRatio),
  });
  const inspectAcpSearchResultsByVision = async (): Promise<boolean> => {
    if (!isAcpPad(padCode)) return true;
    report("搜索结果视觉检查中...");
    const captureSearchResultShot = async () => {
      for (let attempt = 0; attempt < 6; attempt += 1) {
        const shot = await withTimeout(
          screenshot(config, padCode).then((url) => freezeScreenshotUrl(url)),
          7_500,
          "ACP search result screenshot timeout",
        ).catch(() => "");
        if (!shot) {
          await delay(warmupRandomInt(900, 1400));
          continue;
        }
        const searchResultsVisualGate = await detectThreadsSearchResultsVisualGateLocally(shot).catch(() => false);
        const keyboardVisible = await detectAndroidKeyboardVisibleLocally(shot).catch(() => false);
        const searchResultsPage = keyboardVisible && !searchResultsVisualGate
          ? false
          : await detectThreadsSearchResultsPageLocally(shot).catch(() => false);
        const contentLoaded = keyboardVisible && !searchResultsVisualGate
          ? false
          : await detectThreadsSearchResultContentLoadedLocally(shot).catch(() => false);
        if (searchResultsVisualGate || (!keyboardVisible && (searchResultsPage || contentLoaded))) return shot;
        if (keyboardVisible) {
          report(`搜索结果视觉仍在等待键盘收起 ${attempt + 1}/6`);
          await execAdbForText(config, padCode, "input keyevent KEYCODE_SEARCH", 8_000, 450).catch(() => "");
        } else {
          report(`搜索结果视觉等待结果页稳定 ${attempt + 1}/6`);
        }
        await delay(warmupRandomInt(1200, 1800));
      }
      return "";
    };
    await delay(warmupRandomInt(2400, 3200));
    const shotUrl = await captureSearchResultShot();
    if (!shotUrl) {
      report("搜索结果截图未等到稳定结果页，按加载异常重新搜索");
      return false;
    }
    const xml = await dumpUiXml(config, padCode, 5_500).catch(() => "");
    if (looksLikeThreadsSearchResultsUiXml(xml, keyword)) {
      report(`搜索结果页 XML 已确认，继续视觉稀疏检查：${keyword}`);
    } else {
      report(`搜索结果页 XML 未确认，但截图已确认结果页，继续视觉稀疏检查：${keyword}`);
    }
    const sparse = shotUrl
      ? await withTimeout(
        detectThreadsSparseSearchResultsLocally(shotUrl),
        5_500,
        "ACP sparse search result visual check timeout",
      ).catch(() => ({ sparse: true, reason: "visual-timeout" }))
      : { sparse: false, reason: "screenshot-unavailable" };
    if (sparse.sparse) {
      report(`搜索结果视觉判断加载异常，准备重新搜索：${sparse.reason}`);
      return false;
    }
    report(`搜索结果视觉判断正常，直接进入浏览：${sparse.reason}`);
    return true;
  };

  report(`按人设关键词搜索相关内容：${keyword}`);
  let searchInput: { x: number; y: number } | null = null;
  for (let attempt = 0; attempt < 3 && !searchInput; attempt += 1) {
    let openedSearchDirectly = false;
    if (isAcpPad(padCode)) {
      report(`ACP 使用 Threads 搜索 deep link ${attempt + 1}/3`);
      await execAdbForText(
        config,
        padCode,
        "am start -a android.intent.action.VIEW -d 'barcelona://search' com.instagram.barcelona",
        15_000,
        1200,
      ).catch((error) => {
        report(`ACP 搜索 deep link 失败，回退到界面导航：${error instanceof Error ? error.message : String(error)}`);
      });
      await delay(warmupRandomInt(2200, 3200));
      openedSearchDirectly = true;
    } else {
      report(`搜索前确认 Threads 首页 ${attempt + 1}/3`);
      await withTimeout(
        ensureThreadsHomeFeed(config, padCode, (p) => report(p.step)),
        25_000,
        "warmup search ensure home timeout",
      ).catch((error) => {
        report(`搜索前回首页失败，继续尝试导航：${error instanceof Error ? error.message : String(error)}`);
      });
    }

    if (!openedSearchDirectly) {
      report(`打开搜索入口 ${attempt + 1}/3`);
      const beforeState = await withTimeout(
        classifyThreadsPageOnDevice(config, padCode),
        10_000,
        "warmup search before open classify timeout",
      ).catch(() => null);
      if (beforeState?.reason === "LOCAL_ANDROID_LAUNCHER") {
        report(`搜索入口前在桌面，重启 Threads 后重试 ${attempt + 1}/3`);
        await relaunchThreads(config, padCode, 3500).catch(() => undefined);
        await delay(warmupRandomInt(900, 1400));
        continue;
      }
      const beforeXml = await dumpUiXml(config, padCode).catch(() => "");
      if (looksLikeThreadsPostOptionsSheetUiXml(beforeXml) || looksLikeThreadsThreadDetailUiXml(beforeXml)) {
        report(`搜索入口前仍不在首页，返回后重试 ${attempt + 1}/3`);
        await execAdbForText(config, padCode, "input keyevent KEYCODE_BACK", 8_000, 700).catch(() => "");
        await delay(warmupRandomInt(900, 1400));
        continue;
      }
      const searchTab = beforeXml
        ? (findThreadsBottomSearchTabTarget(beforeXml) || findThreadsTopSearchButtonTarget(beforeXml))
        : null;
      const fallbackSearchPoint = searchTab ? null : point(0.28, 0.955);
      await warmupTapAbsoluteHuman(config, padCode, searchTab || fallbackSearchPoint, warmupRandomInt(900, 1400), 8);
      await delay(warmupRandomInt(900, 1300));
    }

    report(`等待搜索输入框 ${attempt + 1}/3`);
    if (!searchInput && openedSearchDirectly && isAcpPad(padCode)) {
      const currentShot = await withTimeout(
        screenshot(config, padCode).then((url) => freezeScreenshotUrl(url)),
        7_500,
        "ACP search open state screenshot timeout",
      ).catch(() => "");
      const onSearchResults = Boolean(
        currentShot
        && (
          await detectThreadsSearchResultsPageLocally(currentShot).catch(() => false)
          || await detectThreadsSearchResultContentLoadedLocally(currentShot).catch(() => false)
        )
      );
      const onProfile = Boolean(currentShot && await detectThreadsProfilePageLocally(currentShot).catch(() => false));
      if (onProfile) {
        await tapViaAdbAbsoluteQuick(config, padCode, point(0.61, 0.073).x, point(0.61, 0.073).y, 800).catch(() => undefined);
        await delay(900);
        searchInput = point(0.24, 0.147);
        report(`ACP 当前在个人页，点击顶部搜索图标后使用搜索输入坐标 ${attempt + 1}/3`);
      } else if (onSearchResults) {
        searchInput = point(0.43, 0.085);
        report(`ACP 当前在旧搜索结果页，点击顶部搜索词胶囊 ${attempt + 1}/3`);
      } else {
        searchInput = point(0.24, 0.147);
        report(`ACP 搜索页使用固定输入框坐标 ${attempt + 1}/3`);
      }
      await tapViaAdbAbsoluteQuick(config, padCode, searchInput.x, searchInput.y, 650).catch(() => undefined);
      await delay(550);
      break;
    }
    const searchXml = await dumpUiXml(config, padCode, 5_500).catch(() => "");
    searchInput = searchXml ? findThreadsSearchInputTarget(searchXml) : null;
    if (searchInput) break;

    if (looksLikeThreadsActivityUiXml(searchXml)) {
      report(`搜索入口误入动态消息页，回首页重试 ${attempt + 1}/3`);
      await warmupTapAbsoluteHuman(config, padCode, point(0.10, 0.955), warmupRandomInt(900, 1300), 8).catch(() => undefined);
      await delay(warmupRandomInt(900, 1400));
      continue;
    }

    report(`搜索输入框未出现，重试打开搜索页 ${attempt + 1}/3`);
    await execAdbForText(config, padCode, "input keyevent KEYCODE_BACK", 8_000, 500).catch(() => "");
    await delay(warmupRandomInt(900, 1400));
  }

  if (!searchInput) {
    throw new Error("未能打开 Threads 搜索页，未执行关键词输入");
  }

  await warmupTapAbsoluteHuman(config, padCode, searchInput, warmupRandomInt(650, 1050), 8);
  if (isAcpPad(padCode)) {
    await tapViaAdbAbsoluteQuick(config, padCode, searchInput.x, searchInput.y, 450).catch(() => undefined);
  }
  await clearFocusedTextInput(config, padCode, 350).catch(() => undefined);
  report(`输入搜索关键词：${keyword}`);
  await typeText(config, padCode, keyword, isAcpPad(padCode) ? warmupRandomInt(1800, 2600) : warmupRandomInt(1000, 1600));
  if (isAcpPad(padCode)) {
    const submitAndInspectAcpSearch = async () => {
      await delay(700);
      await execAdbForText(config, padCode, "input keyevent KEYCODE_SEARCH", 8_000, 700).catch(() => "");
      await delay(700);
      await tapViaAdbAbsoluteQuick(config, padCode, Math.round(screen.width * 0.88), Math.round(screen.height * 0.94), 450).catch(() => undefined);
      report(`等待搜索结果稳定后进行视觉检查：${keyword}`);
      await delay(warmupRandomInt(6500, 8500));
      return inspectAcpSearchResultsByVision();
    };
    report(`ACP 已输入中文关键词，直接提交并浏览搜索结果：${keyword}`);
    let resultLooksHealthy = await submitAndInspectAcpSearch();
    if (!resultLooksHealthy) {
      report(`搜索结果加载异常，重新搜索一次：${keyword}`);
      const resultSearchInput = point(0.43, 0.085);
      await tapViaAdbAbsoluteQuick(config, padCode, resultSearchInput.x, resultSearchInput.y, 500).catch(() => undefined);
      await delay(500);
      await clearFocusedTextInput(config, padCode, 350).catch(() => undefined);
      report(`重新输入搜索关键词：${keyword}`);
      await typeText(config, padCode, keyword, warmupRandomInt(1800, 2600));
      resultLooksHealthy = await submitAndInspectAcpSearch();
      report(`重新搜索后视觉判断：${resultLooksHealthy ? "正常" : "仍疑似异常，切换下一个关键词"}`);
      if (!resultLooksHealthy) {
        throw new Error(`搜索结果视觉判断持续异常：${keyword}`);
      }
    }
    report("搜索结果视觉检查完成，停留搜索结果页交给浏览链路接管");
    await delay(warmupRandomInt(1600, 2400));
    return;
  }
  const waitForKeywordWrittenOrResults = async (timeoutMs = 8_000) => {
    const deadline = Date.now() + timeoutMs;
    let lastXml = "";
    while (Date.now() < deadline) {
      const xml = await dumpUiXml(config, padCode).catch(() => "");
      lastXml = xml || lastXml;
      if (threadsSearchInputContainsKeyword(xml, keyword)) return { ok: true, xml };
      if (looksLikeThreadsSearchResultsUiXml(xml, keyword)) return { ok: true, xml };
      const text = normalizeSingleLine(decodeXmlAttr(xml));
      if (/EditText|搜索|搜尋|Search/i.test(xml) && text.includes(keyword) && scoreWarmupPostRelevance(text, undefined, [keyword]).relevant) {
        return { ok: true, xml };
      }
      await delay(900);
    }
    return { ok: false, xml: lastXml };
  };
  const initialWritten = await waitForKeywordWrittenOrResults(isAcpPad(padCode) ? 8_000 : 4_000);
  if (initialWritten.ok && looksLikeThreadsSearchResultsUiXml(initialWritten.xml, keyword)) {
    report(`搜索结果页已显示中文关键词，继续浏览：${keyword}`);
    await warmupWaitForScrollSettle(1200, 2200);
    await delay(warmupRandomInt(700, 1300));
    return;
  }
  if (isAcpPad(padCode) && !initialWritten.ok) {
    report(`搜索关键词首次未确认，重试中文输入：${keyword}`);
    await warmupTapAbsoluteHuman(config, padCode, searchInput, warmupRandomInt(650, 950), 8);
    await tapViaAdbAbsoluteQuick(config, padCode, searchInput.x, searchInput.y, 450).catch(() => undefined);
    await clearFocusedTextInput(config, padCode, 350).catch(() => undefined);
    await typeTextViaAdbBase64Broadcast(config, padCode, keyword, warmupRandomInt(1800, 2600), 12_000);
  }
  const afterRetryWritten = await waitForKeywordWrittenOrResults(isAcpPad(padCode) ? 8_000 : 4_000);
  if (isAcpPad(padCode) && !afterRetryWritten.ok) {
    report(`搜索关键词暂未从 UI XML 确认，已输入中文关键词并提交搜索验证：${keyword}`);
  }
  const afterInputXml = afterRetryWritten.xml || await dumpUiXml(config, padCode).catch(() => "");
  if (looksLikeThreadsSearchResultsUiXml(afterInputXml, keyword)) {
    report(`搜索结果页已显示中文关键词，继续浏览：${keyword}`);
    await warmupWaitForScrollSettle(1200, 2200);
    await delay(warmupRandomInt(700, 1300));
    return;
  }
  const proceedFromSearchResults = async (reason: string) => {
    report(`搜索结果页已可继续浏览（${reason}）：${keyword}`);
    if (isAcpPad(padCode)) {
      await tapViaAdbAbsoluteQuick(config, padCode, Math.round(screen.width * 0.56), Math.round(screen.height * 0.18), 450).catch(() => undefined);
      await delay(warmupRandomInt(900, 1300));
    }
    await delay(isAcpPad(padCode) ? warmupRandomInt(700, 1100) : warmupRandomInt(500, 900));
  };
  const waitForSubmittedSearchResults = async (timeoutMs = isAcpPad(padCode) ? 2_500 : 5_000) => {
    const deadline = Date.now() + timeoutMs;
    let lastXml = "";
    while (Date.now() < deadline) {
      const xml = await dumpUiXml(config, padCode).catch(() => "");
      lastXml = xml || lastXml;
      if (looksLikeThreadsSearchResultsUiXml(xml, keyword)) return { ok: true, xml };
      if (!isAcpPad(padCode)) {
        const shotUrl = await screenshot(config, padCode).then((url) => freezeScreenshotUrl(url)).catch(() => "");
        if (shotUrl && await detectThreadsSearchResultsPageLocally(shotUrl).catch(() => false)) return { ok: true, xml };
      }
      await delay(isAcpPad(padCode) ? 350 : 800);
    }
    return { ok: false, xml: lastXml };
  };
  const submitAttempts: Array<{ label: string; run: () => Promise<void> }> = [
    {
      label: "系统搜索键",
      run: async () => {
        await execAdbForText(config, padCode, "input keyevent KEYCODE_SEARCH", 8_000, 900).catch(() => "");
      },
    },
    {
      label: "软键盘搜索键",
      run: async () => {
        const keyPoint = point(0.91, 0.92);
        await tapViaAdbAbsoluteQuick(config, padCode, keyPoint.x, keyPoint.y, 1100).catch(() => undefined);
      },
    },
    {
      label: "回车键",
      run: async () => {
        await execAdbForText(config, padCode, "input keyevent KEYCODE_ENTER", 8_000, 900).catch(() => "");
      },
    },
  ];
  let submitted = await waitForSubmittedSearchResults(isAcpPad(padCode) ? 700 : 1200);
  for (const attempt of submitAttempts) {
    if (submitted.ok) break;
    report(`提交搜索关键词并等待结果页（${attempt.label}）：${keyword}`);
    await attempt.run();
    await delay(isAcpPad(padCode) ? 700 : 1200);
    submitted = await waitForSubmittedSearchResults(isAcpPad(padCode) ? 1600 : 4_000);
  }
  if (submitted.ok) {
    await proceedFromSearchResults("短确认通过");
    return;
  }
  if (isAcpPad(padCode)) {
    await proceedFromSearchResults("ACP 搜索提交后跳过长确认");
    return;
  }
  const stillInSearchInput = threadsSearchInputContainsKeyword(submitted.xml || "", keyword);
  throw new Error(`搜索提交后未进入结果页：${keyword}${stillInSearchInput ? "（仍停留在搜索输入框）" : ""}`);
}

async function warmupAssessPostRelevanceByModel(
  screenshotUrl: string | undefined,
  preview: string,
  cfg: WarmupConfig,
  keyword?: string,
): Promise<{ relevant: boolean; reason: string; preview?: string } | null> {
  const primaryTimeoutMs = 12_000;
  const fallbackTotalTimeoutMs = 24_000;
  const fallbackPerModelTimeoutMs = 9_000;
  if (!screenshotUrl) return null;
  const inlineData = await getInlineData(screenshotUrl).catch(() => null);
  if (!inlineData) {
    console.warn("[threads][warmup][relevance-model] unavailable: screenshot-inline-data-missing");
    return null;
  }
  const personaText = warmupCommentPersonaText(cfg.commentPersona);
  const prompt = `判断这张 Threads 截图中的当前主要内容是否适合这个养号人设浏览/互动。
只根据内容主题是否相关判断；不要因为语言不同就判不相关。
如果是搜索页，也可以判断可见搜索结果是否整体与人设相关。
如果主要内容明显不相关，例如体育/娱乐与房产人设无关，应判 false。
现代社会、新闻、生活观察、普通历史讨论都可以按主题相关性正常判断；只有主要内容是争议政治对骂、辱骂仇恨、煽动对立、暴力恶性事件或明显引战攻击时，才判 false 并跳过互动。
返回 JSON：{"relevant":true|false,"reason":"简短原因","preview":"你识别出的主要内容"}

人设：${personaText}
搜索关键词：${keyword || ""}
本地抽取正文：${preview || ""}`;
  const parseModelResult = (rawText: string): { relevant: boolean; reason: string; preview?: string } | null => {
    const text = normalizeSingleLine(rawText).replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/i, "");
    const jsonText = text.match(/\{[\s\S]*\}/)?.[0] || "";
    if (jsonText) {
      try {
        const parsed = JSON.parse(jsonText);
        return {
          relevant: Boolean(parsed?.relevant),
          reason: normalizeSingleLine(String(parsed?.reason || "model")).slice(0, 120),
          preview: normalizeSingleLine(String(parsed?.preview || "")).slice(0, 120),
        };
      } catch {
        // Fall through to parse short natural-language model replies.
      }
    }
    const negative = /不相关|不相關|无关|無關|不符合|不適合|不适合|irrelevant|not relevant|false/i.test(text);
    const positive = /相关|相關|符合|適合|适合|relevant|true/i.test(text);
    if (negative || positive) {
      return {
        relevant: positive && !negative,
        reason: normalizeSingleLine(text || "model-text").slice(0, 120),
        preview: "",
      };
    }
    return null;
  };
  let lastError = "";
  if (getGeminiEndpoint().apiKey) {
    const primaryRequest = createTimeoutSignal(primaryTimeoutMs);
    try {
      const raw = await callGemini(
        PUBLISH_VERIFY_MODEL,
        [{
          role: "user",
          parts: [
            { text: prompt },
            { inlineData },
          ],
        }],
        { maxOutputTokens: 180, temperature: 0 },
        primaryRequest.signal,
      );
      const parsed = parseModelResult(extractText(raw));
      if (parsed) return parsed;
      lastError = "primary-json-empty";
    } catch (error) {
      lastError = `primary:${error instanceof Error ? error.message : String(error)}`.slice(0, 180);
    } finally {
      primaryRequest.cleanup();
    }
  } else {
    lastError = "primary-api-key-missing";
  }

  const fallbackRequest = createTimeoutSignal(fallbackTotalTimeoutMs);
  try {
    const raw = await callThreadsAutoReplyVisionOcrModel(prompt, inlineData, fallbackRequest.signal, {
      maxTokens: 220,
      perModelTimeoutMs: fallbackPerModelTimeoutMs,
    });
    const parsed = parseModelResult(raw);
    if (parsed) return parsed;
    lastError = `${lastError || "fallback"};fallback-json-empty`;
  } catch (error) {
    lastError = `${lastError || "fallback"};fallback:${error instanceof Error ? error.message : String(error)}`.slice(0, 220);
  } finally {
    fallbackRequest.cleanup();
  }
  if (lastError) console.warn(`[threads][warmup][relevance-model] unavailable: ${lastError}`);
  return null;
}

async function warmupCurrentPostRelevance(
  config: VmosConfig,
  padCode: string,
  cfg: WarmupConfig,
  options: {
    allowVisionFallback?: boolean;
    report?: (step: string) => void;
    label?: string;
    keyword?: string;
    useModelMatch?: boolean;
    requireModelMatch?: boolean;
  } = {},
): Promise<{ preview: string; relevance: WarmupRelevanceResult; screenshotUrl?: string; modelMatch?: { relevant: boolean; reason: string; preview?: string } | null }> {
  if (options.report) options.report(`人设相关性检测中：${options.label || "读取当前内容"}，正在截图...`);
  const screenshotUrl = await withTimeout(
    screenshot(config, padCode).then((url) => freezeScreenshotUrl(url)),
    10_000,
    "warmup relevance screenshot timeout",
  ).catch(() => "");
  if (options.report) options.report(`人设相关性检测中：${options.label || "读取当前内容"}，正在解析推文...`);
  const preview = await withTimeout(
    warmupExtractPostPreview(config, padCode, screenshotUrl, { allowVisionFallback: options.allowVisionFallback }),
    options.allowVisionFallback ? 12_000 : 7_000,
    "warmup relevance preview timeout",
  ).catch(() => "");
  let relevance = scoreWarmupPostRelevance(preview, cfg.commentPersona, cfg.keywords || []);
  const shouldUseModelMatch = options.requireModelMatch || options.useModelMatch || (!relevance.relevant && options.useModelMatch);
  let modelMatch: { relevant: boolean; reason: string; preview?: string } | null = null;
  if (shouldUseModelMatch) {
    if (options.report) options.report(`人设相关性检测中：${options.label || "读取当前内容"}，等待模型判定...`);
    modelMatch = await withTimeout(
      warmupAssessPostRelevanceByModel(screenshotUrl, preview, cfg, options.keyword),
      40_000,
      "warmup model relevance timeout",
    ).catch(() => null);
  }
  if (modelMatch?.relevant) {
    relevance = {
      relevant: true,
      score: Math.max(5, relevance.score),
      matched: Array.from(new Set([...relevance.matched, "model-match"])).slice(0, 8),
      keywords: relevance.keywords,
      reason: `model:${modelMatch.reason}`,
    };
  }
  if (options.requireModelMatch && modelMatch?.relevant === false) {
    relevance = {
      relevant: false,
      score: 0,
      matched: relevance.matched,
      keywords: relevance.keywords,
      reason: `model-reject:${modelMatch.reason}`,
    };
  } else if (options.requireModelMatch && !modelMatch && relevance.relevant) {
    relevance = {
      ...relevance,
      reason: `local-strong-fallback:model-unavailable:${relevance.reason}`,
    };
  } else if (options.requireModelMatch && !modelMatch && !relevance.relevant) {
    relevance = {
      relevant: false,
      score: 0,
      matched: relevance.matched,
      keywords: relevance.keywords,
      reason: "model-unavailable",
    };
  }
  return {
    preview: preview || modelMatch?.preview || "",
    relevance,
    screenshotUrl,
    modelMatch,
  };
}

async function warmupEnsureRelevantSurface(
  config: VmosConfig,
  padCode: string,
  cfg: WarmupConfig,
  report: (step: string) => void,
  options: { phase?: "preflight" | "browse"; allowSearch?: boolean; forceSearch?: boolean } = {},
): Promise<{ ok: boolean; preview: string; reason: string }> {
  if (cfg.requireRelevantContent === false) return { ok: true, preview: "", reason: "disabled" };
  const keywords = buildWarmupInterestKeywords(cfg.commentPersona, cfg.keywords || []);
  if (!keywords.length) return { ok: true, preview: "", reason: "no-keywords" };

  if (!options.forceSearch) {
    const configuredProbePosts = Math.max(1, Math.min(5, Math.floor(cfg.relevanceProbePosts || (options.phase === "preflight" ? 3 : 2))));
    const probePosts = isAcpPad(padCode) ? Math.min(1, configuredProbePosts) : configuredProbePosts;
    for (let attempt = 0; attempt < probePosts; attempt += 1) {
      const current = await warmupCurrentPostRelevance(config, padCode, cfg, {
        allowVisionFallback: attempt === probePosts - 1,
        report,
        label: `首页探测 ${attempt + 1}/${probePosts}`,
      });
      if (current.relevance.relevant) {
        report(`已定位人设相关内容：${current.preview.slice(0, 42) || current.relevance.reason}`);
        return { ok: true, preview: current.preview, reason: current.relevance.reason };
      }
      report(`当前内容和人设不匹配，继续探测 ${attempt + 1}/${probePosts}：${current.preview.slice(0, 36) || current.relevance.reason}`);
      await warmupDwellLikeHuman(config, padCode, warmupRandomInt(900, 1800)).catch(() => undefined);
      await warmupScrollDown(config, padCode).catch(() => undefined);
      await delay(warmupRandomInt(900, 1800));
    }
  } else {
    report("按补点策略重新执行中文人设关键词搜索，避免在当前推荐流直接互动");
  }

  if (options.allowSearch === false) return { ok: false, preview: "", reason: "probe-unmatched" };

  const searchAttempts = Math.max(1, Math.min(5, Math.floor(cfg.relevanceSearchAttempts || 3)));
  report("正在整理中文人设搜索关键词...");
  const rawSearchKeywords = await buildWarmupSearchKeywords(cfg.commentPersona, cfg.keywords || []);
  const searchKeywords = shuffleWarmupList(rawSearchKeywords).slice(0, Math.max(searchAttempts, 3));
  report(`已整理中文人设搜索关键词：${searchKeywords.slice(0, Math.min(3, searchKeywords.length)).join("、") || "无"}`);
  for (let attempt = 0; attempt < Math.min(searchAttempts, searchKeywords.length); attempt += 1) {
    const keyword = searchKeywords[attempt];
    if (!keyword) continue;
    try {
      report(`选择人设搜索关键词 ${attempt + 1}/${Math.min(searchAttempts, searchKeywords.length)}：${keyword}`);
      await warmupSearchInterestSurface(config, padCode, keyword, report);
      if (isAcpPad(padCode) && /\p{Script=Han}/u.test(keyword)) {
        report(`ACP 已进入中文人设关键词搜索结果页，按关键词相关继续：${keyword}`);
        return { ok: true, preview: keyword, reason: `search-acp-query:${keyword}` };
      }
      for (let scan = 0; scan < 3; scan += 1) {
        const current = await warmupCurrentPostRelevance(config, padCode, cfg, {
          allowVisionFallback: true,
          report,
          label: `搜索结果 ${keyword} ${scan + 1}/3`,
          keyword,
          useModelMatch: true,
        });
        if (current.relevance.relevant) {
          report(`搜索命中人设相关内容：${keyword}｜${current.preview.slice(0, 42) || current.relevance.reason}`);
          return { ok: true, preview: current.preview, reason: `search:${keyword}:${current.relevance.reason}` };
        }
        if (current.modelMatch?.relevant !== false) {
          const searchXml = await dumpUiXml(config, padCode).catch(() => "");
          if (threadsSearchInputContainsKeyword(searchXml, keyword)) {
            report(`搜索页关键词已锁定人设相关内容，按搜索词继续：${keyword}`);
            return { ok: true, preview: current.preview || keyword, reason: `search-query:${keyword}` };
          }
        }
        const keywordScore = current.preview ? scoreWarmupPostRelevance(current.preview, cfg.commentPersona, [keyword]) : null;
        if (scan === 0 && keywordScore?.relevant && current.modelMatch?.relevant !== false) {
          report(`搜索页已按人设关键词打开且内容相关，按关键词相关继续：${keyword}`);
          return { ok: true, preview: current.preview, reason: `search-keyword:${keyword}` };
        }
        report(`搜索结果仍不匹配：${keyword} ${scan + 1}/3${current.modelMatch ? `｜模型：${current.modelMatch.reason}` : ""}`);
        await warmupScrollDown(config, padCode).catch(() => undefined);
        await delay(warmupRandomInt(1600, 2800));
      }
    } catch (error) {
      report(`人设关键词搜索失败：${keyword}｜${error instanceof Error ? error.message : String(error)}`);
      await relaunchThreads(config, padCode, 2200).catch(() => undefined);
    }
  }

  return { ok: false, preview: "", reason: `no-relevant-content:${keywords.slice(0, 4).join("/")}` };
}

function resolveWarmupCommentLanguage(persona?: WarmupCommentPersona): string {
  const hint = warmupCommentPersonaText(persona).toLowerCase();
  if (/english|英文/.test(hint)) return "英文";
  if (/日本語|日文|japanese/.test(hint)) return "日文";
  if (/粵語|粤语|廣東話|广东话|香港|hong\s*kong|cantonese/.test(hint)) return "香港繁體中文";
  if (/简体|簡體|大陆|大陸|mainland|zh-cn/.test(hint)) return "简体中文";
  return "台灣地區繁體中文";
}

function fallbackWarmupComment(
  postPreview: string,
  templates: string[] = [],
  persona?: WarmupCommentPersona,
): string {
  const explicit = templates.map(sanitizeWarmupComment).filter(isUsableWarmupComment);
  if (explicit.length) return explicit[warmupRandomInt(0, explicit.length - 1)];

  const text = postPreview.toLowerCase();
  if (isShortMarketMoodWarmupPost(postPreview)) {
    const comments = resolveWarmupCommentLanguage(persona) === "英文"
      ? ["Hope market goes up tomorrow", "Fingers crossed for tomorrow", "Hope tomorrow is green"]
      : ["期待", "希望明天股市大漲", "希望明天轉好", "明天開盤加油", "希望明天一片紅"];
    return comments[warmupRandomInt(0, comments.length - 1)];
  }
  if (isShortLowInfoWarmupPost(postPreview)) {
    const shortDefaults = resolveWarmupCommentLanguage(persona) === "英文"
      ? ["Yeah really", "True lol", "So real"]
      : ["真的欸", "哈哈真的", "也太懂", "笑死真的", "有夠真"];
    return shortDefaults[warmupRandomInt(0, shortDefaults.length - 1)];
  }
  const personaText = warmupCommentPersonaText(persona);
  if (personaText && !scoreWarmupPostRelevance(postPreview, persona, []).relevant) return "";
  if (personaText) return "";
  const topic = postPreview
    .replace(/https?:\/\/\S+/g, "")
    .replace(/[#@][^\s，。,.!?！？]+/g, "")
    .match(/[\u4e00-\u9fffA-Za-z0-9]{3,14}/)?.[0];
  if (topic) {
    const topicComments = [
      `${topic}這裡可以再拆細`,
      `${topic}後面變化才關鍵`,
      `${topic}這段判斷蠻實際`,
    ];
    return sanitizeWarmupComment(topicComments[warmupRandomInt(0, topicComments.length - 1)]);
  }
  const defaults = [
    "先看後續怎麼發展",
    "這段脈絡蠻值得看",
    "細節補上會更好判斷",
  ];
  return defaults[warmupRandomInt(0, defaults.length - 1)];
}

function warmupExtractCommentGroundingTerms(text: string): string[] {
  const normalized = normalizeSingleLine(text);
  const terms = new Set<string>();
  for (const match of normalized.matchAll(/[#＃]([\p{Script=Han}A-Za-z0-9_]{2,12})/gu)) {
    if (match[1]) terms.add(match[1]);
  }
  for (const match of normalized.matchAll(/[A-Z][A-Z0-9]{1,8}/g)) {
    terms.add(match[0]);
  }
  for (const match of normalized.matchAll(/[\p{Script=Han}]{2,8}/gu)) {
    const term = match[0];
    if (!/^(這個|这个|真的|可以|重要|關鍵|关键|後續|后续|比較|比较|服務|服务|分享|日常)$/.test(term)) terms.add(term);
  }
  return Array.from(terms).filter((term) => term.length >= 2);
}

function isWarmupCommentGroundedInPostAndPersona(
  commentText: string,
  postPreview: string,
  persona?: WarmupCommentPersona,
): boolean {
  const comment = sanitizeWarmupComment(commentText);
  const preview = normalizeSingleLine(postPreview);
  if (!comment || !preview || warmupCommentContentLength(preview) < 6) return false;
  if (isShortLowInfoWarmupPost(preview) || isShortMarketMoodWarmupPost(preview)) return true;

  const personaText = warmupCommentPersonaText(persona);
  const commentCompact = comment.replace(/\s+/g, "");
  const postTerms = warmupExtractCommentGroundingTerms(preview);
  if (postTerms.some((term) => commentCompact.includes(term))) return true;

  const previewCompact = sanitizeWarmupComment(preview).replace(/\s+/g, "");
  for (let i = 0; i < commentCompact.length - 1; i += 1) {
    const gram = commentCompact.slice(i, i + 2);
    if (previewCompact.includes(gram) && !/這個|这个|真的|可以|重要|關鍵|关键|後續|后续|比較|比较|服務|服务/.test(gram)) {
      return true;
    }
  }
  return false;
}

function fallbackAcpAsciiWarmupComment(postPreview: string): string {
  const text = postPreview.toLowerCase();
  if (/stock|market|price|invest|trade|股|投資|投资|買|卖|市場|市场/.test(text)) {
    return "Useful market view thanks";
  }
  if (/life|travel|food|日常|旅行|生活|心情/.test(text)) {
    return "Nice slice of daily life";
  }
  const defaults = [
    "Useful context thanks",
    "Good point worth noting",
    "Helpful view thanks",
    "Nice insight worth a look",
  ];
  return defaults[warmupRandomInt(0, defaults.length - 1)];
}

function isGenericWarmupComment(comment: string): boolean {
  const normalized = normalizeSingleLine(comment);
  return isThinWarmupComment(normalized)
    || /^(这个角度很有意思|這個角度很有意思|说得很到位|說得很到位|这个分享值得参考|這個分享值得參考|确实有启发|確實有啟發|这个点我认同|這個點我認同|这个分享很有共鸣|這個分享很有共鳴|這段觀察蠻值得看|這個角度很有參考感|後續變化想再看|這點我也有感|這段真的蠻有畫面|想看後續怎麼走|這個角度很自然|這段分享蠻有共鳴|這個觀察值得再看|這件事很有畫面感|這點我能理解|房仲服務細節真的關鍵|房仲細節服務真的關鍵|房市資訊透明很重要|買房前多比較才安心|房仲也要跟上AI工具|用AI輔助服務會更有感|房仲持續學新工具很重要|市場變快房仲也要成長|房仲服務真的不能停在原地|房市變化快專業要跟上|帶看前把需求對齊很重要|客戶需求抓準才省時間)$/.test(normalized);
}

export function finalizeWarmupComment(
  text: string,
  postPreview: string,
  templates: string[] = [],
  persona?: WarmupCommentPersona,
): string {
  const comment = sanitizeWarmupComment(text);
  if (isShortMarketMoodWarmupPost(postPreview)) {
    const shortMarketComment = warmupCommentContentLength(comment) <= 12
      && /期待|希望|明天|明日|大漲|大涨|轉好|转好|開盤|开盘|加油|green|tomorrow|market/i.test(comment)
      && !isAwkwardWarmupComment(comment)
      ? comment
      : "";
    return shortMarketComment || fallbackWarmupComment(postPreview, templates, persona);
  }
  if (isShortLowInfoWarmupPost(postPreview) && isUsableShortWarmupReaction(comment)) return comment;
  if (
    comment
    && isUsableWarmupComment(comment)
    && !isGenericWarmupComment(comment)
    && isWarmupCommentGroundedInPostAndPersona(comment, postPreview, persona)
  ) return comment;
  const fallback = fallbackWarmupComment(postPreview, templates, persona);
  if (isWarmupCommentGroundedInPostAndPersona(fallback, postPreview, persona)) return fallback;
  return "";
}

function finalizeGeneratedWarmupCommentOnly(
  text: string,
  postPreview: string,
  persona?: WarmupCommentPersona,
): string {
  const validation = validateGeneratedWarmupCommentCandidate(text, postPreview, persona);
  return validation.ok ? validation.comment : "";
}

type WarmupGeneratedCommentValidation =
  | { ok: true; comment: string }
  | { ok: false; candidate: string; reason: string };

function validateGeneratedWarmupCommentCandidate(
  text: string,
  postPreview: string,
  persona?: WarmupCommentPersona,
): WarmupGeneratedCommentValidation {
  const comment = sanitizeWarmupComment(text);
  const previewReadable = warmupCommentContentLength(postPreview) >= 6;
  if (!previewReadable) return { ok: false, candidate: comment, reason: "没有读到足够完整的推文内容" };
  if (!comment) return { ok: false, candidate: comment, reason: "模型没有输出评论正文" };
  if (!isCompleteGeneratedWarmupComment(comment, postPreview)) {
    return { ok: false, candidate: comment, reason: "评论不是完整自然的一句话，像半句或语义没收住" };
  }
  if (/逼(?!真)/.test(comment)) {
    return { ok: false, candidate: comment, reason: "评论出现不自然或疑似截断的词" };
  }
  if (isGenericWarmupComment(comment)) {
    return { ok: false, candidate: comment, reason: "评论太泛，缺少和当前推文的具体关联" };
  }
  if (isLongUnpunctuatedWarmupComment(comment)) {
    return { ok: false, candidate: comment, reason: "评论较长但没有自然停顿或标点" };
  }
  if (!isWarmupCommentGroundedInPostAndPersona(comment, postPreview, persona)) {
    return { ok: false, candidate: comment, reason: "评论没有贴住当前推文里的具体内容" };
  }
  return { ok: true, comment };
}

function finalizeThreadsAutoReplyModelReply(
  text: string,
  postPreview: string,
  commentText: string,
  persona?: WarmupCommentPersona,
): string {
  void postPreview;
  void commentText;
  const reply = sanitizeWarmupComment(text);
  if (!reply) return "";
  if (resolveWarmupCommentLanguage(persona) !== "英文" && !/\p{Script=Han}/u.test(reply)) return "";
  if (!isUsableWarmupComment(reply)) return "";
  if (isGenericWarmupComment(reply)) return "";
  if (isLongUnpunctuatedWarmupComment(reply)) return "";
  if (/(歡迎|欢迎|私訊|私信|諮詢|咨询|聯繫|联系|為您|为您|房源|看房|預約|预约|http|www\.|加我|私聊)/i.test(reply)) {
    return "";
  }
  return reply;
}

async function callThreadsAutoReplyTextModelWithFallback(
  contents: any[],
  generationConfig: Record<string, any>,
  signal: AbortSignal | undefined,
  isUsableResponse: (data: any) => boolean,
): Promise<any> {
  const result = await callTextUnderstandingModelWithFallback(
    "xai/grok-4.3",
    contents,
    generationConfig,
    signal,
    {
      isUsableResponse,
      isRetryableError: () => true,
      onFallback: (event) => {
        console.warn(`[threads][auto-reply][text-model] fallback ${event.from} -> ${event.to}: ${event.error.slice(0, 160)}`);
      },
    },
  );
  return result.data;
}

function hasWarmupCommentNaturalPause(comment: string): boolean {
  return /[，。！？、,.!?]/.test(comment);
}

function isLongUnpunctuatedWarmupComment(comment: string): boolean {
  const length = warmupCommentContentLength(comment);
  return length >= 16 && !hasWarmupCommentNaturalPause(comment);
}

function isSemanticallyIncompleteWarmupComment(comment: string): boolean {
  const normalized = sanitizeWarmupComment(comment);
  if (!normalized) return true;
  if (/[，、,]$/.test(normalized)) return true;
  if (/(看起來|看起来|聽起來|听起来|感覺|感觉|讓人|让人|有點|有点|有些|比較|比起來|比起来|很|蠻|蛮|挺|更加|更像|像是|不像|不是|可以|應該|应该|值得|適合|适合|想到)$/.test(normalized)) return true;
  if (/(很|挺|蠻|蛮|更|比較|比较)逼$/.test(normalized)) return true;
  if (/^(看著|看着|望著|望着|盯著|盯着)[^，。！？!?]{2,16}$/.test(normalized)) return true;
  if (/在[^，。！？!?]{1,16}(下|裡|里|中)?(看起來|看起来|顯得|显得)?$/.test(normalized)) return true;
  return false;
}

function isCompleteGeneratedWarmupComment(comment: string, postPreview: string): boolean {
  const normalized = sanitizeWarmupComment(comment);
  const length = warmupCommentContentLength(normalized);
  if (!normalized || !isUsableWarmupComment(normalized)) return false;
  if (/^(comment|comments|reply|replies|text|preview|summary)$/i.test(normalized)) return false;
  if (!/\p{Script=Han}/u.test(normalized)) return false;
  if (/^[，。、,.!?！？；;]/.test(normalized)) return false;
  if (/[，、,]$/.test(normalized)) return false;
  const trailingAfterPause = normalized.match(/[。！？!?]\s*([^。！？!?，、,.；;]{1,3})$/u)?.[1]?.trim() || "";
  if (trailingAfterPause && /\p{Script=Han}/u.test(trailingAfterPause)) return false;
  if (/(不會|不会|不能|可以|應該|应该|如果|因為|因为|所以|而且|但是|只是|也不)$/.test(normalized)) return false;
  if (/[的之和與与跟及在把對对給给為为是了着著會会能要想讓让我你妳他她它們们咱誰谁這这那有沒没還还很]$/.test(normalized)) return false;
  if (isSemanticallyIncompleteWarmupComment(normalized)) return false;
  if (/^(勇敢踏出第一步|加油|支持|不错|不錯|认同|認同)[，。,.!?！？]?$/.test(normalized)) return false;
  if (isShortLowInfoWarmupPost(postPreview)) return isUsableShortWarmupReaction(normalized) || length >= 8;
  if (length < 10) return false;
  return true;
}

export function isUsableGeneratedWarmupCommentForTest(comment: string, postPreview: string): boolean {
  return isCompleteGeneratedWarmupComment(comment, postPreview)
    && !isGenericWarmupComment(comment)
    && !isLongUnpunctuatedWarmupComment(comment);
}

function warmupModelText(raw: unknown): string {
  if (typeof raw === "string") return normalizeSingleLine(raw);
  return normalizeSingleLine(extractText(raw));
}

async function warmupGenerateCommentForPost(
  postPreview: string,
  templates: string[] = [],
  persona?: WarmupCommentPersona,
): Promise<string> {
  const cleanedPreview = normalizeSingleLine(postPreview).slice(0, 180);
  if (!cleanedPreview) return "";
  if (!getGeminiEndpoint().apiKey) return "";

  try {
    const templateHint = templates.length
      ? `\n可参考这些语气模板，但不要照抄：${templates.map((t) => `「${sanitizeWarmupComment(t)}」`).filter(Boolean).join("、")}`
      : "";
    const personaHint = warmupCommentPersonaText(persona);
    const language = resolveWarmupCommentLanguage(persona);
    const pickGeneratedComment = (rawText: string): string => {
      const text = warmupModelText(rawText)
        .replace(/^```(?:json)?\s*/i, "")
        .replace(/```\s*$/i, "");
      const candidates: string[] = [];
      const jsonText = text.match(/\{[\s\S]*?\}/)?.[0] || "";
      if (jsonText) {
        try {
          const parsed = JSON.parse(jsonText);
          const comments = Array.isArray(parsed?.comments)
            ? parsed.comments
            : [parsed?.comment, parsed?.reply, parsed?.text];
          for (const item of comments) candidates.push(String(item || ""));
        } catch {
          // Fall through to plain text parsing.
        }
      }
      candidates.push(...text.split(/\s*(?:\d+[.、)]|[-•])\s*/).filter(Boolean));
      candidates.push(...text.split(/[|｜\n]/).filter(Boolean));
      candidates.push(text);
      const seen = new Set<string>();
      for (const candidate of candidates) {
        const normalized = sanitizeWarmupComment(candidate);
        const key = normalized.replace(/\s+/g, "");
        if (!key || seen.has(key)) continue;
        seen.add(key);
        const final = finalizeGeneratedWarmupCommentOnly(normalized, cleanedPreview, persona);
        if (final) return final;
      }
      return "";
    };
    const callCommentTextModel = async (promptText: string) => {
      const request = createTimeoutSignal(14_000);
      let selectedComment = "";
      try {
        const result = await callTextUnderstandingModelWithFallback(
          PUBLISH_VERIFY_MODEL,
          [{
            role: "user",
            parts: [{ text: promptText }],
          }],
          { maxOutputTokens: 180, temperature: 0.8 },
          request.signal,
          {
            isUsableResponse: (data) => {
              selectedComment = pickGeneratedComment(warmupModelText(data));
              return Boolean(selectedComment);
            },
            isRetryableError: () => true,
            onFallback: (event) => {
              console.warn(`[threads][warmup][comment-text-model] fallback ${event.from} -> ${event.to}: ${event.error.slice(0, 160)}`);
            },
          },
        );
        if (selectedComment) return selectedComment;
        return pickGeneratedComment(warmupModelText(result.data));
      } finally {
        request.cleanup();
      }
    };
    const primary = await callCommentTextModel(`根據下面這條 Threads 推文內容，寫 3 條自然、簡短、像真人隨手留下的留言候選。

要求：
- 只輸出 JSON：{"comments":["候選1","候選2","候選3"]}，不要解釋。
- 語言：${language}；若人設明確指定其他語言，以人設為準，否則使用台灣地區繁體中文。
- 留言必須同時符合留言帳號人設和目標推文內容；不能只符合其中一邊。
- 必須提到或呼應推文中的具體名詞、場景、問題、風險、情緒或判斷；如果無法判斷具體內容，輸出空字串。
- 如果原帖本身很短或只是情緒句，可以只回 2 到 8 個有效字的自然語氣反應，例如「真的欸」「哈哈真的」「也太懂」，不要硬拉長。
- 如果原帖只是短句祝願行情變好，例如「明天股市心情會變好」，只回「期待」「希望明天股市大漲」「希望明天轉好」這類簡單短句，不要硬湊比喻或奇怪名詞。
- 如果原帖有明確資訊量，回 10 到 30 個有效字即可，留言要帶出原帖中的具體名詞、場景、風險、情緒或判斷。
- 短反應可以沒有標點；如果留言超過 15 個有效字，必須至少有一個自然停頓標點，例如逗號、句號、問號或驚嘆號，但不要堆疊標點。
- 不要把多個資訊點連成一整段無標點長句，語氣要像真人按人設自然說話。
- 必須是完整短句，不要停在“的”“和”“在”“把”“對”“給”“是”“了”這類未完成語尾，也不要以逗號或頓號結尾。
- 不要重複同一個詞或同一句話，不可輸出「這個角度很自然這個角度很自然」這類拼接內容。
- 內容必須貼合推文內容，不要泛泛說“不錯”“支持”“這個角度很自然”“這段分享蠻有共鳴”。
- 不要輸出舊模板句或萬用句，例如「值得參考」「這個角度很自然」「這段分享蠻有共鳴」「這個點我認同」；若人設有專業領域，也不要把留言寫成制式廣告。
- 語氣要符合留言帳號人設：${personaHint || "未指定，使用台灣 Threads 自然口語"}。
- 不要寫和人設領域明顯衝突的回覆；只要能自然呼應推文內容和人設口吻，就輸出一句具體留言，不要因為沒有命中固定詞而留空。
- 現代社會、新聞、生活觀察、普通歷史討論都可以正常留言；只有推文主要是在爭議政治對罵、辱罵仇恨、煽動對立、暴力惡性事件或明顯引戰攻擊時，才輸出空字串。
- 不要使用 hashtag、@、連結或表情符號。
- 不要提到你是 AI 或自動化。
${templateHint}

目標推文：${cleanedPreview}`);
    if (primary) return primary;
    return await callCommentTextModel(`重新根據下面 Threads 推文全文和目前留言帳號人設，寫 3 條自然短留言候選。

只輸出 JSON：{"comments":["候選1","候選2","候選3"]}，不要解釋。
要求：
- 使用台灣繁體中文。
- 10 到 30 個有效字。
- 短反應可以沒有標點；如果留言超過 15 個有效字，必須至少有一個自然停頓標點，例如逗號、句號、問號或驚嘆號，但不要堆疊標點。
- 不要把多個資訊點連成一整段無標點長句，語氣要像真人按目前人設自然說話。
- 必須是完整句子，不能只輸出半句，不能以逗號或頓號結尾。
- 不要表情符號、hashtag、@ 或連結。
- 必須自然像真人留言，語氣和用詞要符合目前人設：${personaHint || "未指定，使用台灣 Threads 自然口語"}。
- 不要硬銷售，不要模板句，不要把留言寫成客服廣告。
- 需要基於推文全文理解來回覆，可以直接呼應具體事件、問題、情緒、數字、場景或判斷，但不要受固定詞庫限制。
- 現代社會、新聞、生活觀察、普通歷史討論都可以正常留言；只有推文主要是在爭議政治對罵、辱罵仇恨、煽動對立、暴力惡性事件或明顯引戰攻擊時，才輸出空字串。
- 不要輸出空泛句，例如「值得參考」「這個角度很自然」「這段分享蠻有共鳴」「這個點我認同」。

目標推文：${cleanedPreview}`);
  } catch (error) {
    console.warn(`[threads][warmup][comment-text-model] unavailable: ${error instanceof Error ? error.message : String(error)}`.slice(0, 220));
    return "";
  }
}

async function createWarmupCommentFocusCrop(screenshotUrl: string): Promise<string | undefined> {
  const inlineData = await getInlineDataFromUrlOrLocalFile(screenshotUrl).catch(() => null);
  if (!inlineData?.data) return undefined;
  const source = Buffer.from(inlineData.data, "base64");
  const image = sharp(source);
  const metadata = await image.metadata();
  const width = Number(metadata.width || 0);
  const height = Number(metadata.height || 0);
  if (width < 240 || height < 480) return undefined;
  const top = Math.max(0, Math.floor(height * 0.07));
  const cropHeight = Math.max(
    Math.floor(height * 0.42),
    Math.min(height - top, Math.floor(height * 0.68)),
  );
  const dir = path.join(process.cwd(), ".runtime", "warmup-vision-crops");
  fs.mkdirSync(dir, { recursive: true });
  const out = path.join(dir, `comment-focus-${Date.now()}-${crypto.randomBytes(3).toString("hex")}.jpg`);
  await image
    .extract({ left: 0, top, width, height: cropHeight })
    .jpeg({ quality: 88 })
    .toFile(out);
  return out;
}

async function warmupGenerateCommentFromScreenshot(
  screenshotUrl: string | undefined,
  templates: string[] = [],
  persona?: WarmupCommentPersona,
  postPreviewHint = "",
): Promise<{ comment: string; preview: string }> {
  if (!screenshotUrl || !getGeminiEndpoint().apiKey) {
    return { comment: "", preview: "" };
  }
  const focusedScreenshot = await createWarmupCommentFocusCrop(screenshotUrl).catch(() => undefined);
  const inlineData = await getInlineDataFromUrlOrLocalFile(focusedScreenshot || screenshotUrl).catch(() => null);
  if (!inlineData) return { comment: "", preview: "" };

  const extractScreenshotPreviewHint = (rawText: string): string => {
    const text = warmupModelText(rawText)
      .replace(/^```(?:json)?\s*/i, "")
      .replace(/```\s*$/i, "");
    if (!text) return "";
    const jsonText = text.match(/\{[\s\S]*?\}/)?.[0];
    if (jsonText) {
      try {
        const parsed = JSON.parse(jsonText);
        return normalizeSingleLine(String(parsed.preview || parsed.summary || parsed["帖子摘要"] || parsed["摘要"] || "")).slice(0, 160);
      } catch {
        // Fall through to looser formats.
      }
    }
    const labeledPreview = text.match(/(?:帖子摘要|摘要|summary|preview)\s*[:：]\s*(.+)$/i)?.[1] || "";
    if (labeledPreview) return normalizeSingleLine(labeledPreview).slice(0, 160);
    const looseSummary = text.match(/(?:提取|抽取)?(?:帖子|貼文|推文)?(?:摘要|正文)\s*[:：]?\s*(.+)$/i)?.[1] || "";
    return normalizeSingleLine(looseSummary || text).slice(0, 160);
  };
  const buildFromPreviewHint = async (rawPreview: string): Promise<{ comment: string; preview: string } | null> => {
    const preview = normalizeSingleLine(rawPreview).slice(0, 160);
    if (warmupCommentContentLength(preview) < 6) return null;
    const generated = await warmupGenerateCommentForPost(preview, templates, persona).catch(() => "");
    const comment = finalizeGeneratedWarmupCommentOnly(generated, preview, persona);
    if (comment) {
      return { comment, preview };
    }
    return null;
  };
  const parseScreenshotCommentResult = (rawText: string): { comment: string; preview: string } | null => {
    const text = warmupModelText(rawText)
      .replace(/^```(?:json)?\s*/i, "")
      .replace(/```\s*$/i, "");
    if (!text) return null;
    const build = (commentText: string, previewText: string) => {
      const preview = normalizeSingleLine(previewText || postPreviewHint).slice(0, 120);
      const comment = finalizeGeneratedWarmupCommentOnly(commentText, preview, persona);
      return { comment, preview };
    };
    const jsonText = text.match(/\{[\s\S]*?\}/)?.[0];
    if (jsonText) {
      try {
        const parsed = JSON.parse(jsonText);
        const result = build(
          String(parsed.comment || parsed.reply || parsed["評論"] || parsed["评论"] || ""),
          String(parsed.preview || parsed.summary || parsed["帖子摘要"] || parsed["摘要"] || ""),
        );
        if (result.comment && result.preview) return result;
      } catch {
        // Fall through to parse looser model formats.
      }
    }
    if (/[|｜]/.test(text)) {
      const [commentPart, ...previewParts] = text.split(/[|｜]/);
      const result = build(commentPart, previewParts.join(" "));
      if (result.comment && result.preview) return result;
    }
    const labeledComment = text.match(/(?:評論|评论|comment|reply)\s*[:：]\s*(.+?)(?:\s+(?:帖子摘要|摘要|summary|preview)\s*[:：]|$)/i)?.[1] || "";
    const labeledPreview = text.match(/(?:帖子摘要|摘要|summary|preview)\s*[:：]\s*(.+)$/i)?.[1] || "";
    if (labeledComment && labeledPreview) {
      const result = build(labeledComment, labeledPreview);
      if (result.comment && result.preview) return result;
    }
    if (text.length <= 140) {
      const looseFirst = normalizeSingleLine(text.split(/\s{2,}|(?:帖子摘要|摘要|summary|preview)\s*[:：]/i)[0] || text);
      const firstChunk = (looseFirst.length > 42 ? looseFirst.slice(0, 42) : looseFirst).replace(/[的之和與与跟及在把對对給给為为是了着著，、,]$/u, "");
      const result = build(firstChunk, text);
      if (result.comment && result.preview) return result;
    }
    if (text.length <= 48 && isUsableWarmupComment(text) && !isGenericWarmupComment(text)) {
      const result = build(text, text);
      if (result.comment && result.preview) return result;
    }
    return null;
  };
  const prompt = `看圖，先完整讀取並理解 Threads 畫面中最適合互動的一條主帖，再基於完整理解寫一句自然留言，並提取帖子摘要。
留言語言：${resolveWarmupCommentLanguage(persona)}；若人設沒有明確指定語言，預設台灣地區繁體中文。
留言人設：${warmupCommentPersonaText(persona) || "未指定，使用台灣 Threads 自然口語"}。
優先完整閱讀畫面頂部到回覆輸入框上方的主帖文字；摘要要包含主帖的核心事實、對象、情緒/訴求、具體場景或數字，不要只抽幾個關鍵詞。
不要把貼文圖片內的聊天截圖、手機畫面文字、底部輸入框、鍵盤或推薦詞當成主帖正文。
如果主帖可見文字清楚，必須基於主帖全文理解輸出評論和摘要；只有完全看不清主帖文字時才留空。
評論必須同時貼合畫面中的帖子內容和留言人設；不能只寫人設口吻，也不能回和人設無關的內容。
必須提到或呼應帖子中的具體名詞、場景、問題、風險、情緒或判斷；如果畫面看不清楚或無法判斷具體內容，評論留空。
現代社會、新聞、生活觀察、普通歷史討論都可以正常留言；只有主帖主要是在爭議政治對罵、辱罵仇恨、煽動對立、暴力惡性事件或明顯引戰攻擊時，評論才留空。
如果帖子本身很短或只是情緒句，可以只回 2 到 8 個有效字的自然語氣反應，例如「真的欸」「哈哈真的」「也太懂」，不要硬拉長。
如果帖子有明確資訊量，評論必須貼合具體內容，10 到 30 個有效字即可，要帶出畫面中的具體名詞、場景、風險、情緒或判斷。
短反應可以沒有標點；如果評論超過 15 個有效字，必須至少有一個自然停頓標點，例如逗號、句號、問號或驚嘆號，但不要堆疊標點。
不要把多個資訊點連成一整段無標點長句，語氣要像真人按目前人設自然說話。
不要 hashtag、@、連結或表情符號，不要泛泛說“這個角度很有意思”“這個點我認同”“值得參考”“這個角度很自然”“這段分享蠻有共鳴”。
不要輸出舊模板句或萬用句，例如「值得參考」「這個角度很自然」「這段分享蠻有共鳴」「這個點我認同」；若人設領域有專業話術，也不要照抄成模板廣告。
若人設有明確領域，優先用人設口吻自然呼應帖子內容；不要因為沒有命中固定詞而留空，但也不要回和畫面明顯衝突的內容。
不要重複同一個詞或同一句話，不可輸出「這個角度很自然這個角度很自然」這類拼接內容。
留言必須是完整短句，不要停在“的”“和”“在”“把”“對”“給”“是”“了”這類未完成語尾，也不要以逗號或頓號結尾。
${templates.length ? `\n可参考这些语气模板，但不要照抄：${templates.map((t) => `「${sanitizeWarmupComment(t)}」`).filter(Boolean).join("、")}` : ""}
只按這個格式返回：評論|完整帖子摘要`;
  let lastError = "";
  const fallbackRequest = createTimeoutSignal(28_000);
  try {
    const raw = await callThreadsAutoReplyVisionOcrModel(prompt, inlineData, fallbackRequest.signal, {
      maxTokens: 220,
      perModelTimeoutMs: 12_000,
    });
    const parsed = parseScreenshotCommentResult(raw);
    if (parsed?.comment && parsed.preview) return parsed;
    const previewFromRaw = extractScreenshotPreviewHint(raw);
    const generatedFromPreview = await buildFromPreviewHint(previewFromRaw || postPreviewHint);
    if (generatedFromPreview?.comment && generatedFromPreview.preview) return generatedFromPreview;
    lastError = `vision-unparsed:${normalizeSingleLine(raw).slice(0, 120)}`;
  } catch (error) {
    lastError = `vision:${error instanceof Error ? error.message : String(error)}`.slice(0, 180);
  } finally {
    fallbackRequest.cleanup();
  }
  const request = createTimeoutSignal(10_000);
  try {
    const raw = await callGemini(
      PUBLISH_VERIFY_MODEL,
      [{
        role: "user",
        parts: [
          {
            text: prompt,
          },
          { inlineData },
        ],
      }],
      { maxOutputTokens: 120, temperature: 0.75 },
      request.signal,
    );
    const parsed = parseScreenshotCommentResult(extractText(raw));
    if (parsed?.comment && parsed.preview) return parsed;
    const previewFromRaw = extractScreenshotPreviewHint(extractText(raw));
    const generatedFromPreview = await buildFromPreviewHint(previewFromRaw || postPreviewHint);
    if (generatedFromPreview?.comment && generatedFromPreview.preview) return generatedFromPreview;
    lastError = `primary-unparsed:${normalizeSingleLine(extractText(raw)).slice(0, 80)}`;
  } catch (error) {
    lastError = `${lastError || "primary"};primary:${error instanceof Error ? error.message : String(error)}`.slice(0, 220);
  } finally {
    request.cleanup();
  }
  const generatedFromHint = await buildFromPreviewHint(postPreviewHint);
  if (generatedFromHint?.comment && generatedFromHint.preview) return generatedFromHint;
  if (lastError) console.warn(`[threads][warmup][comment-vision] unavailable: ${lastError}`);
  return { comment: "", preview: "" };
}

type ThreadsAutoReplyCandidate = {
  text: string;
  author?: string;
  score: number;
  key?: string;
  replyPoint?: { x: number; y: number };
  sourceScreenshotUrl?: string;
  debugReason?: string;
};

type ThreadsAutoReplyHistoryEntry = {
  key: string;
  padCode: string;
  postHash: string;
  commentIdentityKey?: string;
  commentAuthor?: string;
  commentPreview: string;
  replyPreview: string;
  repliedAt: string;
};

function getThreadsAutoReplyHistoryFile() {
  return process.env.THREADS_AUTO_REPLY_HISTORY_FILE
    || path.join(process.cwd(), ".runtime", "automatic-script", "threads-auto-reply-history.json");
}

function readThreadsAutoReplyHistory(): ThreadsAutoReplyHistoryEntry[] {
  try {
    const parsed = JSON.parse(fs.readFileSync(getThreadsAutoReplyHistoryFile(), "utf8"));
    return Array.isArray(parsed?.entries) ? parsed.entries : [];
  } catch {
    return [];
  }
}

function writeThreadsAutoReplyHistory(entries: ThreadsAutoReplyHistoryEntry[]) {
  const file = getThreadsAutoReplyHistoryFile();
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, JSON.stringify({ entries: entries.slice(-800) }, null, 2), "utf8");
}

export function loadThreadsAutoReplyRepliedSets(padCode: string) {
  const repliedKeys = new Set<string>();
  const repliedCommentIdentityKeys = new Set<string>();
  const repliedCommentTextKeys = new Set<string>();
  for (const entry of readThreadsAutoReplyHistory()) {
    if (entry.padCode !== padCode) continue;
    if (entry.key) repliedKeys.add(entry.key);
    const commentIdentityKey = entry.commentIdentityKey
      || buildThreadsAutoReplyRecentCommentIdentityKey(entry.padCode, entry.commentAuthor, entry.commentPreview);
    if (commentIdentityKey) repliedCommentIdentityKeys.add(commentIdentityKey);
    const textKey = buildThreadsAutoReplyRecentCommentTextKey(entry.padCode, entry.commentPreview);
    if (textKey) repliedCommentTextKeys.add(textKey);
  }
  return { repliedKeys, repliedCommentIdentityKeys, repliedCommentTextKeys };
}

function buildThreadsAutoReplyPostHash(padCode: string, postPreview: string, fallbackTexts: string[] = []) {
  const seed = normalizeSingleLine(postPreview || fallbackTexts.slice(0, 8).join("|")).slice(0, 360);
  return hashString(`${padCode}|${seed || "unknown-post"}`, 20);
}

function normalizeThreadsAutoReplyCommentIdentityText(commentText: string) {
  const variantMap: Record<string, string> = {
    "個": "个",
    "們": "们",
    "這": "这",
    "錯": "错",
    "讚": "赞",
    "麼": "么",
    "嗎": "吗",
    "蘋": "苹",
    "裡": "里",
    "裏": "里",
    "臺": "台",
    "灣": "湾",
    "點": "点",
  };
  return Array.from(normalizeSingleLine(commentText).toLowerCase())
    .map((char) => variantMap[char] || char)
    .join("")
    .replace(/\s+/g, "")
    .replace(/[，。！？、,.!?~～"“”'‘’]/g, "");
}

function buildThreadsAutoReplyCandidateIdentity(author: string | undefined, commentText: string) {
  const normalizedAuthor = normalizeThreadsAutoReplyAuthor(author) || "unknown-author";
  const normalizedComment = normalizeThreadsAutoReplyCommentIdentityText(commentText);
  return `${normalizedAuthor}|${normalizedComment}`;
}

function buildThreadsAutoReplyRecentCommentIdentityKey(
  padCode: string,
  commentAuthor: string | undefined,
  commentText: string,
) {
  return `${padCode}|${buildThreadsAutoReplyCandidateIdentity(commentAuthor, commentText)}`;
}

function buildThreadsAutoReplyRecentCommentTextKey(
  padCode: string,
  commentText: string | undefined,
) {
  const normalizedComment = normalizeThreadsAutoReplyCommentIdentityText(commentText || "");
  return normalizedComment && normalizedComment.length >= 8 ? `${padCode}|${normalizedComment}` : "";
}

function buildThreadsAutoReplyCommentKey(
  padCode: string,
  postHash: string,
  commentAuthor: string | undefined,
  commentText: string,
) {
  return hashString(`${padCode}|${postHash}|${buildThreadsAutoReplyCandidateIdentity(commentAuthor, commentText)}`, 32);
}

function normalizeThreadsAutoReplyAuthor(raw: string | undefined | null): string {
  const text = normalizeSingleLine(String(raw || ""));
  const username = normalizeThreadsProfileUsername(text)
    || normalizeThreadsProfileUsername(text.match(/^@?([A-Za-z0-9._]{3,30})(?:\s|$)/)?.[1] || "");
  return username ? username.toLowerCase() : "";
}

function mergeThreadsAutoReplyOwnIdentifiers(...groups: Array<Array<string | undefined | null> | undefined>): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const group of groups) {
    for (const value of group || []) {
      const normalized = normalizeThreadsAutoReplyAuthor(value);
      if (!normalized || seen.has(normalized)) continue;
      seen.add(normalized);
      result.push(normalized);
    }
  }
  return result;
}

function isThreadsAutoReplyOwnAuthor(author: string | undefined, ownIdentifiers: string[] = []): boolean {
  const normalized = normalizeThreadsAutoReplyAuthor(author);
  if (!normalized) return false;
  return ownIdentifiers.some((own) => normalizeThreadsAutoReplyAuthor(own) === normalized);
}

function isThreadsAutoReplyUsablePostPreview(text: string): boolean {
  const compact = normalizeSingleLine(text);
  if (!compact) return false;
  if (isThreadsAutoReplyIgnoredText(compact)) return false;
  if (!/[\p{L}\p{N}]/u.test(compact)) return false;
  return compact.length >= 4;
}

function extractThreadsAutoReplyLikelyOwnAuthorsFromUiXml(uiXml: string): string[] {
  if (!uiXml) return [];
  const username = extractThreadsProfileUsernameFromUiXml(uiXml);
  return username ? mergeThreadsAutoReplyOwnIdentifiers([username]) : [];
}

export function rememberThreadsAutoReplyComment(input: {
  padCode: string;
  postHash: string;
  commentAuthor?: string;
  commentText: string;
  replyText: string;
}) {
  const entries = readThreadsAutoReplyHistory();
  const key = buildThreadsAutoReplyCommentKey(input.padCode, input.postHash, input.commentAuthor, input.commentText);
  const commentIdentityKey = buildThreadsAutoReplyRecentCommentIdentityKey(input.padCode, input.commentAuthor, input.commentText);
  const next = entries.filter((entry) => entry.key !== key);
  next.push({
    key,
    padCode: input.padCode,
    postHash: input.postHash,
    commentIdentityKey,
    commentAuthor: normalizeThreadsAutoReplyAuthor(input.commentAuthor) || undefined,
    commentPreview: normalizeSingleLine(input.commentText).slice(0, 80),
    replyPreview: normalizeSingleLine(input.replyText).slice(0, 80),
    repliedAt: new Date().toISOString(),
  });
  writeThreadsAutoReplyHistory(next);
}

function isThreadsAutoReplyForcedVisibleFallbackCandidate(item: ThreadsAutoReplyCandidate): boolean {
  if (process.env.THREADS_AUTO_REPLY_FORCE_VISIBLE_REPLY !== "1") return false;
  const forcedVisibleFallbackText = normalizeSingleLine(
    process.env.THREADS_AUTO_REPLY_FORCE_VISIBLE_REPLY_FALLBACK_TEXT || "",
  ).toLowerCase();
  return Boolean(forcedVisibleFallbackText)
    && normalizeSingleLine(item.text).toLowerCase() === forcedVisibleFallbackText
    && String(item.debugReason || "").includes("force_visible_reply_fallback");
}

function isValidThreadsAutoReplyReplyPoint(point: { x: number; y: number } | undefined | null): point is { x: number; y: number } {
  return Boolean(point && Number.isFinite(point.x) && Number.isFinite(point.y) && point.x > 0 && point.y > 0);
}

function summarizeThreadsAutoReplyCandidatesForLog(candidates: ThreadsAutoReplyCandidate[], limit = 8) {
  return candidates.slice(0, Math.max(0, limit)).map((item) => ({
    text: item.text,
    author: item.author,
    normalizedAuthor: normalizeThreadsAutoReplyAuthor(item.author),
    score: item.score,
    replyPoint: item.replyPoint,
    debugReason: item.debugReason,
  }));
}

export function finalizeThreadsAutoReplyCandidates(input: {
  padCode: string;
  postHash: string;
  postPreview: string;
  candidates: ThreadsAutoReplyCandidate[];
  repliedKeys: Set<string>;
  repliedCommentIdentityKeys?: Set<string>;
  repliedCommentTextKeys?: Set<string>;
  ownIdentifiers?: string[];
}) {
  const normalizedPostPreview = normalizeSingleLine(input.postPreview).replace(/\s+/g, "");
  const seen = new Set<string>();
  return input.candidates
    .filter((item) => isValidThreadsAutoReplyReplyPoint(item.replyPoint))
    .filter((item) => Boolean(normalizeThreadsAutoReplyAuthor(item.author)))
    .filter((item) => !isThreadsAutoReplyIgnoredText(item.text))
    .filter((item) => !isThreadsAutoReplyOwnAuthor(item.author, input.ownIdentifiers || []))
    .filter((item) => {
      const normalizedCandidate = normalizeSingleLine(item.text).replace(/\s+/g, "");
      return !normalizedPostPreview
        || normalizedCandidate.length < 8
        || (
          normalizedCandidate !== normalizedPostPreview
          && !normalizedPostPreview.includes(normalizedCandidate)
          && !normalizedCandidate.includes(normalizedPostPreview.slice(0, 30))
        );
    })
    .filter((item) => {
      const identity = buildThreadsAutoReplyCandidateIdentity(item.author, item.text);
      if (seen.has(identity)) return false;
      seen.add(identity);
      return true;
    })
    .map((item) => ({
      ...item,
      author: normalizeThreadsAutoReplyAuthor(item.author) || undefined,
      key: buildThreadsAutoReplyCommentKey(input.padCode, input.postHash, item.author, item.text),
    }))
    .filter((item) => !item.key || !input.repliedKeys.has(item.key))
    .filter((item) => !input.repliedCommentIdentityKeys?.has(
      buildThreadsAutoReplyRecentCommentIdentityKey(input.padCode, item.author, item.text),
    ))
    .filter((item) => {
      const textKey = buildThreadsAutoReplyRecentCommentTextKey(input.padCode, item.text);
      return !textKey || !input.repliedCommentTextKeys?.has(textKey);
    });
}

function extractThreadsAutoReplyVisibleTexts(uiXml: string): string[] {
  const nodes = uiXml.match(/<node\b[^>]*>/g) ?? [];
  const values: string[] = [];
  for (const node of nodes) {
    const center = parseBoundsCenter(getXmlAttr(node, "bounds"));
    if (center && (center.y < 150 || center.y > 1360)) continue;
    for (const raw of [
      decodeXmlAttr(getXmlAttr(node, "text")),
      decodeXmlAttr(getXmlAttr(node, "content-desc")),
    ]) {
      const text = normalizeSingleLine(raw);
      if (!text) continue;
      values.push(text);
    }
  }
  const seen = new Set<string>();
  return values.filter((value) => {
    const key = value.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function extractThreadsAutoReplyVisibleComments(
  uiXml: string,
  screenshotUrl: string,
  ownIdentifiers: string[] = [],
): ThreadsAutoReplyCandidate[] {
  const nodes = uiXml.match(/<node\b[^>]*>/g) ?? [];
  const comments: ThreadsAutoReplyCandidate[] = [];
  const seen = new Set<string>();
  const textNodes = nodes
    .map((node) => {
      const rect = parseBoundsRect(getXmlAttr(node, "bounds"));
      const text = normalizeSingleLine([
        decodeXmlAttr(getXmlAttr(node, "text")),
        decodeXmlAttr(getXmlAttr(node, "content-desc")),
      ].filter(Boolean).join(" "));
      return rect && text ? { rect, text } : null;
    })
    .filter((item): item is { rect: NonNullable<ReturnType<typeof parseBoundsRect>>; text: string } => Boolean(item));

  const findAuthorForRect = (rect: NonNullable<ReturnType<typeof parseBoundsRect>>): string | undefined => {
    const centerY = Math.round((rect.top + rect.bottom) / 2);
    const candidates = textNodes
      .filter((item) => item.rect.bottom <= centerY + 8)
      .filter((item) => item.rect.bottom >= centerY - 180)
      .map((item) => ({
        author: normalizeThreadsProfileUsername(item.text),
        dy: Math.abs(item.rect.bottom - rect.top),
        leftDelta: Math.abs(item.rect.left - rect.left),
      }))
      .filter((item): item is { author: string; dy: number; leftDelta: number } => Boolean(item.author))
      .sort((a, b) => a.dy - b.dy || a.leftDelta - b.leftDelta);
    return candidates[0]?.author;
  };

  for (const node of nodes) {
    const rect = parseBoundsRect(getXmlAttr(node, "bounds"));
    if (!rect) continue;
    const centerY = Math.round((rect.top + rect.bottom) / 2);
    // Comment detail pages can place the first visible visitor comment well
    // above the media/post action row. Keep the lower cutoff, but do not
    // discard mid-screen comments; otherwise the automation reaches the
    // correct page and still reports zero candidates.
    if (centerY < 260 || centerY > 1510) continue;
    if (rect.width < 28 || rect.height < 16) continue;

    const text = normalizeSingleLine([
      decodeXmlAttr(getXmlAttr(node, "text")),
      decodeXmlAttr(getXmlAttr(node, "content-desc")),
    ].filter(Boolean).join(" "));
    if (isThreadsAutoReplyIgnoredText(text)) continue;
    if (/新增到串文|Add to thread|熱門|热门|查看翻譯|查看翻译/i.test(text)) continue;

    const author = findAuthorForRect(rect);
    if (!author) continue;
    if (isThreadsAutoReplyOwnAuthor(author, ownIdentifiers)) continue;
    const key = buildThreadsAutoReplyCandidateIdentity(author, text);
    if (seen.has(key)) continue;
    seen.add(key);

    comments.push({
      text,
      author,
      score: 0,
      replyPoint: {
        x: Math.round(BASE_SCREEN.width * 0.34),
        y: Math.min(
          Math.round(BASE_SCREEN.height * 0.90),
          Math.max(rect.bottom + 64, rect.bottom + Math.round(rect.height * 1.15)),
        ),
      },
      sourceScreenshotUrl: screenshotUrl,
      debugReason: "thread_detail_visual:auto_reply_comment_target",
    });
  }

  return comments;
}

function resolveThreadsAutoReplyVisionModels(): string[] {
  const config = readRuntimeApiConfig();
  const rawValues = [
    config.llmFreeModelPriorityOrder,
    config.llm_free_model_priority_order,
    config.llmModelPriorityOrder,
    config.llm_model_priority_order,
    config.llmPaidModelPriorityOrder,
    config.llm_paid_model_priority_order,
    config.llmDefaultModel,
    config.llm_default_model,
    config.llmDefaultModelGpt,
    config.llm_default_model_gpt,
  ];
  const parsed = rawValues
    .flatMap((value) => String(value || "").split(/[,\n]/))
    .map((model) => normalizeSingleLine(model))
    .filter(Boolean);
  const defaults = ["google/gemini-3-flash-preview", "google/gemini-3.5-flash", "gemini-3-flash-preview", "gemini-3.5-flash", "xai/grok-4.3"];
  const seen = new Set<string>();
  const unique = [...parsed, ...defaults].filter((model) => {
    const key = model.toLowerCase();
    if (!model || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  const score = (model: string) => {
    const lower = model.toLowerCase();
    if (/gemini.*flash/.test(lower)) return 0;
    if (/gemini/.test(lower)) return 1;
    if (/vision|vl|ocr/.test(lower)) return 2;
    if (/grok|xai/.test(lower)) return 4;
    return 3;
  };
  return unique.sort((a, b) => score(a) - score(b));
}

async function callThreadsAutoReplyVisionOcrModel(
  prompt: string,
  inlineData: { data: string; mimeType?: string },
  signal?: AbortSignal,
  options: { maxTokens?: number; perModelTimeoutMs?: number } = {},
): Promise<string> {
  const config = readRuntimeApiConfig();
  const apiKey = normalizeSingleLine(config.geminiTextKey || config.geminiKey || config.zhanhuKey || process.env.GEMINI_TEXT_API_KEY || process.env.GEMINI_API_KEY || "");
  const baseUrl = normalizeSingleLine(config.geminiTextEndpoint || config.geminiEndpoint || config.zhanhuEndpoint || "");
  if (!apiKey || !baseUrl) throw new Error("文字視覺 API 未設定");

  const endpoint = `${baseUrl.replace(/\/+$/, "")}/chat/completions`;
  const models = resolveThreadsAutoReplyVisionModels();
  let lastError: unknown;
  const perModelTimeoutMs = Math.max(3_000, Math.min(30_000, Math.round(options.perModelTimeoutMs || 7_000)));
  const maxTokens = Math.max(20, Math.min(900, Math.round(options.maxTokens || 900)));
  for (const model of models) {
    if (signal?.aborted) throw new Error("文字視覺 OCR 已取消");
    const modelController = new AbortController();
    const timeout = globalThis.setTimeout(() => modelController.abort(), perModelTimeoutMs);
    const abortForwarder = () => modelController.abort();
    signal?.addEventListener("abort", abortForwarder, { once: true });
    try {
      const body = JSON.stringify({
        model,
        messages: [{
          role: "user",
          content: [
            { type: "text", text: prompt },
            {
              type: "image_url",
              image_url: {
                url: `data:${inlineData.mimeType || "image/jpeg"};base64,${inlineData.data}`,
              },
            },
          ],
        }],
        max_tokens: maxTokens,
        temperature: 0,
      });
      const response = await proxiedFetch(
        endpoint,
        {
          "Content-Type": "application/json",
          Authorization: `Bearer ${apiKey}`,
        },
        body,
        modelController.signal,
      );
      const text = await response.text().catch(() => "");
      if (!response.ok) {
        throw new Error(`文字視覺模型 ${model} 呼叫失敗 (${response.status}): ${text.slice(0, 180)}`);
      }
      const data = JSON.parse(text);
      const content = data?.choices?.[0]?.message?.content;
      const output = typeof content === "string"
        ? content
        : Array.isArray(content)
          ? content.map((part: any) => part?.text || "").join("")
          : "";
      if (normalizeSingleLine(output)) return output;
      throw new Error(`文字視覺模型 ${model} 未返回文字`);
    } catch (error) {
      lastError = error;
    } finally {
      globalThis.clearTimeout(timeout);
      signal?.removeEventListener("abort", abortForwarder);
    }
  }
  throw lastError instanceof Error ? lastError : new Error(String(lastError || "文字視覺模型呼叫失敗"));
}

async function callThreadsAutoReplyDirectMultimodalModel(
  prompt: string,
  inlineData: { data: string; mimeType?: string },
  signal?: AbortSignal,
  options: { maxTokens?: number; model?: string } = {},
): Promise<string> {
  const config = readRuntimeApiConfig();
  const apiKey = normalizeSingleLine(config.gptKey || config.geminiTextKey || "");
  const baseUrl = normalizeSingleLine(config.gptEndpoint || config.geminiTextEndpoint || "");
  if (!apiKey || !baseUrl) throw new Error("OpenAI 兼容多模態端點未設定");
  const modelCandidates = [
    ...String(options.model || config.llmModelPriorityOrder || config.llm_model_priority_order || resolvePublishVerifyModel() || "")
    .split(/[,\n]/)
    .map((item) => normalizeSingleLine(item))
      .filter(Boolean),
    "google/gemini-3.5-flash",
    "google/gemini-3-flash-preview",
    "gemini-3.5-flash",
    "gemini-3-flash-preview",
    "xai/grok-4.3",
  ];
  const modelScore = (candidate: string) => {
    const lower = candidate.toLowerCase();
    if (/grok|xai/.test(lower)) return 0;
    if (/gemini-3\.1-pro/.test(lower)) return 1;
    if (/gemini.*flash/.test(lower) && !/gemini-3\.5-flash/.test(lower)) return 2;
    if (/gemini-3\.5-flash/.test(lower)) return 5;
    return 3;
  };
  const seenModels = new Set<string>();
  const model = [...modelCandidates]
    .filter((candidate) => {
      const key = candidate.toLowerCase();
      if (!candidate || seenModels.has(key)) return false;
      seenModels.add(key);
      return true;
    })
    .sort((a, b) => modelScore(a) - modelScore(b))[0] || "xai/grok-4.3";
  const response = await fetch(`${baseUrl.replace(/\/+$/, "")}/chat/completions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model,
      messages: [{
        role: "user",
        content: [
          { type: "text", text: prompt },
          {
            type: "image_url",
            image_url: {
              url: `data:${inlineData.mimeType || "image/jpeg"};base64,${inlineData.data}`,
            },
          },
        ],
      }],
      temperature: 0,
      max_tokens: Math.max(80, Math.min(600, Math.round(options.maxTokens || 220))),
    }),
    signal,
  });
  if (!response.ok) {
    const text = await response.text().catch(() => "");
    throw new Error(`direct-multimodal ${response.status}: ${text.slice(0, 200)}`);
  }
  const data = await response.json().catch(() => null);
  const content = data?.choices?.[0]?.message?.content;
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    return content.map((item: any) => {
      if (typeof item === "string") return item;
      if (item?.type === "text") return String(item.text || "");
      return "";
    }).join("");
  }
  return "";
}

async function getInlineDataFromUrlOrLocalFile(input: string): Promise<{ mimeType: string; data: string } | null> {
  const inline = await getInlineData(input).catch(() => null);
  if (inline) return inline;
  const localPath = input.startsWith("file://")
    ? decodeURIComponent(new URL(input).pathname).replace(/^\/([A-Za-z]:\/)/, "$1")
    : input;
  if (!localPath || /^https?:\/\//i.test(localPath) || !fs.existsSync(localPath)) return null;
  const ext = path.extname(localPath).toLowerCase();
  const mimeType = ext === ".png"
    ? "image/png"
    : ext === ".webp"
      ? "image/webp"
      : "image/jpeg";
  return {
    mimeType,
    data: fs.readFileSync(localPath).toString("base64"),
  };
}

async function detectThreadsProfileUsernameByVision(screenshotUrl: string | undefined): Promise<string | null> {
  if (!screenshotUrl) return null;
  const inlineData = await getInlineDataFromUrlOrLocalFile(screenshotUrl).catch(() => null);
  if (!inlineData) return null;
  const prompt = `Read this Threads profile screenshot and return JSON only: {"username":"profile owner username"}.

Rules:
- Extract the profile owner username shown near the top of the profile page.
- Do not return names from posts, replies, comments, suggested cards, buttons, or bottom tabs.
- If the profile owner username is not visible, return {"username":""}.`;
  const parseUsername = (raw: string) => {
    const text = extractText(raw);
    const jsonText = text.match(/\{[\s\S]*\}/)?.[0] || "";
    if (jsonText) {
      try {
        const parsed = JSON.parse(jsonText);
        const username = normalizeThreadsProfileUsername(String(parsed?.username || ""));
        if (username) return username;
      } catch {
        // Fall through to loose parsing below.
      }
    }
    return normalizeThreadsProfileUsername(normalizeSingleLine(text));
  };
  const request = createTimeoutSignal(9_000);
  try {
    const raw = await callThreadsAutoReplyDirectMultimodalModel(
      prompt,
      inlineData,
      request.signal,
      { maxTokens: 80 },
    );
    return parseUsername(raw) || null;
  } catch {
    try {
      const raw = await callThreadsAutoReplyVisionOcrModel(prompt, inlineData, request.signal, {
        maxTokens: 80,
        perModelTimeoutMs: 4_500,
      });
      return parseUsername(raw) || null;
    } catch {
      return null;
    }
  } finally {
    request.cleanup();
  }
}

